window.__D("text/torat-shmuel/c057",{"p":[[2001910374,"בלק\"ת בד\"ה כי ביום הזה יכפר הא' בפ' אחרי בפ\"ג<sup data-n=\"3738\">56</sup> וז\"ל וכמ\"ש בזהר דבמח' אחת ברא (הקב\"ה) את העולמות<sup data-n=\"3739\">57</sup> לפי שהוא ית' צופה ומביט עד סוף כל הדורות<sup data-n=\"3740\">58</sup> מראש<sup data-n=\"3741\">59</sup>, וע' בד\"ה ושמתי כדכד<sup data-n=\"3742\">60</sup> דרוש הראשון פ\"ב ובכ\"ד, וא\"כ מיד כשעלו כל העולמות במחשבה להבראות הרי כבר נגמרו ונשלמו בריאותם לפניו ית'), וזהו בחי' מאמר דבראשית שהוא בחי' הכלל בחי' מחשבה שכאשר עלה במחשבתו נבראו כל הנבראים, וזהו בראשית נמי מאמר הוא פי' שהוא בחי' מאמר א' מאמר כללי שכולל כל הע\"מ, וא\"כ צ\"ל למה הי' צריך עוד ט' מאמרות פרטיות מאחר שבמא' א' דבראשית נברא כל הנבראים, והענין הוא דהנה אם הי' בריאת העולם מבחי' מאמר א' הי' העולם בטל במציאות ולא בחי'<sup data-n=\"3743\">61</sup> מציאת יש ודבר נפרד כלל, כ\"א הי' הכל בטל בתכלית כו', ולא הי' שום בחירה כו'.\nד) <b>ויובן</b> זה היטב, כי הנה כלל ופרט הוא בחי' מחשבה ודבור, והנה אנו רואים שמחשבתו של האדם היא מתאחדת בתכלית עם הנפש שהיא בחי' לבוש הפנימי<sup data-n=\"3744\">62</sup> של הנפש, אבל בחי' הדבור נעשה נפרד מן האדם, כך הנה יובן למעלה שכאשר הי' בריאת העולם מבחי' מח' הי' העולם בבחי' ביטול במציאות אבל כדי שיהי' העולם יש ודבר נפרד זהו דוקא ע\"י בחי' הדבור שכמו שהדבור הוא נפרד ויוצא לחוץ (והגם שאין לך דבר שחוץ ממנו ית', מ\"מ דברה תורה כלשון בנ\"א<sup data-n=\"3745\">63</sup> לשכך את האזן<sup data-n=\"3746\">64</sup> מה שהיא יכולה לשמוע, כמ\"ש בסש\"ב בשער היחוד והאמונה פ\"י וע' בד\"ה וככה תאכלו<sup data-n=\"3747\">65</sup> אותו בהוכחות וראיות ברורות שגם דבור האדם אינו נפרד באמת רק שנדמה שנעשה נפרד), כך הוא ההתהוות שמן הדבור הוא בחי' נבראים נפרדים (ופעולת המאמר א' שהי' תחלה מבחי' מחשבה בחי' כלל כדי שאף שנברא העולם ליש ודבר נפרד אעפ\"כ יהי' יכול להיות בחי' הביטול בעולם כו'), וא\"כ מובן שעכשיו שנברא בע\"מ מבחי' דבור נעשה העולם ליש ודבר נפרד, ואעפ\"כ יש בחי' עולמות שנבראו מבחי' המאמר א' בחי' מחשבה שלא נפרטו אח\"כ בבחי' דבור והם בחי' עלמא דאתכסי' שנודע מענין עלמא",[["3738","56","<b>בלק\"ת . . בפ' אחרי בפ\"ג</b>: כו, סע\"ב ואילך."],["3739","57","<b>דבמח' אחת ברא . . העולמות</b>: ראה זהר שמות כ, א. שם תוספות רעו, סע\"ב. סידור שער התפלה יח, סע\"ד. סהמ\"צ להצ\"צ ע' קעח ואילך. מאמרי אדה\"א קונטרסים ע' תלא. וש\"נ."],["3740","58","<b>צופה ומביט . . הדורות</b>: נוסח ברכת זכרונות."],["3741","59","<b>מראש</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381295\" data-slug=\"likkutei-torah\" data-id=\"4001381295\">לקו\"ת שם</a>: וקורא הדורות מראש — ישעי' מא, ד."],["3742","60","<b>בד\"ה ושמתי כדכד</b>: לקו\"ת פ' ראה כד סע\"ד ואילך."],["3743","61","<b>ולא בחי'</b>: אוצ\"ל: ולא הי' בבחי'."],["3744","62","<b>שמחשבתו של האדם . . לבוש הפנימי</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י הערה 105."],["3745","63","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["3746","64","<b>לשכך את האזן</b>: ראה (בנוסף לשער היחוד והאמונה רפ\"י המובא בפנים). מכילתא יתרו יט, יח. תנחומא שם יג. אגה\"ק ס\"ו קי, א. סכ\"ט קמט, ב. וראה גם ע\"ח שער ד שער אח\"פ רפ\"ב."],["3747","65","<b>בד\"ה וככה תאכלו</b>: תרל\"ז פע\"ט. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 28."]]],[2001910375,"דאתכסי' ועדאת\"ג<sup data-n=\"3748\">66</sup> שנק' ים ויבשה<sup data-n=\"3749\">67</sup>, והנה ארז\"ל כל מה שיש ביבשה<sup data-n=\"3750\">68</sup> יש בים, וההפרש בין ברואי' שבים לברואי' שביבשה כי הברואים שבים הם מובלעים בתוך הים ואינם יכולים לחיות זולת הים אפי' שעה א'<sup data-n=\"3751\">69</sup>, משא\"כ ברואי' שביבשה אף שהם מקבלים חיות מבחי' הארץ אעפ\"כ הם נפרדי' מן הארץ ויכולים לחיות בלא הארץ כמו כאשר הם שטים ע\"פ המים. וכך יובן למעלה שיש בחי' מלאכים ונשמות שהם מבחי' עלמא דאתכסי' ונקראים בשם נוני<sup data-n=\"3753\">71</sup> דימא<sup data-n=\"3752\">70</sup> רבא<sup data-n=\"3754\">72</sup> שהם תמיד בבחי' הביטול לאלקות, וכמ\"ש במשה<sup data-n=\"3755\">73</sup> כי מן המים משיתיהו, שהי' מבחי' עלמא דאתכסי'<sup data-n=\"3756\">74</sup> ולכן אמר ונחנו מ\"ה<sup data-n=\"3757\">75</sup> שהי' תמיד בבחי' ביטול, אבל כדי שיהי' התהוות העולם בבחי' יש ודבר נפרד זהו ע\"י הדבור שכאשר נברא ע\"פ דבר הוי' נעשה העולם יש ודבר נפרד ויש בחי' הבחירה לבחור בטוב או להיפוך, משא\"כ אם הי' מבחי' מאמר א' בחי' מחשבה לא הי' בחירה כלל, וזהו כדי ליפרע<sup data-n=\"3758\">76</sup> מן הרשעים שמאבדין את העולם שנברא בע\"מ דוקא ולא במאמר א' דאם הי' נברא ממאמר א' לא הי' מציאות<sup data-n=\"3759\">*77</sup> נפרדים כלל כ\"א הי' הכל בבחי' ביטול במציאות, אבל כשנברא בע\"מ בבחי' דבור הנה מבחי' הדבור נברא העולם ליש ודבר נפרד ויש בחי' הבחירה לבחור בטוב והרשעים שבוחרים ברע הרי הם מאבדין את העולם, וזהו שנברא דוקא בע\"מ כי ע\"י הע\"מ נמצא בחי' הבחירה בעולם והרשעים שבוחרים ברע נפרעין מהם על שמאבדין את העולם שנברא בע\"מ כו', וע\"פ הקבלה בחי' הכלל הוא בחי' עולם העקודים<sup data-n=\"3760\">77</sup>, ששם עקוד כל האורות בכלי אחד<sup data-n=\"3761\">78</sup> כו' כמ\"ש במ\"א.",[["3748","66","<b>עלמא דאתכסי' . . ועדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["3749","67","<b>עלמא דאתכסי' . . ועדאת\"ג . . ים ויבשה</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 104."],["3750","68","<b>כל מה שיש ביבשה</b>: חולין קכז, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a> הערה 770."],["3751","69","<b>הברואים שבים . . אפילו שעה א'</b>: ראה ע\"ז ג, ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 34."],["3753","71","<b>ונשמות . . נוני דימא</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 32 בשם הזהר — ראה ביאוה\"ז בשלח מא, סע\"ג [ושם: דמשמע בזהר בכמה דוכתי]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540223\" data-slug=\"torat-chaim\" data-id=\"2300540223\">תו\"ח בשלח ח\"א רז, א</a>. וש\"נ. סה\"מ תרל\"א ותרל\"ט שבהערה 73. לקמן מאמר ד\"ה כל אשר חפץ ה' עשה על יד הערה 36."],["3752","70","<b>מלאכים . . נוני דימא</b>: ראה זהר בשלח מח, ב ובמק\"מ שם. ביאורי הזהר בשלח מא, סע\"ג. מב, ג. ולהצ\"צ כרך א ע' רח. ע' ריב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380110\" data-slug=\"likkutei-torah\" data-id=\"4001380110\">לקו\"ת צו ח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380150\" data-slug=\"likkutei-torah\" data-id=\"4001380150\">שמיני יח, א</a>."],["3754","72","<b>נוני דימא רבא</b>: זהר בלק קפח, א."],["3755","73","<b>נוני דימא רבא . . במשה</b>: ראה גם סה\"מ תרכ\"ז כאן ע' רפד. תרל\"א ח\"א ע' רסה. תרל\"ט ח\"ב ריש ע' תח. ע' תקפג. תרנ\"ב ע' מט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550171\" data-slug=\"torat-chaim\" data-id=\"2300550171\">תו\"ח יתרו ח\"ב רסה, א</a>."],["3756","74","<b>כי מן המים משיתיהו . . דאתכסי'</b>: שמות ב, י. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>."],["3757","75","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 140."],["3758","76","<b>כדי ליפרע</b>: לעיל פ\"ב על יד הערה 37 להפרע. ותיבת כדי לא הובא שם. ראה גם לקמן מאמר ד\"ה בעש\"מ נבה\"ע הערה 3."],["3759","*77","<b>מציאות</b>: בהעתקה ראשונה [ראה לעיל הערה 1] כאן: מציאת. וכ\"ה בסה\"מ תרכ\"ז כאן ע' רפד."],["3760","77","<b>הכלל . . עולם העקודים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650111\" data-slug=\"or-hatorah-hb\" data-id=\"8316650111\">אוה\"ת</a> ישעי' כרך ב ס\"ע תתמ."],["3761","78","<b>העקודים ששם עקוד . . בכלי אחד</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370043\" data-slug=\"torah-or\" data-id=\"3901370043\">תו\"א נח י, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540165\" data-slug=\"torat-chaim\" data-id=\"2300540165\">תו\"ח וארא ח\"א נב, ד</a>. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274. (לקמן בחלק ההנחות) הנחה ד\"ה בעשרה מאמרות נברא העולם על יד הערה 61."]]],[2001910376,"ה) <b>וכדי</b> ליתן שכר טוב לצדיקים שמקיימין את העולם שנברא בע\"מ, פי' כי כל עבודת הצדיקים הוא להמשיך בחי' מאמר א' בחי' מאמר הכללי בט\"מ<sup data-n=\"3762\">79</sup>, שזהו מ\"ש ומי כעמך כישראל<sup data-n=\"3763\">80</sup> גוי אחד בארץ שאפי' בארץ שנעשה יש ודבר נפרד אעפ\"כ יהי' נמצא בארץ בחי' אחד<sup data-n=\"3764\">81</sup> דהיינו בחי' מאמר אחד כו' מאמר הכללי.\n<b>ועוי\"ל</b> בפי' המשנה בע\"מ נבה\"ע, והלא במאמר אחד יכול כו' אלא כו' כפשוטו שכאשר נברא בע\"מ הוא חשוב יותר מכמו שהי' נברא במאמר אחד, דאילו לפי משנת\"ל<sup data-n=\"3765\">82</sup> המאמר אחד הוא גבוה יותר, רק שאם הי' נברא במא' א' לא הי' בחירה ולא הי' שכר ועונש, ולכן כדי להפרע כו' וליתן שכר נפרטו בע\"מ כו', שפשט לשון המשנה אינו מורה כך, כ\"א שהי' יכול לברוא במא' אחד, ועכשיו שנברא בע\"מ הרי הוא חשוב יותר והוא בכדי להפרע מן הרשעים שמאבדי' חפץ יקר שנברא בעשרה מאמרות, וכדי ליתן שכר טוב לצדיקים שמקיימין כו', כפשוטו שכאשר החפץ הוא יקר יותר מגיע להמקיימו שכר יותר כו'. והענין הוא דהנה ע\"מ הוא כנגד ע\"ס<sup data-n=\"3766\">83</sup> וכמ\"ש ה' בחכמה יסד ארץ כונן שמים בתבונה<sup data-n=\"3767\">84</sup> בדעתו כו'<sup data-n=\"3768\">85</sup> שהם בחי' חב\"ד, וכתי' כי אמרתי עולם חסד יבנה<sup data-n=\"3769\">86</sup>, וכן זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"3770\">87</sup>, וכדפי' בזח\"ג שמיני דל\"ט ע\"א<sup data-n=\"3771\">88</sup>, וכמארז\"ל בחגיגה בעשרה דברים<sup data-n=\"3772\">89</sup> ברא הקב\"ה את עולמו בחכ' ובתבונה ובדעת בכח ובגערה כו', שהתחדשות התהוות העולמות זהו ע\"י ע\"ס דוקא, והיינו לפי שכל השפעה צריך להיות נמשך ע\"י עשר בחי' אלו<sup data-n=\"3773\">90</sup>, ומבשרי אחזה<sup data-n=\"3774\">91</sup> שגם בבחי' השפעת שכל לזולתו צריך ג\"כ שיומשך ע\"י עשר בחי' אלו, והיינו שבבחי' חב\"ד צריך תחלה להשכיל ולהתבונן בכח חכמתו ובינתו בשכל ההשכלה ההיא ולהעמיק בדעתו היטב באיכות ומהות ההשכלה, וגם",[["3762","79","<b>בט\"מ</b>: בסה\"מ תרכ\"ז כאן ע' רפד: בט' מאמרות."],["3763","80","<b>ומי כעמך כישראל</b>: שמו\"ב ז, כג."],["3764","81","<b>שאפי' בארץ . . בחי' אחד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו\"א וישב כז, סע\"ד</a>. לעיל מאמר ד\"ה כי תשא ובהערה 21."],["3765","82","<b>משנת\"ל</b>: ספ\"ב ואילך."],["3766","83","<b>ע\"מ הוא כנגד ע\"ס</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380652\" data-slug=\"likkutei-torah\" data-id=\"4001380652\">לקו\"ת מטות פב, רע\"ג</a> ובהנסמן שם. מאמרי אדה\"א דברים ח\"ג ע' תתפח. שער האמונה סא, א ובהערה 6. סה\"מ תרכ\"ז ע' רמט. לעיל מאמר ד\"ה וירא ישראל את היד הגדולה ספ\"ב."],["3767","84","<b>ה' בחכ' . . בתבונה</b>: משלי ג, יט. ראה גם לקמן ובהערה 100."],["3768","85","<b>בדעתו כו'</b>: משלי שם כ."],["3769","86","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["3770","87","<b>זכור רחמיך . . מעולם המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם לעיל מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 32 ואילך."],["3771","88","<b>דל\"ט ע\"א</b>: וכ\"ה לקמן במאמר ד\"ה בעשרה מאמרות נבה\"ע על יד הערה 24. אבל לעיל (במאמר ד\"ה שלש רגלים תחוג לי) שם: דל\"ח ע\"א. ואולי גם כאן צ\"ל כן."],["3772","89","<b>וכמארז\"ל בחגיגה בעשרה דברים</b>: ראה שם יב, א. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זכור את יום השבת ובהערה 49."],["3773","90","<b>שכל השפעה . . ע\"י עשר בחי' אלו</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450373\" data-slug=\"or-hatorah-hb\" data-id=\"8316450373\">אוה\"ת</a> ישעי' כרך ב ע' תתמא: שכ' באו\"ת מהמגיד נ\"ע שכל השפעה א\"א להיות בלתי עשר בחי' אלו ע\"ש בד\"ה אין התורה מתקיימת אלא במי שממית עצמו עלי' [במהדורת קה\"ת קיא, ד] והובא אצלי בפ' חוקת ע\"פ זאת התורה אדם כי ימות באהל [אוה\"ת חוקת ע' תתיח]. או\"ת ר\"פ חוקת מז, ג. סה\"מ תרל\"ב ח\"ב ע' תלח. וש\"נ."],["3774","91","<b>ומבשרי אחזה</b>: לשון הכתוב איוב יט, כו."]]],[2001910377,"צריך שיהי' לו אהבה ורצון בההשפעה, ודברים היוצאים מן הלב<sup data-n=\"3775\">92</sup> נכנסים ללב השומע, וכן צריך לצמצם א\"ע בכח גבורתו שיוגבל דברי ההשכלה שלא יתבללו<sup data-n=\"3776\">93</sup> הענינים מחמת האהבה והרצון שיותר ממה שהעגל רוצה לינק<sup data-n=\"3777\">94</sup> הפרה רוצה להניק ולהשפיע כו', וגם שלא יצמצם ביותר צ\"ל מדת התפארת לזווג וליחד חו\"ג<sup data-n=\"3778\">95</sup> שיהי' הרצון והצמצום ע\"ד המצוע, וכן נו\"ה הם בחי' כליות יועצות<sup data-n=\"3779\">96</sup> איך להשפיע כו', וכן בבחי' שפע הפנימי להוליד בדומה לו הנה המשכת הטפה הגשמיות היא ג\"כ ע\"י עשר בחי' אלו<sup data-n=\"3780\">97</sup> כמ\"ש במ\"א, ועד\"ז יובן שכדי שיהי' התהוות העולמות זהו ג\"כ ע\"י עשר ספירות, כי א\"א שיהי' ההשפעה כ\"א ע\"י עשר בחי' דוקא, אך בענין העשר בחי' אלו יש חילוקי מדרגות, דהנה נודע שכל מדה כלולה מיו\"ד<sup data-n=\"3781\">98</sup> ולזה אומר התנא במתניתין והלא במאמר אחד יכול להבראות, פי' מאמר אחד הוא בחי' דבר מלך שלטון שבדבר ה' שמים נעשו<sup data-n=\"3782\">99</sup> וברוח פיו כל צבאם שהיא כלולה ג\"כ מעשר ספירות כו', ולכן גם במאמר אחד יכול להבראות שגם במל' יש כל העשר ספירות, ולמה נברא בעשרה מאמרות דהיינו בע\"ס עצמן, כי מ\"ש ה' בחכ' יסד ארץ אינה חכ' שבמל', כ\"א בחי' חכמה עילאה<sup data-n=\"3783\">100</sup> ולכן אמר ה' בחכ' להורות שבחי' חכ' זו אינה בחי' חכ' תתאה לבד כ\"א בחי' חכ' עילאה, וזהו דכתי' אלה תולדות השמים והארץ כו' מלא<sup data-n=\"3784\">101</sup> בשני ווי\"ן, כמארז\"ל שהעולם על מילואו נברא<sup data-n=\"3785\">102</sup>, והיינו שנבה\"ע ע\"י ע\"ס עצמן, ולכן נברא בוויתור, וכמארז\"ל עיקר שכינה בתחתונים היתה<sup data-n=\"3786\">103</sup>, רק שע\"י חסרון הלבנה וחטא עה\"ד<sup data-n=\"3787\">104</sup> נעשה תולדת חסר, וכן ע\"י חטא הדורות סילקו השכינה למעלה מז' רקיעים עד שבא אברהם והורידה לרקיע הראשון<sup data-n=\"3788\">105</sup> כו' עד",[["3775","92","<b>ודברים היוצאים מן הלב</b>: ספר הישר לר\"ת שי\"ג. הובא בשל\"ה שער האותיות אות כ (סט, א)."],["3776","93","<b>יתבללו</b>: אוצ\"ל: יתבלבלו."],["3777","94","<b>שיותר ממה שהעגל רוצה לינק</b>: ראה פסחים קיב, א. מאמרי אדה\"א דברים ח\"א ע' רפז. וש\"נ. תו\"ח ויצא קסט, ג ובהערה 35."],["3778","95","<b>התפארת לזווג וליחד חו\"ג</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. לעיל מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 49. סה\"מ תר\"ם ח\"א ע' רלא-רלג."],["3779","96","<b>נו\"ה . . כליות יועצות</b>: ברכות סא, א. ראה זהר אד\"ז האזינו רצו, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540928\" data-slug=\"torat-chaim\" data-id=\"2300540928\">תו\"ח שמות ח\"א יד, ג</a>."],["3780","97","<b>המשכת הטפה . . ע\"י עשר בחי' אלו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380446\" data-slug=\"likkutei-torah\" data-id=\"4001380446\">לקו\"ת בהעלותך לד, א</a>."],["3781","98","<b>שכל מדה כלולה מיו\"ד</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א. לקו\"ת חוקת סה, ד."],["3782","99","<b>שבדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3783","100","<b>ה' בחכ' . . חכמה עילאה</b>: ראה גם סה\"מ תרל\"ח ע' ע."],["3784","101","<b>אלה תולדות השמים והארץ . . מלא</b>: בראשית ב, ד. ראה ב\"ר פי\"ב ו. שמו\"ר פ\"ל, ג. סה\"מ תרל\"ו ח\"ב ע' שיז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' יב. סה\"מ תרכ\"ט ע' שטז. וש\"נ. תרל\"ב ח\"ב ע' תלט. המשך תער\"ב ח\"א ע' רד. סה\"מ תרפ\"ט ע' 76. לעיל מאמר ד\"ה הוא אהרן ומשה על יד הערה 147 ואילך."],["3785","102","<b>שהעולם על מילואו נברא</b>: ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם). ראה גם תו\"ח ח\"ש קלד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש בראשית כרך כה ע' 14</a> ואילך."],["3786","103","<b>עיקר שכינה בתחתונים היתה</b>: ראה ב\"ר פי\"ט, ז. וש\"נ. שהש\"ר רפ\"ה. סה\"מ תר\"ם ח\"א ע' רנח. וש\"נ."],["3787","104","<b>חסרון הלבנה וחטא עה\"ד</b>: במדרש שם: שחטא אדה\"ר. ראה סה\"מ מלוקט ג' ע' פה. וש\"נ."],["3788","105","<b>אברהם והורידה לרקיע הראשון</b>: כנראה הכוונה מלמעלה למטה. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 106. מאמרי אדה\"א בראשית ע' רלד. דברים ח\"ב ע' שעא. סה\"מ תר\"ם ח\"א ע' תי. תרע\"ח ע' רעא."]]],[2001910378,"משה שהורידה למטה כמ\"ש וירד ה' על ה\"ס<sup data-n=\"3789\">106</sup>, וע\"י בחי' הבירור שמזככים העולם יהי' לע\"ל תולדות מלא כמ\"ש אלה תולדות פרץ מלא<sup data-n=\"3790\">107</sup> בשני ווי\"ן, ולכן כתי' ושמחת עולם על ראשם<sup data-n=\"3791\">108</sup> שיהי' השמחה בעולם מחמת הגילוי שיומשך המשכת גילוי אלקות בעולם עד שיהי' גילוי שכינה למטה כמו קודם החטא, וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"3792\">109</sup> והיו עיניך רואות כו', וזהו כדי להפרע מן הרשעים שמאבדי' את העולם שנברא בע\"מ היינו שנברא בוויתור ע\"י בחי' ע\"ס עצמן, וכמו הדורות בעוונם שסלקו השכינה עד למעלה מז' רקיעים שאבדו דבר חשוב יותר מכמו אם הי' נברא העולם ממאמר אחד לבד היינו מע\"ס שבבחי' דבור לבד, וכדי ליתן שכר טוב לצדיקים שמקיימים תומ\"צ כמ\"ש וצדקה תהי' לנו<sup data-n=\"3793\">110</sup> כי נשמור לעשות את כל המצוה שהתומ\"צ נק' בשם צדקה, ועמך כולם צדיקים<sup data-n=\"3794\">111</sup> שהפועל הצדקה נק' בשם צדיק<sup data-n=\"3795\">112</sup>, ועי\"ז הם מקיימים את העולם שנברא בע\"מ היינו שנברא בוויתור כנ\"ל, ופי' מקיימים שממשיכים למלאות החסרון כו', ולכן בגמר הבירורים יהי' הגילוי למטה כמו קודם החטא שעיקר שכינה בתחתונים היתה כו', ומפני שמקיימים העולם שנברא בע\"מ שהוא דבר חשוב יותר מכמו אם היתה נבראת במאמר אחד כו', והקיום הוא שממשיכין למלאות החסרון כו', ולכן מגיע שכר טוב יותר כו'.",[["3789","106","<b>וירד ה' על ה\"ס</b>: יתרו יט, כ."],["3790","107","<b>אלה תולדות פרץ מלא</b>: רות ד, יח [ושם: ואלה — אבל כ\"ה גם בב\"ר פי\"ב, ו]. ראה גם ב\"ר־ שמו\"ר־ וחלק מהדרושים שבהערה 101. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830241\" data-slug=\"or-hatorah-hb\" data-id=\"8158830241\">אוה\"ת בלק ע' תתקכז</a>. (ע' תתקלו)."],["3791","108","<b>ושמחת עולם על ראשם</b>: ישעי' לה, י. נא, יא."],["3792","109","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["3793","110","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ועבדתם את ה\"א ובהערה 34."],["3794","111","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["3795","112","<b>שהפועל הצדקה . . צדיק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380688\" data-slug=\"likkutei-torah\" data-id=\"4001380688\">לקו\"ת מסעי צא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">שה\"ש טז, ג</a>. סה\"מ תרל\"ח ע' תז. וש\"נ."]]],[2001910379,"<h3>אר\"א וכו' ת\"ח מרבים</h3>\n<b></b><b>בס\"ד, למא' כי תבואו כו' ושבתה דתקס\"ב</b>\n<b>א\"ר</b> אלעזר א\"ר חנינא ת\"ח מרבים שלום<sup data-n=\"3796\">1</sup> בעולם<sup data-n=\"3797\">2</sup> שנא' וכל בניך כו' ורב שלום בניך<sup data-n=\"3798\">3</sup> א\"ת בנייך אלא בוניך<sup data-n=\"3799\">4</sup>, שהם ת\"ח<sup data-n=\"3800\">5</sup> שעוסקים בבנינו ש\"ע כמארז\"ל בענין הבנאים מצד א'<sup data-n=\"3801\">6</sup> מאי בנאי' אלו ת\"ח שעוסקי' בבנינו ש\"ע, ולכאורה א\"מ הלא העולם כבר בנוי ומשוכלל כו', ויובן בהקדם מ\"ש שובי שובי השולמית (שה\"ש ז' )<sup data-n=\"3802\">7</sup> וארז\"ל בשה\"ש במקומו<sup data-n=\"3803\">8</sup>, ובפ' תולדות פס\"ו<sup data-n=\"3804\">9</sup> אומה שעושה<sup data-n=\"3805\">10</sup> שלום ביני ובין עולמי, וצ\"ל מהו\"ע השלום שעושין כו', שלכאו' אינו מובן איך יתכן ענין העדר השלום עמו ית', עד שיצטרכו לעשות שלום בינו ובין עולמו כו'. אך הענין דפי' שלום הוא לשון התחברות וא\"כ פי' שעושין שלום ביני ובין עולמי היינו שמחברים וממשיכים אוא\"ס בעולם ויתפרש זה גם מתחילת הבריאה, וכ\"ש לפי מה שנעשה אח\"כ חסרון הירח, וחטא עה\"ד והדורות שסילקו השכינה למעלה מז' רקיעי'<sup data-n=\"3807\">12</sup> כנ\"ל<sup data-n=\"3806\">11</sup>, דהנה נת\"ל<sup data-n=\"3808\">13</sup> בענין והלא במא' א' יכול להבראות, שהוא מא' כללי דבראשית<sup data-n=\"3809\">14</sup> נמי מא' הוא<sup data-n=\"3810\">15</sup>, ואם הי' נברא ממאמר א' זה היו העולמות בתכלית הביטול ע\"ד עלמא דאתכסיא<sup data-n=\"3811\">16</sup> ויותר כו', ולכן נפרטו בע\"מ בבחי' הדבור בכדי שיהי' מציאות נבראים נפרדים, בכדי",[["3796","1","<b>א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום</b>: מאמר זה הוא מאמר הב' מההמשך דמאמר ד\"ה כי תבואו וכו' ושבתה הארץ תרכ\"ז שנדפס לפנ\"ז עם הוספות. וש\"נ (והוא נדפס בסה\"מ תרכ\"ז ע' רפה-רפז — פרקים א-ה). וכאן באים המשך הפרקים ה-ז ממאמר דתרכ\"ז.\nהמאמר דתרכ\"ז נרשם עוה\"פ בבוך זה בכת\"י מעתיק — כנ\"ל בריש המאמר שנדפס לפנ\"ז. ומאמר דידן נרשם בגוכתי\"ק עד להלן רפ\"ב (היינו בהוספת פתיחה, והמשך פ\"ה נרשם כאן באריכות וכו'). ומשם ואילך הועתק עוד הפעם בכת\"י מעתיק (היינו פרקים ו-ז דהמאמר דתרכ\"ז — שהם פרקים ב-ג שבמאמר דידן).\nבבוך תרמ\"א 2086 — כת\"י מעתיק — בא כותרת על המאמר: בס\"ד פ' במדבר. אבל ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב — ועד\"ז לקמן בחלק ההנחות] הנחה ד\"ה בעשרה מאמרות ושם נרשם כותרת: ש\"פ בחקתי. והוא מקביל למאמר ד\"ה זה שנדפס להלן [אחר מאמר ד\"ה כל אשר חפץ ה' עשה], וכן בבוך תרמ\"א הנ\"ל נרשם מאמר זה להלן. ויש לציין שבהנחות כ\"ק אדמו\"ר מהורש\"ב נרשמו רק שני מאמרים מההמשך והם: א) ד\"ה כי תבואו וכו' ושבתה הארץ. ב) ד\"ה בעשרה מאמרות הנ\"ל."],["3797","2","<b>א\"ר אלעזר . . מרבים שלום בעולם</b>: סוף ברכות."],["3798","3","<b>וכל בניך כו' ורב שלום בניך</b>: ישעי' נד, יג."],["3799","4","<b>א\"ת בנייך אלא בוניך</b>: ברכות שם."],["3800","5","<b>בוניך שהם ת\"ח</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ. סה\"מ תרל\"ח ע' קנז. וש\"נ."],["3801","6","<b>הבנאים מצד א'</b>: שבת קיד, א."],["3802","7","<b>שובי שובי השולמית (שה\"ש ז )</b>: פסוק א."],["3803","8","<b>בשה\"ש במקומו</b>: שהש\"ר פ\"ז, א."],["3804","9","<b>ובפ' תולדות פס\"ו</b>: ב\"ר פס\"ו, ב."],["3805","10","<b>שעושה</b>: בסה\"מ תרכ\"ז כאן ע' קפה: שעשה. בב\"ר: שעשת. בשהש\"ר: שעשתה."],["3807","12","<b>למעלה מז' רקיעי'</b>: ראה ב\"ר פי\"ט, ז. וש\"נ. שהש\"ר רפ\"ה."],["3806","11","<b>חסרון הירח . . למעלה מז' רקיעי' כנ\"ל</b>: במאמר ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 104 ואילך (שנדפס לפנ\"ז)."],["3808","13","<b>נת\"ל</b>: במאמר ד\"ה כי תבואו וכו' ספ\"ג ואילך."],["3809","14","<b>והלא במא' א' . . דבראשית</b>: אבות רפ\"ה. בראשית א, א. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 19."],["3810","15","<b>דבראשית נמי מא' הוא</b>: ר\"ה לב, א."],["3811","16","<b>עלמא דאתכסיא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."]]],[2001910380,"שיושלם הרצון מה שעלה ברצונו בחי' הרצון דאנא אמלוך<sup data-n=\"3812\">17</sup> שענין המלוכה לא יתכן כ\"א על נבראים נפרדים<sup data-n=\"3813\">18</sup> שז\"ע עם מל' עוממות<sup data-n=\"3814\">19</sup> כמ\"ש במ\"א, וע\"י שנפרט בבחי' הדבור דע\"מ פרטי' עי\"ז נמשך שיהיו נבראים נפרדים ליש ודבר נפרד כמשנת\"ל. ואמנם צ\"ל הלא אמרו ג\"כ שנתאוה הקב\"ה להיות לו ית'<sup data-n=\"3816\">21</sup> דירה בתחתונים<sup data-n=\"3815\">20</sup>, וכמ\"ש שוקיו עמודי שש<sup data-n=\"3817\">22</sup>, וארז\"ל במד\"ר שוקיו זה העולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"3818\">23</sup>, ולמה נשתוקק ונתאוה<sup data-n=\"3819\">24</sup> זה אינו מובן, אך זה אנו יודעים שנשתוקק ונתאוה כו', ולמלאות תשוקה זו מוכרח להיות תחילה מציאות תחתונים, וזהו ע\"י שנפרט בע\"מ בבחי' הדבור כנ\"ל שעי\"ז נעשה בחי' מציאות תחתונים במעלה<sup data-n=\"3820\">25</sup> כו', אך עדיין אינו מובן איך יהי' לו ית' דירה בבחי' התחתונים במעלה, שזהו מה שנתהווה העולם ליש ודבר נפרד, הלא אין אני והוא יכולים לדור<sup data-n=\"3821\">26</sup> כו', ואיך יהי' שניהם יחד שיהי' בחי' תחתונים במעלה ועכ\"ז יהי' דירה לו ית' במקום התחתונים כו'. אך הענין הוא שזהו מ\"ש רז\"ל בפ\"ט דשבת תנאי התנה הקב\"ה עם מע\"ב אם יקיימו ישראל תורתי מוטב, ובא\"ל יחזור את העולם לתהו<sup data-n=\"3822\">27</sup>, וכתי' עשרה עשרה הכף<sup data-n=\"3823\">28</sup> וארז\"ל במד\"ר<sup data-n=\"3824\">29</sup> ובזהר שעה\"ד מכוונים כנגד עש\"מ<sup data-n=\"3825\">30</sup>, והיינו שע\"י עשרת הדברות מתקיימים ע\"מ, וכמ\"ש נמוגים ארץ וכל יושבי' אנכי תכנתי עמודי' סלה (תילי' סי'<sup data-n=\"3827\">32</sup> ע\"ה<sup data-n=\"3826\">31</sup> ) וארז\"ל במד\"ר שה\"ש ע\"פ שובי שובי השולמי' דל\"ג נמוגי'",[["3812","17","<b>דאנא אמלוך</b>: לשון הת\"י למלכים-א א, ה. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד [ושם נדפס: נשא כא, ב. וצ\"ל כא, ד]."],["3813","18","<b>המלוכה . . על נבראים נפרדים</b>: ראה שער היחוד והאמונה רפ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550731\" data-slug=\"torat-chaim\" data-id=\"2300550731\">תו\"ח ויקהל ח\"ב תו, ד</a>."],["3814","19","<b>עם מל' עוממות</b>: שער היחוד והאמונה פ\"ז. ראה גם לקו\"ת ואתחנן יא, ג [הועתק לעיל במאמר ד\"ה מגילה נקראת ספ\"ב]. אוה\"ת שמות ע' פט ואילך. סה\"מ תרכ\"ט ע' שי. תר\"ס ע' ה. לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי פ\"ז."],["3816","21","<b>ית'</b>: כ\"ה בכ\"מ ומהם: סה\"מ תרכ\"ט ע' רט. תרל\"ח ע' מ. סה\"מ תר\"ם ח\"ב ע' תקכא. ובהנסמן בהנ\"ל. לעיל מאמר ד\"ה קדש ישראל לה' ספ\"א. מאמר ד\"ה תקעו תרצ\"א על יד הערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191027\" data-slug=\"likkutei-sichot\" data-id=\"1300191027\">לקו\"ש דברים כרך יט ע' 27</a> ואילך."],["3815","20","<b>שנתאוה הקב\"ה . . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. תו\"ח בא ח\"א קמז, סע\"ב ואילך. וש\"נ. פקודי ח\"ב תנב, ג. סה\"מ תרל\"ח ע' לט ואילך בהערות. תר\"ם ח\"א ע' רנ. וש\"נ. לעיל מאמר ד\"ה קדש ישראל לה' פ\"ב."],["3817","22","<b>שוקיו עמודי שש</b>: שה\"ש ה, טו."],["3818","23","<b>שוקיו זה עולם . . לבראותו</b>: ראה במד\"ר רפ\"י."],["3819","24","<b>ולמה נשתוקק ונתאוה</b>: ראה גם סה\"מ תרכ\"ז ע' תנג ואילך. תרל\"ג ח\"ב ע' תקצד. תרל\"ח ס\"ע תנד. תרל\"ט ח\"ב ע' תקט. תר\"ם ח\"א ע' רנח. תש\"ח ס\"ע 111 ואילך ובהנסמן בהנ\"ל."],["3820","25","<b>תחתונים במעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380052\" data-slug=\"likkutei-torah\" data-id=\"4001380052\">לקו\"ת פקודי ג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550068\" data-slug=\"torat-chaim\" data-id=\"2300550068\">תו\"ח פקודי ח\"ב תמב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550135\" data-slug=\"torat-chaim\" data-id=\"2300550135\">תנב, ג</a>."],["3821","26","<b>אין אני והוא יכולים לדור</b>: סוטה ה, א. ערכין טו, ב."],["3822","27","<b>בפ\"ט דשבת תנאי התנה . . לתהו</b>: ראה שם פח, א. ילקוט שמעוני בראשית א, לא (רמז טז). לעיל מאמר ד\"ה וירא ישראל את היד הגדולה רפ\"ב. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' ובהערה 53. סה\"מ תר\"ם ח\"א ע' רנ. וש\"נ."],["3823","28","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["3824","29","<b>במד\"ר</b>: ראה פסיקתא רבתי פיסקא עשה\"ד פכ\"א, יט. מדרש לקח טוב יתרו כ, ב."],["3825","30","<b>ובזהר שעה\"ד . . עש\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לעיל מאמר ד\"ה קדש ישראל לה' הערה 52."],["3827","32","<b>סי'</b>: כשמציינים לתנ\"ך לפעמים משתמשים בתיבת ”סימן\". ולפעמים בתיבת ”קפיטל\". ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 17."],["3826","31","<b>נמוגים ארץ . . תילי' סי' ע\"ה</b>: פסוק ד."]]],[2001910381,"ארץ וכל יושבי' אלולי שעמדו ישראל לפני ה\"ס ואמרו כל אשר דבר ה' נעשה ונשמע<sup data-n=\"3828\">33</sup> כבר הי' העולם מתגמגם והולך, ומי ביסם העולם אנכי שנא' אנכי תכנתי עמודי' סלה בזכות אנכי ה' אלקיך<sup data-n=\"3829\">34</sup> תכנתי עמודי', וכ\"ה בפ' תולדות פס\"ו, וכמשי\"ת שאחת דבר כו' שזהו כל הדברים<sup data-n=\"3830\">35</sup> כו' הכלל שכולל הכל כו', ונת' לעיל<sup data-n=\"3831\">36</sup> דכתי' ועמך כולם צדיקים<sup data-n=\"3832\">37</sup> שהוא ע\"י קיום התומ\"צ שכללותן נק' בשם צדקה<sup data-n=\"3833\">38</sup> כו', וז\"ע וכדי ליתן שכ\"ט לצדיקים שמקיימים את העולם שנברא בע\"מ<sup data-n=\"3834\">39</sup>, והיינו כי הצדיקים ממשיכים בחי' מאמר א' הוא מאמר הכללי, וכמ\"ש גוי אחד בארץ<sup data-n=\"3835\">40</sup> שממשיכים בחי' אחד היינו מאמר אחד גם בארץ<sup data-n=\"3836\">41</sup> שהיא בחי' יבשה, שהנבראים שביבשה בחי' עלמא דאתגלי'<sup data-n=\"3837\">42</sup> הם נפרדים ועכ\"ז יומשך בחי' אחד היינו שיהי' בבחי' ביטול היש לאין כו', וז\"ע ת\"ח מרבים שלום בעולם כי ע\"י התורה נמשך קיום העולם כנ\"ל והם מרבים שלום שעושים שלום ביני ובין עולמי, והיינו הגם שנעשה העולם ליש ודבר נפרד שהוא בחי' מציאת התחתונים, עכ\"ז יהי' דירתו ית' בתחתונים ע\"י בחי' ביטול היש שפועלים הצדיקים והת\"ח שעוסקים בתורה שז\"ע בנינו ש\"ע פי' בנינו היינו קיומו וכנ\"ל שתלוי בתומ\"צ, ועי\"ז ממשיך אחד בארץ היינו מא' א' שיהי' ביטול היש, ועי\"ז יהי' שלום והתחברות אא\"ס בעולם שז\"ע בחי'\n\nגדולים<sup data-n=\"8638\">א</sup> מע\"צ ממעשה שו\"א<sup data-n=\"8639\">ב</sup>, והיינו כי ע\"י מע\"צ נמשך להיות בחי' ביטול היש לאין, ולכן אשר הוצאתיך מאמ\"צ ולא אשר בראתי שו\"א<sup data-n=\"8640\">ג</sup>, לפי שיצ\"מ בעבודה ז\"ע לצאת מהמיצר שיתגלה כבוד ה'<sup data-n=\"8641\">ד</sup> וראו כל בשר<sup data-n=\"8642\">ה</sup> כו'.",[["3828","33","<b>כל אשר דבר. . ונשמע</b>: משפטים כד, ז."],["3829","34","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."],["3830","35","<b>וכמשי\"ת שאחת דבר . . כל הדברים</b>: לקמן פ\"ב. וש\"נ."],["3831","36","<b>ונת' לעיל</b>: במאמר ד\"ה כי תבואו וכו' ושבתה הארץ בסופו."],["3832","37","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["3833","38","<b>התומ\"צ . . בשם צדקה</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ועבדתם את ה\"א ובהערה 34."],["3834","39","<b>וכדי ליתן . . שנברא בע\"מ</b>: ראה אבות רפ\"ה."],["3835","40","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דברי הימים-א יז, כא."],["3836","41","<b>שממשיכים בחי' אחד . . גם בארץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו\"א וישב כז, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380519\" data-slug=\"likkutei-torah\" data-id=\"4001380519\">לקו\"ת שלח נא, ד</a>. לעיל מאמר ד\"ה כי תשא ובהערה 21."],["3837","42","<b>עלמא דאתגלי'</b>: ראה לעיל הערה 16.\n\n<b>א</b> ) <b>גדולים</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>ב</b> ) <b>גדולים מע\"צ ממעשה שו\"א</b>: ראה כתובות ה, א. לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 234.\n\n<b>ג</b> ) <b>אשר הוצאתיך . . בראתי שו\"א</b>: יתרו כ, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שצז ואילך. וש\"נ. ע' תא ואילך. וש\"נ. שה\"א יא, ב הערה 13. סה\"מ תרל\"ח ע' קא. וש\"נ. ע' שצה.\n\n<b>ד</b> ) <b>שיצ\"מ . . כבוד ה'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, ב</a> ואילך. אוה\"ת וארא ע' רמ. סה\"מ תרל\"א ח\"א ע' מז. וש\"נ.\n\n<b>ה</b> ) <b>וראו כל בשר</b>: ישעי' מ, ה. ראה גם סה\"מ תר\"ם ח\"ב ע' תשנא. וש\"נ."]]],[2001910382,"דירה בתחתונים, שיושלם רצון דאנא אמלוך שזהו אינו שייך כ\"א על נפרדים שזהו מציאות בחי' התחתונים במעלה, ועכ\"ז יהי' לו ית' דירה בתחתונים, וז\"ע מרבים שלום כו', בחי' שלום והתחברות ביני ובין עולמי כו'.\nב) <b>ולהבין</b> איך ע\"י התורה נמשך בנינו ש\"ע, ושע\"י יומשך בחי' מאמר א' בחי' מאמר כללי הנ\"ל, הנה כתי' ואהי' אצלו אמון<sup data-n=\"3838\">43</sup>, ופי' במד\"ר אמון לשון אומן<sup data-n=\"3839\">44</sup> שהתורה היא בחי' כלי אומנתו של הקב\"ה, והנה אנו רואים שכאשר המלך בונה פלטרין מתחלה עושה האומן הציור איך יבנה הפלטרין של המלך, כמ\"ש משל זה במד\"ר ובזהר<sup data-n=\"3840\">45</sup>, והנה האומן כשמצייר הציור הנה תחלה מצייר כללות הבנין ארכו ורחבו לצד זה ולצד זה, ואח\"כ מצייר פרטי החדרים, שיהי' כך וכך כו', וכך הנה יובן בבחי' התורה שהיא נק' אמון ל' אומן וכמ\"ש ואהי' אצלו שעשועים יום יום<sup data-n=\"3841\">46</sup> וארז\"ל אלפים שנה קדמה תורה לעולם<sup data-n=\"3842\">47</sup> כי יומו של הקב\"ה אלף שנה<sup data-n=\"3843\">48</sup> והתורה היא בחי' האומן שבה נברא העולם וכמ\"ש בזהר אסתכל באורייתא וברא עלמא<sup data-n=\"3844\">49</sup>, ומאחר שבעולם יש בחי' כלל ופרט כנ\"ל בהכרח שיהי' בבחי' התורה שהיא בחי' האומן ג\"כ בחי' כלל ופרט, והענין הוא דהנה כתיב וידבר אלקים את כל הדברים האלה לאמר<sup data-n=\"3845\">50</sup>, ופי' כל הדברים האלה שדיבור אחד יצא מפי הקב\"ה שהי' כולל כל עשה\"ד<sup data-n=\"3846\">51</sup> וגם כל פרטי הדינים המבוארים בכל התורה כולה כו', וכמ\"ש אחת דיבר אלקים שתים זו שמעתי<sup data-n=\"3847\">52</sup>, פי' אחת דיבר אלקים שדבור א' יצא מפי הקב\"ה שהוא בחי' כל הדברים שכולל כל העשה\"ד, שתים זו שמעתי שהוא בחי' אנכי ולא יהי' לך מפי הגבורה שמענו<sup data-n=\"3848\">53</sup>, ולכן במ\"ת כתי' וכל העם רואים את הקולות<sup data-n=\"3849\">54</sup> כו' רואין את הנשמע ושומעין את הנראה<sup data-n=\"3850\">55</sup> שהוא מה שאין הפה יכול לדבר והאזן אינו יכול לשמוע<sup data-n=\"3851\">56</sup> כו' והיינו מפני שבמ\"ת האיר בחי' הכלליות ולכן האיר בנפש ג\"כ בחי' הכלליות, ולכן הי' ראי' ושמיעה הכל א' כי בבחי' הנפש עצמה",[["3838","43","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["3839","44","<b>ופי' במד\"ר אמון לשון אומן</b>: ב\"ר בתחילתו."],["3840","45","<b>ובזהר</b>: ראה בסמוך הערה 49."],["3841","46","<b>ואהי' אצלו שעשועים יום יום</b>: משלי ח, ל."],["3842","47","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["3843","48","<b>יומו של הקב\"ה אלף שנה</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רז. וש\"נ. ח\"ג ע' תתה. וש\"נ. וראה גם סה\"מ תרל\"ט ח\"ב ס\"ע שצו ואילך. וש\"נ. ס\"ע תקצב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540233\" data-slug=\"torat-chaim\" data-id=\"2300540233\">תו\"ח שמות ח\"א מד, סע\"ב</a>."],["3844","49","<b>אסתכל באורייתא וברא עלמא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט ואילך."],["3845","50","<b>וידבר אלקים . . לאמר</b>: יתרו כ, א."],["3846","51","<b>שדיבור אחד . . כל עשה\"ד</b>: ראה מכילתא ורש\"י יתרו שם. הנסמן בסה\"מ תרכ\"ז כאן ע' רפה."],["3847","52","<b>אחת . . שתים זו שמעתי</b>: תהלים סב, יב."],["3848","53","<b>אנכי . . מפי הגבורה שמענו</b>: מכות כד, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131119\" data-slug=\"likkutei-sichot\" data-id=\"1300131119\">לקו\"ש מסעי כרך יג ע' 119</a> ואילך. סה\"ש תנש\"א ע' 302 ואילך. סה\"מ תר\"ם ח\"ב ע' תרלט. וש\"נ."],["3849","54","<b>וכל העם רואים את הקולות</b>: יתרו כ, טו."],["3850","55","<b>רואין את הנשמע . . הנראה</b>: ראה מכילתא ורש\"י יתרו שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061131\" data-slug=\"likkutei-sichot\" data-id=\"1300061131\">לקו\"ש יתרו כרך ו ע' 120</a> בהערה 5-6. ובהשמטה לשם בע' 416. מאמרי אדה\"א במדבר ח\"ב ע' תכא. ע' תרכו. סה\"מ תרכ\"ט ע' ריח ואילך. וש\"נ."],["3851","56","<b>מה שאין הפה . . והאזן . . לשמוע</b>: ראה מכילתא דרשב\"י יתרו כ, א. יל\"ש ירמי' ב, ו [רמז רסו]. תנחומא יתרו יא."]]],[2001910383,"בחי' הראי' ובחי' השמיעה ביחד כו', ולמעלה הוא ג\"כ כן, כי הנה למטה בעולם הבריאה ראי' ושמיעה המה כל א' בחי' בפ\"ע, ראובן הוא בחי' ראי'<sup data-n=\"3852\">57</sup> כי ראה ה'<sup data-n=\"3853\">58</sup>, שמעון הוא בחי' כי שמע ה'<sup data-n=\"3854\">59</sup>, אך הנה השבטים הם בחי' מרכבתא תתאה שהוא בחי' מרכבתא דבריאה<sup data-n=\"3855\">60</sup>, פני ארי'<sup data-n=\"3856\">61</sup> אותיות ראי'<sup data-n=\"3857\">62</sup>, אבל למעלה הוא בחי' הכלל ששם ראי' ושמיעה בהדי הדדי כו', ולכן ת\"ח שלומדים תורה הם ממשיכים מבחי' כללות הנמצא בתורה והתורה היא בחי' אומן שבה נברא העולם, ולכן כאשר ממשיכים מבחי' כלל שבתורה נמשך ג\"כ בחי' הכלל שבעולם שהוא בחי' מאמר א' מאמר הכללי כו', וזהו ות\"ת כנגד כולם<sup data-n=\"3858\">63</sup>, כי ע\"י בחי' ת\"ת נמשך בחי' מאמר א' מאמר הכללי, וזהו שנק' הת\"ח בשם בנאין שעוסקי' בבנינו של עולם, כי ע\"י שלומדים בחי' התורה ממשיכים בחי' מאמר א' בעולם ולכן נק' עוסקי' בבנינו ש\"ע כו'.\nג) <b>ומעתה</b> יובן משארז\"ל והלואי שיתפלל אדם<sup data-n=\"3859\">64</sup> כל היום כולו, שמשמע שבחי' התפלה גדול מבחי' התורה כו', ויובן זה בהקדם מעלת התורה שנית, כי הנה כתי' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"3860\">65</sup>, ופי' לעבדה ולשמרה להמשיך בחי' זיו ואור בג\"ע כי ג\"ע הוא בחי' עולם הבריאה<sup data-n=\"3861\">66</sup>, והנה כתי' יוצר אור ובורא חשך<sup data-n=\"3862\">67</sup> שיצירה נק' בשם אור ובריאה נק' חשך, ולכאו' צ\"ל איך שייך לומר שבריאה יהי' נק' בשם חשך ויצי' אור הלא עולם הבריאה גבוה מבחי' יצירה. אך הענין הוא דהנה ביצי' מאיר מבחי' מדות כמ\"ש בכהאריז\"ל ובתקונים<sup data-n=\"3863\">68</sup> שית ספירן מקננא ביצי'<sup data-n=\"3864\">69</sup>, ולכן הוא בחי' אור שמאירים מדותיו ית' בחי' אהוי\"ר כו', אבל בבריאה מאיר בחי' בינה וכמ\"ש בתקוני' ובכהאריז\"ל אימא מקננא בכורסייא<sup data-n=\"3865\">70</sup>, ומחמת עוצם הגילוי שמאיר בבריאה א\"א שיהי' השגה גמורה בבחי' זו, ולכן נק' בשם חשך, כי פי' החשך הוא שאינו מאיר וכמו\"כ בעולם הבריאה שאינו מאיר בהשגה גמורה",[["3852","57","<b>ראובן . . ראי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370205\" data-slug=\"torah-or\" data-id=\"3901370205\">תו\"א ויחי מה, א</a>. סע\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540892\" data-slug=\"torat-chaim\" data-id=\"2300540892\">תו\"ח וארא ח\"א פד, סע\"ד</a>. וש\"נ."],["3853","58","<b>כי ראה ה'</b>: ויצא כט, לב."],["3854","59","<b>שמעון . . כי שמע ה'</b>: ויצא כט, לג. תו\"א שם מה, ב. סע\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540901\" data-slug=\"torat-chaim\" data-id=\"2300540901\">תו\"ח שם פה, א</a>."],["3855","60","<b>השבטים . . מרכבתא תתאה . . דבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370515\" data-slug=\"torah-or\" data-id=\"3901370515\">תו\"א ויקהל קטו, ג</a>. לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 179."],["3856","61","<b>פני ארי'</b>: יחזקאל א, י."],["3857","62","<b>ארי' אותיות ראי'</b>: ראה ת\"ז ת\"ע (קכב, א). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370205\" data-slug=\"torah-or\" data-id=\"3901370205\">תו\"א ויחי מה, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370319\" data-slug=\"torah-or\" data-id=\"3901370319\">יתרו עא, ד</a>. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["3858","63","<b>ות\"ת כנגד כולם</b>: פאה פ\"א, מ\"א. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 117."],["3859","64","<b>והלואי שיתפלל אדם</b>: ראה ברכות כא, א. לעיל מאמר ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 16 ואילך."],["3860","65","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו. ראה גם לקמן בסיום הפרק."],["3861","66","<b>ג\"ע . . עולם הבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a> ובמ\"מ, הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380917\" data-slug=\"likkutei-torah\" data-id=\"4001380917\">לקו\"ת נצבים מט, ג</a>. מק\"מ לזהר שלח קנט, ב. סה\"מ תר\"ם ח\"א ע' טז. וש\"נ."],["3862","67","<b>יוצר אור ובורא חושך</b>: ישעי' מה, ז. ראה פע\"ח שער הק\"ש ש\"ח, פ\"א. סה\"מ תרכ\"ז כאן ע' רפו. וש\"נ. תר\"ם ח\"א ע' רלז. וש\"נ."],["3863","68","<b>בכהאריז\"ל ובתקונים</b>: בתניא שבהערה הבאה: בתיקונים וע\"ח."],["3864","69","<b>שית ספירן מקננא ביצי'</b>: ראה ת\"ז ת\"ו כג, א. ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ב. תניא פל\"ט ובמ\"מ הגהות והע\"ק שם. שם פנ\"ב. מאמרי אדה\"ז הקצרים ע' תקנב."],["3865","70","<b>אימא מקננא בכורסייא</b>: ת\"ז שם. ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ג. שער דרושי כללות אבי\"ע שמ\"ב, פי\"ג. תניא פל\"ט."]]],[2001910384,"האור שמאיר בה לכן נק' בשם חשך, וזהו שמשנה ביצי' ותלמוד בבריאה<sup data-n=\"3866\">71</sup>, כי משנה היא בחי' פסק דין וטעם קצר הנה זה יכול להשיג אף מי שאינו בר דעת גדול שהרי גם הקטן יכול ג\"כ להשיגה<sup data-n=\"3867\">72</sup>, אבל בחי' התלמוד מחמת החריפות שבתלמוד לא יוכל הקטן להשיגה מחמת קוטן כלי המוח כו' ולכן נק' חשך כמ\"ש במחשכים הושיבני וארז\"ל זו תלמוד בבלי<sup data-n=\"3868\">73</sup> שנק' חשך מפני שאינו בגילוי כ\"כ כמו המשנה שגם קטן יכול להבין המשנה, וכמו\"כ הוא ענין בריאה שנק' בשם חשך היינו מפני עוצם הגילוי שמאיר שם אינו יכול לבוא בבחי' השגה גמורה לכן נק' בשם חשך, וזהו ויניחהו בג\"ע בחי' עולם הבריאה לעבדה ולשמרה דהיינו להמשיך בחי' אור וזיו להאיר את החשך וכמו בבית אפל כאשר מביאים הנר לתוכה מאיר הנר את החשך, כך הנה בחי' עולם הבריאה שנק' בורא חשך ע\"י המשכת האור והזיו של התומ\"צ שזהו לעבדה ולשמרה רמ\"ח מ\"ע ושס\"ה מל\"ת<sup data-n=\"3869\">74</sup> ממשיכים בחי' אור וזיו בבריאה כו', והאור והזיו זה הוא כמו האבות שנק' זיו כמ\"ש מלכים א' ו'<sup data-n=\"3870\">75</sup> בשנה הרביעית בחדש זיו וארז\"ל בר\"ה די\"א ע\"א בירח שבו נולדו זיותני עולם היינו האבות<sup data-n=\"3871\">76</sup>, והיינו מפני כי האבות הן המרכבה<sup data-n=\"3872\">77</sup> וע\"י הביטול שלהם המשיכו בחי' האור והזיו, וכמו\"כ ע\"י המצות ממשיכים אור וזיו בג\"ע שהוא עולם הבריאה שנק' בורא חשך.",[["3866","71","<b>שמשנה ביצי' ותלמוד בבריאה</b>: ראה פע\"ח שער הנהגת הלימוד שי\"ז. תניא פ\"מ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, סע\"א</a> ואילך. מאמרי אדה\"א נ\"ך ע' קלט. וש\"נ."],["3867","72","<b>הקטן יכול ג\"כ להשיגה</b>: ראה אבות פ\"ה בסופה: בן עשר למשנה . . בן חמש עשרה לגמרא."],["3868","73","<b>במחשכים הושיבני . . זו תלמוד בבלי</b>: איכה ג, ו. ראה סנהדרין כד, א. הנסמן במאמרי אדה\"'א ויקרא ח\"א ע' קו. סה\"מ תרל\"ג ח\"ב ע' תכז. וש\"נ."],["3869","74","<b>לעבדה . . רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["3870","75","<b>מלכים א' ו'</b>: פסוק א."],["3871","76","<b>זיותני עולם היינו האבות</b>: ראה גם ביאוה\"ז להצ\"צ אחרי כרך א ע' שנה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200164\" data-slug=\"or-hatorah-hb\" data-id=\"8159200164\">אוה\"ת בהר כרך ג ע' תתעט</a> ואילך. סה\"מ תר\"ס ע' קלב. פלח הרמון בהר ס\"ע שפח ואילך."],["3872","77","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."]]],[2001910385,"<h3>כל אשר חפץ ה'</h3>\n<b>בס\"ד</b>\nכל אשר חפץ ה' עשה<sup data-n=\"3873\">1</sup> בשמים ובארץ<sup data-n=\"3874\">2</sup>.\n<b>מה</b> רבו מעשיך ה' כולם בחכמה עשית<sup data-n=\"3875\">3</sup>, משמע שכל מה שנעשה במע\"ב זהו הכל מבחי' החכ' כמ\"ש כולם בחכ' שקאי על כל בחי' ריבוי המעשים שנבראו בשי\"ב שעליהם אמר דהע\"ה מה רבו מעשיך כמ\"ש במזמור ק\"ד שבתילים שחשב כל מה שנברא ונוצר ונעשה ועלי' אומר מה רבו מעשיך ע\"ש. וכן ת\"י על בראשית ברא בחוכמתא<sup data-n=\"3876\">4</sup> ברא, וכן כתי' ה' בחכמה יסד ארץ<sup data-n=\"3877\">5</sup>. ולכאו' צ\"ל הלא כתי' כל אשר חפץ ה' עשה בשמים ובארץ, שמשמע שמה שעשה בשמי' ובארץ נמשך מבחי' חפץ, שנודע שבחי' חפץ הוא פנימיות הרצון<sup data-n=\"3878\">6</sup> שזהו גבוה יותר למעלה ראש מבחי' החכמה, ואונקלס<sup data-n=\"3879\">7</sup> תירגם על בראשית בקדמין<sup data-n=\"3880\">8</sup> שנודע שקדם הוא למעלה מן החכ'<sup data-n=\"3881\">9</sup> וקרוב לבחי' חפץ הנ\"ל כו', ופעם כתי' כי אמרתי עולם חסד יבנה<sup data-n=\"3882\">10</sup> שיש בזה ב'\n\nוביאור<sup data-n=\"8643\">א</sup> הענין כי מדות שייך לזולת דוקא<sup data-n=\"8644\">ב</sup>, ולכן כדי שיהי' מציאות נבדל זהו ע\"י המדות.\nויאמר מד\"ר ביטל הגזירה<sup data-n=\"8645\">ג</sup> וירד כו' עה\"ס<sup data-n=\"8646\">ד</sup>",[["3873","1","<b>כל אשר חפץ ה' עשה</b>: מאמר זה הוא מאמר הג' מההמשך דמאמר ד\"ה כי תבואו וכו' ושבתה הארץ שנדפס לעיל.\nלפיסקא ראשונה ראה מאמר ד\"ה מה רבו נדפס ב”קונטרס בר מצוה תרנ\"ג\" [תש\"ס] ע' מד. סה\"מ תרמ\"ד מהדורת תשס\"ב ע' שיג ובהנסמן שם.\nהמאמר נרשם בגוכתי\"ק."],["3874","2","<b>כל אשר חפץ ה' עשה בשמים ובארץ</b>: תהלים קלה, ו."],["3875","3","<b>מה רבו . . כולם בחכמה עשית</b>: תהלים קד, כד."],["3876","4","<b>ת\"י על בראשית ברא בחוכמתא</b>: בראשית א, א. ראה תרגום ירושלמי שם. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["3877","5","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["3878","6","<b>חפץ הוא פנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["3879","7","<b>ואונקלס</b>: בבוך תרמ\"א 2086 — כת\"י מעתיק: ואונקלוס."],["3880","8","<b>ואונקלוס . . בראשית בקדמין</b>: בראשית א, א."],["3881","9","<b>שקדם הוא למעלה מן החכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. אוה\"ת ואתחנן ע' תיד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370395\" data-slug=\"torah-or\" data-id=\"3901370395\">תו\"א ויקהל פז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380791\" data-slug=\"likkutei-torah\" data-id=\"4001380791\">לקו\"ת פ' ראה יח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381204\" data-slug=\"likkutei-torah\" data-id=\"4001381204\">שה\"ש יח, ד</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' רכה. אוה\"ת תצא ס\"ע תתצ."],["3882","10","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 106.\n\n<b>א</b> ) <b>וביאור</b>: שני קטעים הבאים נרשמו בשולי היריעה ללא ציון מקומם בפנים. בבוך תרמ\"א 2086 — כת\"י מעתיק לא העתיקם.\n\n<b>ב</b> ) <b>מדות שייך לזולת דוקא</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ.\n\n<b>ג</b> ) <b>ויאמר מד\"ר ביטל הגזירה</b>: וארא ט, כב. ראה שמו\"ר פי\"ב, ג. וראה גם פלח הרמון אמור ע' רפ הערה 81.\n\n<b>ד</b> ) <b>וירד כו' עה\"ס</b>: יתרו יט, כ."]]],[2001910386,"פירושים הא' שהעולם נבנה ע\"י החסד, והב' שבכדי שיהי' עולם צריך לבנות מדת החסד, שאוא\"ס ב\"ה הוא לאו מכל אילון מדות<sup data-n=\"3883\">11</sup> איהו כלל, וכדי שיהי' התהווות העולמות צריכין לבנות מדהח\"ס שבה וע\"י יומשך חיות העולם כמ\"ש מכלכל חיים בחסד<sup data-n=\"3884\">12</sup> כו', ולפעמים מצינו דכתיב בדבר ה' שמים נעשו<sup data-n=\"3885\">13</sup> כו' שמשמע שנברא ע\"י הדבור, וכמו שארז\"ל בע\"מ נברא העולם<sup data-n=\"3886\">14</sup>, וכן כתי' במע\"ב ויאמר אלקים<sup data-n=\"3887\">15</sup>. אך הענין הוא שיובן ע\"פ משנת\"ל<sup data-n=\"3888\">16</sup> בפי' והלא במאמר אחד יכול להבראות<sup data-n=\"3889\">17</sup> לפי' הא' שמאמר א' הוא מה שעלה ברצונו, והוא מאמר דבראשית בחוכמתא, כי כאשר עלה ברצונו הפשוט<sup data-n=\"3890\">18</sup> התהוות העולמות נמשך בבחי' חו\"ב שיהי' נמדד ע\"פ החכ' שיהי' כך ולא כך וע\"י הבינה נמדד פרטי כל בחי' ההשתלשלות כו', ונת' לעיל<sup data-n=\"3891\">19</sup> שלא מחשבותי מחשבותיכם<sup data-n=\"3892\">20</sup> ולכן כאשר עלה במח' תומ\"י נתהוה כו', וזהו בחי' המאמר אחד שהוא מאמר כללי שכולל כל כלליות ההשתלשלות, ולכן ת\"י עליו בחוכמתא שזהו ע\"פ מדידת חו\"ב כנ\"ל, וכדכתי' כולם בחכמה עשית, ונודע כי עשית בבינה<sup data-n=\"3893\">21</sup>, ואונקלס תרגם בקדמין, היינו בחי' הרצון מה שעלה ברצונו שזהו ג\"כ מכוון אחד עם בחי' המדידה דחו\"ב הנ\"ל, כי המדידה היא ע\"פ הרצון כו' רק שהרצון כולל כל פרטיות המדידה, ולכן כוללם הת\"א יותר בפירושו שמפרט בקדמין שזהו כלל כל הפרטים ומדידת דחו\"ב, ואמנם גם המדידות דחו\"ב ג\"כ בבחי' הכלל דמאמר אחד יחשב, להיותו בחי' אחד עדיין, כי פי' אחד הוא כמארז\"ל כד אמליכתי'<sup data-n=\"3894\">22</sup> למעלה ולמטה ולד' רוחות תו לא צריכות<sup data-n=\"3895\">23</sup> שזהו תכלית היחוד, שהחי\"ת רומז לז\"ר וארץ והד' רומז לד' רוחות העולם<sup data-n=\"3896\">24</sup>, וכמ\"ש לך ה' הגדולה כו' לך ה' הממלכה<sup data-n=\"3897\">25</sup> איך שזו\"נ שרש ז\"ר וארץ, ושרש ו\"ק שהם ד' רוחות ומעלה ומטה בטלים בתכלית היחוד בבחי' אל\"ף אלופו ש\"ע<sup data-n=\"3898\">26</sup>, ועד\"ז יובן ענין מאמר אחד שהוא איך שכל הפרטים שנבראו ונוצרו ונעשו אח\"כ עומדים הכל בתכלית היחוד בבחי' הכלליות כמו בבחי' עקודים ששם עקוד כל האורות דיו\"ד ספירות בכלי אחד<sup data-n=\"3899\">27</sup> כו' ולכן ת\"י בראשית",[["3883","11","<b>לאו מכל אילון </b> [בבוך תרמ\"א 2086 — כת\"י מעתיק: אלין]<b> מדות</b>: ראה ת\"ז בהקדמה יז, ב."],["3884","12","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460112\" data-slug=\"or-hatorah-hb\" data-id=\"8316460112\">אוה\"ת יתרו ריש ע' תתקכז</a>. סה\"מ תרכ\"ו ע' ב. לקמן מאמר ד\"ה בעשרה מאמרות נבה\"ע על יד הערה 19 (ובחלק ההנחות שם על יד הערה 28). המשך תער\"ב ח\"ג ע' תל."],["3885","13","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו. ראה גם תו\"א מקץ מד, א. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י בתחילתו."],["3886","14","<b>בע\"מ נברא העולם</b>: אבות רפ\"ה."],["3887","15","<b>ויאמר אלקים</b>: בראשית א, ג ואילך."],["3888","16","<b>משנת\"ל</b>: במאמר ד\"ה כי תבואו כו' ושבתה הארץ פ\"ב ואילך."],["3889","17","<b>והלא במאמר אחד יכול להבראות</b>: אבות שם."],["3890","18","<b>כאשר עלה ברצונו הפשוט</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["3891","19","<b>ונת' לעיל</b>: שם פ\"ג."],["3892","20","<b>שלא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a> ואילך. (הועתק ב) סה\"מ תר\"ם ח\"א ע' קלט ואילך ובהנסמן שם."],["3893","21","<b>כולם בחכמה . . עשית בבינה</b>: זהר תזריע מג, א."],["3894","22","<b>כד אמליכתי'</b>: ראה ברכות יג, ב. אמרי בינה פתח השער בתחילתו."],["3895","23","<b>צריכות</b>: בבוך תרמ\"א 2086 — כת\"י מעתיק: צריכת."],["3896","24","<b>שהחי\"ת רומז לז\"ר . . לד' רוחות העולם</b>: ראה גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ הערה 55."],["3897","25","<b>לך ה' הגדולה . . הממלכה</b>: דבהי\"א כט, יא."],["3898","26","<b>אל\"ף אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["3899","27","<b>עקודים ששם עקוד . . בכלי אחד</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370043\" data-slug=\"torah-or\" data-id=\"3901370043\">תו\"א נח י, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540165\" data-slug=\"torat-chaim\" data-id=\"2300540165\">תו\"ח וארא ח\"א נב, ד</a>. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274. (לקמן בחלק ההנחות) הנחה ד\"ה בעשרה מאמרות נברא העולם על יד הערה 62."]]],[2001910387,"בחוכמתא, כי החכמה היא בחי' יו\"ד דש' הוי'<sup data-n=\"3900\">28</sup> כנודע, ונודע כי ביו\"ד יש בו ג' קוצין<sup data-n=\"3901\">29</sup> ומקוץ התחתון נמשך ההי\"א כמ\"ש<sup data-n=\"3903\">31</sup> הפרד\"ס<sup data-n=\"3902\">30</sup> הובא בת\"א ד\"ה ענין לך לך<sup data-n=\"3904\">32</sup>, וקוץ העליון זהו בחי' הרצון<sup data-n=\"3905\">33</sup>, ועצם היו\"ד זהו בחי' חכ', ונמצא כי היו\"ד שהוא החכ' כולל כח\"ב, ולכן תרגם על בראשית בחוכמתא, ואונקלס תרגם בקדמין לרמז על בחי' הרצון בחי' קוש\"י כו', שהוא שרש בחי' המאמר אחד כו'.\n<b>ואמנם</b> כדי להפרע מן הרשעים וליתן שכ\"ט לצדיקים<sup data-n=\"3906\">34</sup> היינו בכדי שיהי' שכר ועונש, שזהו דוקא ע\"י שהבחירה תהי' חפשית, ולכן אם הי' נברא ממאמר אחד הנ\"ל הי' העולמות בטלים בתכלית, ובכלל זהו ע\"ד הביטול דעלמא דאתכסיא<sup data-n=\"3907\">35</sup>\n\nיו\"ד<sup data-n=\"8647\">ה</sup> דחכ' וא\"ו ד' כלולים בו<sup data-n=\"8648\">ו</sup>, וגם קוש\"י רצון, וקוץ התחתון זהו מקור ההי\"א ע' בד\"ה לך לך בת\"א בענין ג' קוצין שביו\"ד כו', נמצא בחוכמתא כולל כל הע\"ס עם הרצון.\nא' ב' יודי\"ן וא\"ו באמצע<sup data-n=\"8649\">ז</sup>, עם קוץ העליון שבאלף זהו ג\"כ כל הע\"ס עם הרצון, א\"כ אחד ויו\"ד דש' הוי' ענינם אחד, ובזה יובן שת\"א ות\"י כוונתם אחד הוא.\nאלף מציאותו בחי' יו\"ד, כי יו\"ד בראש ויו\"ד בסוף, וא\"ו באמצע שענין הוא\"ו הוא ג\"כ יו\"ד בראשח כנודע.",[["3900","28","<b>החכמה . . יו\"ד דש' הוי'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["3901","29","<b>ביו\"ד יש בו ג' קוצין</b>: ראה גם שו\"ע אדה\"ז הל' תפילין סל\"ו, ס\"ב אות יו\"ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670175\" data-slug=\"torat-chaim\" data-id=\"2300670175\">תו\"ח לך פב, ב</a> ובהערה 11. שמות ח\"א לד, א. וש\"נ."],["3903","31","<b>הפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["3902","30","<b>ומקץ התחתון . . ההי\"א כמ\"ש הפרד\"ס</b>: ראה שם שער האותיות שכ\"ז, ספי\"ג."],["3904","32","<b>בת\"א ד\"ה ענין לך לך</b>: שם יא, ג."],["3905","33","<b>וקוץ העליון . . הרצון</b>: ראה זהר ויקרא י, ב [ושם: כתרא עלאה]."],["3906","34","<b>כדי להפרע . . שכ\"ט לצדיקים</b>: אבות רפ\"ה. תיבת כדי — ראה גם לקמן מאמר ד\"ה בעש\"מ נבה\"ע הערה 3."],["3907","35","<b>דעלמא דאתכסיא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>.\n\n<b>ה</b> ) <b>יו\"ד</b>: ג' קטעים הבאים להלן נרשמו בשולי היריעה ללא ציון מקומם בפנים. קטע הג' נרשם שם בצד הימיני של העמוד בהפסק קו מלמעלמ\"ט בינו ובין שני הקטעים שנרשמו זה אחר זה. וסודרו כאן כפי שהם מופיעים בבוך תרמ\"א 2086 — כת\"י מעתיק.\n\n<b>ו</b> ) <b>יו\"ד דחכ' וא\"ו ד' כלולים בו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380316\" data-slug=\"likkutei-torah\" data-id=\"4001380316\">לקו\"ת במדבר ב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380549\" data-slug=\"likkutei-torah\" data-id=\"4001380549\">חוקת נח, ב</a>. מאמרי אדה\"א דברים ח\"ג ע' תשפה. סה\"מ תרכ\"ז ע' רסו וע' שעח. וש\"נ.\n\n<b>ז</b> ) <b>א' ב' יודי\"ן וא\"ו באמצע</b>: ראה זהר בראשית כו, א. ב. אנציק' תלמודית בערכו. ספר הערכים חב\"ד בערכו ע' פ ואילך. וע' קצג ואילך.\n\nח)הוא\"ו . . יו\"ד בראש: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370012\" data-slug=\"torah-or\" data-id=\"3901370012\">תו\"א בראשית ג, ג</a>. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540182\" data-slug=\"torat-chaim\" data-id=\"2300540182\">תו\"ח בשלח ח\"א קנ, ג</a>. וש\"נ."]]],[2001910388,"שהנשמות ומלאכים שבעלמא דאתכסיא נק' בשם נוני<sup data-n=\"3909\">37</sup> ימא<sup data-n=\"3908\">36</sup> ע\"ש שהם בטלים בתכלית במקור חיותם הוא האין אשר מהוה אותם וא\"י ליפרד ממנו כלל כמו דגים הגשמיים שמיד שפורשים<sup data-n=\"3910\">38</sup> מן המים ה\"ה מתים מפני שנפסק קבלת חיותם כו', שמוכרחים להיות תמיד במקום הווייתם דוקא, מפני שהם נבראו באופן כזה. (ובזה יתורץ דלכאו' שרש ענין שם בריאה הוא שנעשה יש ודבר נפרד, פי' כי ענין בריאה הוא דבר חדש מה שלא הי' תחלה, כמו ואם בריאה יברא<sup data-n=\"3911\">39</sup> שפירושו, שאם כבר נברא פה לארץ, א\"צ שיברא כעת, ואם לא נברא עד עכשיו יברא היינו שיהי' דבר חדש מה שלא הי' עד כה, ועד\"ז יובן ענין בריאת יש מאין, היינו כי אצילות הוא בחי' גילוי ההעלם<sup data-n=\"3912\">40</sup> כו' כנודע וכמ\"ש במ\"א, וא\"כ אין זה דבר חדש כלל, כ\"א בריאה הוא דבר חדש, היינו שיהי' מציאת איזה דבר שא\"ז גילוי ההעלם כ\"א נברא להיות מציאות יש ודבר מאין<sup data-n=\"3913\">41</sup> ואפס המוחלט, וכמ\"ש מזה במ\"א באריכות, ולפ\"ז בדגים שבים עד\"מ שהם נבראים בע\"ג נמצאים ליש ודבר נפרד, כמו הנבראים שנבראו ונוצרו ונעשו ביבשה, ועכ\"ז נמצא בהם בחי' הביטול כ\"כ עד שכאשר יפרדו ממקום הוויתם היינו מבחי' האין המהוה אותם הם מתבטלים לגמרי שזהו לכאו' היפך בחי' המציאות והפירוד שזהו שרש ענין בחי' התחדשות הבריאה כו'. אך ע\"פ הנ\"ל יתורץ זה שנבראו באופן כזה פי' שנתחדשו מאין להיות מציאות יש חי באופן כזה דהיינו שיהי' מובלע תמיד בבחי' האין המהוה אותו אז יהי' בו חיותו שיורגש ענין מציאותו שזהו פי' וענין חי כו', משא\"כ כאשר יובדל ממקורו הוא האין נפסק חיותו הוא בחי' הרגש עצמותו היינו בחי' חיות שלו, והגוף קיים רק בלתי חי (כי הגוף יש לו שרש בפ\"ע<sup data-n=\"3914\">42</sup> ושרשו מבחי' הרשימו<sup data-n=\"3915\">43</sup> ובמ\"א נת' שזהו בחי' סוכ\"ע<sup data-n=\"3916\">44</sup> כמ\"ש במ\"א). ועד\"ז יובן במלאכים ונשמות דבריאה שהם הנק' בשם נוני ימא שאם<sup data-n=\"3917\">45</sup> היות שהם נבראים",[["3909","37","<b>ומלאכים . . נוני ימא</b>: ראה זהר בשלח מח, ב ובמק\"מ שם. ביאורי הזהר בשלח מא, סע\"ג. מב, ג. ולהצ\"צ כרך א ע' רח. ע' ריב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380110\" data-slug=\"likkutei-torah\" data-id=\"4001380110\">לקו\"ת צו ח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380150\" data-slug=\"likkutei-torah\" data-id=\"4001380150\">שמיני יח, א</a>."],["3908","36","<b>שהנשמות . . נוני ימא</b>: ראה ביאוה\"ז בשלח מא, סע\"ג [ושם: דמשמע בזהר בכמה דוכתי]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540223\" data-slug=\"torat-chaim\" data-id=\"2300540223\">תו\"ח בשלח ח\"א רז, א</a>. וש\"נ. סה\"מ תרל\"א ח\"א ע' רסה. תרל\"ט ח\"ב ריש ע' תח. ע' תקפג. לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ ובהערה 71."],["3910","38","<b>דגים הגשמיים שמיד שפורשים</b>: ראה ע\"ז ג, ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 34."],["3911","39","<b>ואם בריאה יברא</b>: קרח טז, ל. ראה רש\"י שם."],["3912","40","<b>אצילות . . גילוי ההעלם</b>: ראה עבודת הקודש חלק היחוד פ\"ב. מערכת האלקות פ\"ג. פרדס שער אבי\"ע שט\"ז, פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370339\" data-slug=\"torah-or\" data-id=\"3901370339\">תו\"א משפטים עו, ב</a>. סה\"מ תרל\"א ח\"א ע' קלח. וש\"נ. תר\"ם ח\"ב ע' תשמא. וש\"נ."],["3913","41","<b>בריאה הוא דבר חדש . . מאין</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א (נוסח א') ע' רצב ואילך [אוה\"ת ואתחנן ע' רכח]. שם (נו\"ש) ע' רצד ואילך [אוה\"ת ואתחנן ע' קפז. ס' החקירה להצ\"צ ע' 112]. שער האמונה נ, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540582\" data-slug=\"torat-chaim\" data-id=\"2300540582\">תו\"ח בשלח ח\"א קלח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540357\" data-slug=\"torat-chaim\" data-id=\"2300540357\">קמו, א</a>."],["3914","42","<b>הגוף יש לו שרש בפ\"ע</b>: ראה סידור ערב שבת קסה, ד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490145\" data-slug=\"or-hatorah-hb\" data-id=\"8316490145\">אוה\"ת וירא כרך ד ע' תשמב</a>. סה\"מ עזר\"ת ע' קסה."],["3915","43","<b>הגוף . . הרשימו</b>: ראה מאמרי אדה\"ז על ענינים ע' שיז. תקס\"ז ע' רמה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680084\" data-slug=\"torat-chaim\" data-id=\"2300680084\">תו\"ח ויגש רל, ד</a> ובהערה 41. שעה\"י קל, א. סה\"מ תרס\"ד ע' קלט."],["3916","44","<b>שזהו בחי' סוכ\"ע</b>: ראה גם אוה\"ת דרושים לשמ\"ע ע' א'תשפד. שה\"ש כרך ב' ע' תצג. המשך וככה תרל\"ז פפ\"ט."],["3917","45","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."]]],[2001910389,"עכ\"ז אופן קבלת חיותם הוא שיהיו מובלעי' במקור חיותם פי' שיהי' תמיד בטלים בבחי' האין המהוה אותם ולא יהי' נפרדים ממנו לגמרי, כ\"א בזאת הם נפרדים במה שמרגישים חיותם להרגש מציאות נבדל כמו אדם חי שמרגיש חיותו, משא\"כ כשנפרדים ממקורם ה\"ה מתים היינו שנפסק הרגש חיותם כמו המת שנפרד נשמתו המחי' הגוף, שהגוף קיים לפי ששרשו הוא מבחי' סוכ\"ע, וחיותו מבחי' ממכ\"ע נפרד מהגוף כו'.\n<b>ובמ\"א</b> נת' שלפי שעולם הבריאה הוא ראשית התהוות היש לכן שם מורגש יותר בחי' האין<sup data-n=\"3918\">46</sup> המהוה היש. וגם לפי' זה מוכרח לומר שגם לאחר שמרגישים את האין יותר מ\"מ בחי' האין הוא בבחי' העלם והסתר מהם, דאל\"כ לא הי' יכול להוות ע\"ד יש מאין כ\"א בחי' השתלשלות עו\"ע כמ\"ש בד\"ה מי כמוכה באלים<sup data-n=\"3919\">47</sup> באריכות, וגם לא הי' נק' בשם אין, כי ש' אין פירושו שאינו מושג<sup data-n=\"3920\">48</sup> כמו והחכ' מאין תמצא<sup data-n=\"3921\">49</sup> שנק' בשם בחי' מציאה שענין המציאה פירושה שלא נודע כלל מאין באה, עד שחייב להכריז<sup data-n=\"3922\">50</sup> אולי יתודע ע\"י הסימנים מי הוא בעל החפץ הזה כו'. ועד\"ז פי' האין המהוה היש הוא ג\"כ על דרך זה שהוא אינו מושג כלל, דאל\"כ אינו נק' אין כ\"א עילה כו'. וא\"כ במה יודע איפה בבחי' עולם הבריאה בחי' האין מאשר יודע ביצירה ועשייה כו', א\"ז כ\"א בבחי' ידיעות<sup data-n=\"3923\">*51</sup> המציאות ובהרגש חיותו שמה שהוא חי ה\"ה מרגיש יותר שיש דבר המחי' ומהוה אותו מכמו ההרגש ביצירה ובעשייה כו', ונברא באופן כזה שיהי' תמיד מובלע בחיותו, וכשיפסוק מלהיות מובלע יופסק חיותו. כמו שמצינו גם בנבראים שביבשה כמו בצומח שכ\"ז שצומחים מוכרחים להיות מקושרים להארץ, וכשיבדילו ביניהם לא יצמח כלל, רק לאחר שכבר נצמח אז יכולים להבדילו מהארץ, ובברואים שבים גם לאחר שכבר נגדל כל צרכו מוכרח להיות במים שאל\"כ יופסק חיותם. ועפ\"ז יובן שבנשמות שמעלמא דאתכסיא שמפני שמוכרחים להיות תמיד מובלעים במקורם הוא בחי' האין המהוה אותם, לכן גם בהיותם מלובשים בגוף בעשייה הגשמיית בחי' ארץ שאם היות חיבור נשמתם בגופם הגשמי תלוי באכו\"ש הגשמיות שמקבלים חיותם מהארץ גם בהיותם נפרדים ממנה כמו בהיותם באויר או שטים ע\"פ המים, וגם כל עיקר קבלת חיותם אינו ע\"ד להיות מובלע (כמו כל הנבראים שמעלמא דאתגלייא<sup data-n=\"3924\">51</sup> כו') מ\"מ שרש נפשם גם בהיותם בגוף הוא מובלע בבחי' האין המהווהו כו', וה\"ה נברא שיש בו בחי' ביטול יותר מכמו הנבראים שמעלמא דאתגלי', וע\"ד משה דכתיב בו מן המים משיתיהו<sup data-n=\"3925\">52</sup>, פי' שנמשך מעלמא דאתכסיא לעלדאת\"ג, הי' כבד פה וכבד לשון<sup data-n=\"3926\">53</sup> שלא הי' יכול",[["3918","46","<b>שעולם הבריאה . . מורגש . . האין</b>: ראה גם סה\"מ תרנ\"ב ס\"ע ח ואילך. תרנ\"ד ע' קנז. הגהות לד\"ה פתח אלי' תרנ\"ח ע' לו. תרס\"ב ע' שנז. המשך תרס\"ו ע' תפד."],["3919","47","<b>בד\"ה מי כמוכה באלים</b>: סה\"מ תרכ\"ט ע' קסא."],["3920","48","<b>אין פירושו שאינו מושג</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א בשלח סו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380259\" data-slug=\"likkutei-torah\" data-id=\"4001380259\">בהר מב, ד</a>."],["3921","49","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["3922","50","<b>המציאה . . שחייב להכריז</b>: ב\"מ כא, א במשנה."],["3923","*51","<b>ידיעות</b>: כ\"ה בגוכתי\"ק."],["3924","51","<b>שמעלמא דאתגלייא</b>: ראה לעיל הערה 35."],["3925","52","<b>מן המים משיתיהו</b>: שמות ב, י. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>."],["3926","53","<b>כבד פה וכבד לשון</b>: שמות ד, י."]]],[2001910390,"להשפיל א\"ע גם בבחי' התורה שמקרא בעשייה ומשנה ביצירה<sup data-n=\"3927\">54</sup>, לכן הי' כבד פה לגבי תושבע\"פ וכבד לשון לגבי תושב\"כ<sup data-n=\"3928\">55</sup> כו', וגם בהיותו בגוף אמר ע\"ע ונחנו מה<sup data-n=\"3929\">56</sup> שהי' תמיד בבחי' מה כו'.\n<b>ועד\"ז</b> יובן שאם הי' נברא העולם מבחי' מאמר אחד, היו כל העולמות בטלים בתכלית, ולא הי' בחירה כלל, וממילא לא הי' שכר ועונש, ולכן כדי להפרע כו' וליתן שכ\"ט לזה נברא בע\"מ היינו שנפרטו אח\"כ בבחי' הדבור עד שנוצרו ונעשו עולמות שהם בבחי' מציאות היש כ\"כ עד שמסתירים על בחי' האין המהוה אותם, ואינם בבחי' הביטול, וכמו עד\"מ ברואים שביבשה שאם היות שקבלת חיותם הוא מן הארץ, שהרי ארץ ממנה יצא לחם<sup data-n=\"3930\">57</sup>, ואם יושבת ח\"ו צמיחת הארץ כל צמח האדמה יופסק חיות כל הנבראים שע\"פ האדמה, מ\"מ הנבראים שבארץ הנם נפרדים מן הארץ, שגם בעת קבלת חיותם אינם מוכרחים להיות מובלע בארץ כו', ורק הצומח בעת צמיחתו מוכרח להיות מחובר כנ\"ל, שי\"ל שז\"ע הוויתו כו' שבכ\"י מתהוה מעט מעט עד שמתגדל ואז א\"צ לארץ המגדלו כו'. ועד\"ז יובן בנבראים שמעלמא דאתגליא שאם היות שמקבלים חיותם מבחי' האין המהוה אותם עכ\"ז החומר מסתיר כ\"כ עד שגם כשמרגיש בחי' האין המהוה אותו עכ\"ז אינו בטל ומובלע בו ע\"ד בחי' הנבראים מלאכים ונשמות שנק' בשם נונא ימא כו', והבחירה ניתנה חפשית, ולכן יש שכר ועונש, וזהו כדי להפרע וליתן שכ\"ט כו' שמציאות זה זהו דוקא כאשר נברא בע\"מ משא\"כ אם הי' נברא ממאמר אחד כו' וכנ\"ל.\n\nולכאו'<sup data-n=\"8650\">ט</sup> צ\"ל א\"כ לא הי' משה בעל בחירה, וגם איך נענש בצרעת ע\"ז שהוציא דיבה<sup data-n=\"8651\">י</sup> במה שא' הן לא יאמינו<sup data-n=\"8652\">יא</sup> כו', שמזה מובן שהוא בעל בחירה, וצ\"ל שבחיבור נשמה בגוף בזה תלוי בחירתו, אך א\"כ הי' אפשר לברוא במ' א' ועכ\"ז הי' הבחירה חפשית, וצ\"ל שמפני שנברא בע\"מ לכן גם בנשמות דנונא ימא הבחירה חפשית, משא\"כ אם הי' נברא במא' א', אך א\"כ איך א' יוכל להבראות הלא לא הי' בחירה, וגם איך יתורץ יוכל להבראות הלא נברא תומ\"י כשעלה ברצונו.",[["3927","54","<b>שמקרא בעשייה ומשנה ביצירה'</b>: ראה פע\"ח שער הנהגת הלימוד שי\"ז. תניא פ\"מ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, סע\"א</a> ואילך. מאמרי אדה\"א נ\"ך ע' קלט. וש\"נ."],["3928","55","<b>כבד פה . . תושבע\"פ . . תושב\"כ</b>: ראה זהר רע\"מ צו כח, א. לעיל מאמר ד\"ה להבין וכו' בענין הציץ ובהערה 162."],["3929","56","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 140."],["3930","57","<b>ארץ ממנה יצא לחם</b>: איוב כח, ה. ראה גם סה\"מ תר\"ם ח\"א ע' רלה.\n\n<b>ט</b> ) <b>ולכאו'</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. ראה בפנים פיסקא הבאה.\n\n<b>י</b> ) <b>משה . . בצרעת . . דיבה</b>: שמות ד, ו וברש\"י.\n\n<b>יא</b> ) <b>הן לא יאמינו</b>: וכ\"ה בדב\"ר פ\"ט, ו. תנחומא שמות כג. רש\"י יומא יט, ב ד\"ה החושד — שמות שם, א [ושם: והן — וכ\"ה בסמוך בפנים על יד הערה 61]."]]],[2001910391,"אך הנה עדיין צ\"ל שלפי משנת\"ל שאם הי' נברא במאמר אחד לא הי' בחירה כלל ושזהו כמשל הנבראים שנק' בשם נוני דימא רבא<sup data-n=\"3931\">58</sup> כו', דאינו מובן היתכן לומר שהמלאכים ונשמות שמעלמא דאתכסיא כמו משה וכדומה לא היו בעלי בחירה, והלא מצינו שנענש משה על מי מריבה<sup data-n=\"3932\">59</sup> שמזה מוכרח לומר שהי' בו הבחירה חפשית, דאל\"כ איך הכה את הסלע<sup data-n=\"3933\">60</sup>, ואיך נענש, וגם בתחילת שליחותו למצרים כשאמר והן לא יאמינו לי<sup data-n=\"3934\">61</sup> נענש ע\"ז במה שלקה ידו בצרעת והיינו על שהוציא דיבה<sup data-n=\"3935\">62</sup> על ישראל שלא יאמינו כו', וא\"כ משה דכתי' משה משה ולא פסיק טעמא<sup data-n=\"3936\">63</sup> שנת' פירושו במ\"א שמשה כמו שהי' למעלה כן נמשך גם למטה בלי שינוי, מ\"מ הי' הבחירה אצלו חפשית כ\"ש שאר הנבראים שמעלמא דאתכסיא שלא נא' בהם כעין שנא' במשה ולא פסיק כו' בודאי שאצלם הבחירה חפשית, וא\"כ גם אם הי' נברא במא' אחד ג\"כ הי' הבחירה חפשית, ולפ\"ז הי' גם שכר ועונש ולמה נברא בע\"מ כו', הלא שכר ועונש יכול להיות גם ממאמר אחד, והדרא קושי' לדוכתי' שהיתכן כשמאבד חפץ שמחירו זהב אחד יצטרך לשלם עשרה זהובים<sup data-n=\"3937\">64</sup> מפני שבעל החפץ שילם עבורו עשרה זהובים כו'.\n<b>אך</b> הענין יובן ע\"פ משנת\"ל<sup data-n=\"3938\">65</sup> בענין וכדי ליתן שכ\"ט לצדיקים שמקיימים כו' פי' שממשיכים בחי' מאמר אחד בעולם, היינו להיות בחי' גוי אחד בארץ<sup data-n=\"3939\">66</sup>, שגם בארץ בחי' טורי דפרודא<sup data-n=\"3940\">67</sup> עכ\"ז יהי' גם בארץ בחי' אחד<sup data-n=\"3941\">68</sup>.\n\nוהענין<sup data-n=\"8653\">יב</sup> עדאת\"כ ג\"כ עולם הנברא ובה שכר ועונש, ואינו משל למא' אחד אלא ע\"ד שנמצא הביטול בעדא\"ת<sup data-n=\"8654\">יג</sup> ע\"ד<sup data-n=\"8655\">יד</sup> יובן איך בשרש ומקור מא' אחד הנ\"ל, ב' י\"ל שמה שיש בחירה בנבראים דנונא ימא זהו כשנפרטו בט' מאמרות<sup data-n=\"8656\">טו</sup>, והגם כי עדאתכ\"ס זהו מבחי' מח' מאמר אחד עכ\"ז הלא נשמה שנתת כו' בראת אתה נפחת<sup data-n=\"8657\">טז</sup> שירדה בעשי' לכן הגם כי לא פסיק טעמא מ\"מ אזלית לקרתא עבדית כנמוסהא<sup data-n=\"8658\">יז</sup>, ולכן גם משה הי' בעב\"ח<sup data-n=\"8659\">יח</sup>, משא\"כ אם הי' נברא במאמר אחד לא הי' מציאות נפרד לגמרי כו', ויובן זה מהמשכת הצדיקים בחי' מא' אחד ומ\"מ אינו מתבטל הבחירה אך מזה אין ראי' ע\"ד שאינו מתבטל העולם מהמשכת הקו כו',\nויובן מענין ד\"ע וד\"ת שד\"ע אינו מכריח הבחירה, ומ\"מ בד\"ת הוא ישר כמו בד\"ע, ועד\"ז מאחר<sup data-n=\"8660\">יט</sup>.",[["3931","58","<b>נוני דימא רבא</b>: זהר בלק קפח, א."],["3932","59","<b>שנענש משה על מי מריבה</b>: חוקת כ, יב-יג."],["3933","60","<b>איך הכה את הסלע</b>: חוקת שם, יא."],["3934","61","<b>והן לא יאמינו לי</b>: שמות ד, א."],["3935","62","<b>נענש . . שלקה ידו בצרעת . . דיבה</b>: שמות שם, ו וברש\"י."],["3936","63","<b>משה משה ולא פסיק טעמא</b>: שמות ג, ד. זהר וירא קכ, ב. נשא אד\"ר קלח, א. בלק קפז, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370336\" data-slug=\"torah-or\" data-id=\"3901370336\">תו\"א משפטים עה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">עו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550300\" data-slug=\"torat-chaim\" data-id=\"2300550300\">תו\"ח משפטים ח\"ב רפג, ג</a>. וש\"נ. סה\"מ תר\"ל ע' נו ואילך."],["3937","64","<b>כשמאבד חפץ . . עשרה זהובים</b>: ראה גם לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ ובהערה 39."],["3938","65","<b>משנת\"ל</b>: מאמר ד\"ה כי תבואו כו' ושבתה הארץ רפ\"ה. ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום על יד הערה 39 ואילך."],["3939","66","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דברי הימים-א יז, כא."],["3940","67","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א. ראה גם לעיל מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע הערה 94."],["3941","68","<b>גם בארץ בחי' אחד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו\"א וישב כז, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380519\" data-slug=\"likkutei-torah\" data-id=\"4001380519\">לקו\"ת שלח נא, ד</a>. לעיל מאמר ד\"ה כי תשא ובהערה 21.\n\n<b>יב</b> ) <b>והענין</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. קטעים אלו נרשמו א) חלק בשולי היריעה ב) בצד הימיני של העמוד בהפסק קו מלמעלמ\"ט בינו ובין חלק א. ג) בהיפך הע' ממעל לחלק א.\n\n<b>יג</b> ) <b>בעדא\"ת</b>: אולי צ\"ל: בעדאת\"כ.\n\n<b>יד</b> ) <b>ע\"ד</b>: בבוך תרמ\"א 2086 — כת\"י מעתיק: עד\"ז.\n\n<b>טו</b> ) <b>כשנפרטו בט' מאמרות</b>: ראה גם לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ הערה 41.\n\n<b>טז</b> ) <b>נשמה . . אתה נפחת</b>: ראה ברכת אלקי נשמה (מברכות ס, ב).\n\n<b>יז</b> ) <b>אזלית לקרתא עבדית כנמוסהא</b>: ראה גם עד\"ז סה\"מ תרל\"א ח\"א ע' סז. ע' עה. תרל\"ב ח\"א ס\"ע סה. תרמ\"ג ע' לב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101208\" data-slug=\"likkutei-sichot\" data-id=\"1300101208\">לקו\"ש ח\"ש כרך י' ע' 208</a>. וירא כרך כה ע' 78. ח\"י אלול תשמ\"ה כרך כט ע' 299 בשם חז\"ל. וש\"נ. ובאו\"א סה\"מ תרכ\"ט ע' קו.\nראה שמו\"ר פמ\"ז, ה. וש\"נ. ילקוט שמעוני וירא יח, ח רמז פב מהדורת ירושלים תשל\"ג ע' 361. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730240\" data-slug=\"likkutei-sichot\" data-id=\"1301730240\">לקו\"ש תשא כרך לו ע' 172</a> ואילך.\n\n<b>יח</b> ) <b>בעב\"ח</b>: בעל בחירה.\n\n<b>יט</b> ) <b>מאחר</b>: בבוך תרמ\"א 2086 — כת\"י מעתיק: מאמר."]]],[2001910392,"<h3>בעשרה מאמרות נברא העולם</h3>\n<b>בס\"ד</b>\n<b>בעשרה</b><sup data-n=\"3942\">1</sup> מאמרות נבה\"ע כו' והלא במא' אחד יכול להבראות, אלא כדי<sup data-n=\"3944\">3</sup> להפרע כו' שמאבדי' כו' וליתן שכ\"ט לצדיקים<sup data-n=\"3945\">4</sup> שמקיימים<sup data-n=\"3943\">2</sup> כו', והקשו המפרשים למה מגיע עונש מר כ\"כ לרשעים על שמאבדים את העולם שנברא",[["3942","1","<b>בעשרה מאמרות נבה\"ע</b>: מאמר זה הוא מאמר הד' מההמשך דמאמר ד\"ה כי תבואו וכו' ושבתה הארץ שנדפס לעיל.\nהמאמר — רק חלק — נרשם בגוכתי\"ק.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו [ושם הכותרת: ש\"פ בחקתי — ראה הנרשם לעיל במאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום בתחילתו]."],["3944","3","<b>כדי</b>: כ\"ה גם במחזור וויטרי כאן. במשנה שנדפסה בפירושי ראשונים למס' אבות פי' רש\"י (וכו') ירושלים תשל\"ג ע' ל. רבינו יונה כאן. נחלת אבות אברבנאל ס\"ע רצו ד\"ה החמישית (אבל ראה שם ע' שב ד\"ה אלא). ועוד. לעיל מאמר ד\"ה כי תבואו וכו' ושבתה הארץ ספ\"ד ואילך (אבל ראה שם פ\"ב על יד הערה 37). ד\"ה כל אשר חפץ ה' עשה על יד הערה 34. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 3. סה\"מ תרכ\"ו ע' קמד. תרל\"ב ח\"ב ע' תלט. תרל\"ח ע' רעח — נדפס גם באוה\"ת בראשית כרך ו ע' 2076. תרמ\"ד מהדורת תשס\"ב ע' שטז."],["3945","4","<b>שמקיימים</b>: במשניות: שמקימין."],["3943","2","<b>בעשרה מאמרות . . לצדיקים שמקיימים</b>: אבות רפ\"ה."]]],[2001910393,"בע\"מ, מאחר שבמאמר א' יכול להבראות<sup data-n=\"3947\">6</sup>, א\"כ למה יענשו עבור מה שנברא בע\"מ, ובמד\"ש הביא משל<sup data-n=\"3946\">5</sup> ע\"ז לאחד שקנה חפץ ששוה זהוב אחד, ושילם עבורו עשרה זהובים, ונגנב, ונמצא הגנב, היתכן שיצטרך לשלם עשרה זהובים מפני שזה שילם עבורו עשרה זהובים, והלא אינו שוה כ\"א זהב אחד. ונת' התירוץ ע\"ז<sup data-n=\"3948\">7</sup>, שמה שא' במא' א' יכול להבראות זהו המאמר כללי, שזהו מ\"ש בזהר במח' א' נבראו כל העולמות<sup data-n=\"3949\">8</sup>, ובע\"ח בתחילתו כשעלה ברצונו הפשוט<sup data-n=\"3950\">9</sup>, וכמשנ\"ת שם<sup data-n=\"3951\">10</sup> בענין כי לא מחשבותי מחשבותיכם<sup data-n=\"3952\">11</sup> שתומ\"י כשעלה ברצונו מיד נתהוה, רק שאם הי' נשאר התהוות כל העולמות כמו שנתהוו מבחי' המח' היו העולמות בטלים בתכלית ע\"ד עלמא דאתכסיא<sup data-n=\"3953\">12</sup> ויותר כו', ולא הי' בחי' בחירה כלל, ולכן נפרטו אח\"כ בט' מאמרי' פרטי'<sup data-n=\"3954\">13</sup> בכדי שיהי' מציאות צדיקים ורשעים ע\"י הבחירה שהבחירה חפשית כו' ע\"ש, ונמצא מה שנברא בע\"מ זהו מוכרח כו'.\n<b>והנה</b> מאמר א' היינו מאמר הכללי הנ\"ל לפי פי' הגמרא בר\"ה דל\"א ע\"א<sup data-n=\"3955\">14</sup>, ובמגילה דך\"א ב' הוא בראשית, שאמרו שם והלא ט' ויאמר הן, בראשית נמי מאמר הוא דכתי' בדבר ה' שמים נעשו<sup data-n=\"3956\">15</sup>, וא\"כ מ\"ש בראשית כו' השמים<sup data-n=\"3957\">16</sup> כאילו נא' ויאמר יהי שמים. ונמצא כי זהו פי' ג' בתיבת בראשית, שהת\"א מפרש בראשית בקדמין, ובת\"י מפרש בראשית בחוכמתא, ולפי פי' הגמרא בראשית בדבר. והנה לפי פי' השני שנת' בד\"ה כי תבואו כו' ושבתה<sup data-n=\"3958\">17</sup>, שהמא' אחד הוא נמוך במעלה מן הע\"מ יתפרש היטיב פי' הגמ', וכמשנ\"ת שם שגם במא' א' הוא בחי' דבר ה' הי' יכול להבראות ג\"כ, אלא שנברא העולם בוויתור היינו מה שנברא בע\"מ, ולכן יובן היטיב ענין השכר ועונש שמגיע לצדיקים ורשעים, שמקיימים או מאבדים חפץ היותר יקר כו', ויתפרש בראשית היינו בחי' ראשית חכ' דח\"ת, ומ\"ש ה' בחכ' ג\"כ על בחי' ח\"ת כו'. אך לפי פי' הראשון שמאמר אחד הוא בחי' הכלל שכולל כל פרטי ההשתשלות והוא בחי' מח' א' כו', שלפי' הת\"י וכ\"ש לפי' הת\"א יתפרש היטיב כמשי\"ת, אבל לפי' הגמ' שבראשית הוא בחי' דבור איך יתפרש זה שיהי' מאמר זה היותר כללי שיוכלל",[["3947","6","<b>מגיע עונש . . שבמאמר א' יכול להבראות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410069\" data-slug=\"likkutei-sichot\" data-id=\"1301410069\">לקו\"ש בראשית כרך ל ע' 4</a> ואילך."],["3946","5","<b>והקשו המפרשים . . ובמד\"ש הביא משל</b>: ראה גם לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ ובהערה 39."],["3948","7","<b>ונת' התירוץ ע\"ז</b>: לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ ספ\"ב ואילך."],["3949","8","<b>במח' א' נבראו כל העולמות</b>: ראה זהר שמות כ, א. שם תוספות רעו, סע\"ב. סידור שער התפלה יח, סע\"ד. סהמ\"צ להצ\"צ ע' קעח ואילך. מאמרי אדה\"א קונטרסים ע' תלא. וש\"נ."],["3950","9","<b>ובע\"ח בתחילתו כשעלה ברצונו הפשוט</b>: ראה שם דרוש עגו\"י ש\"א, ענף ב."],["3951","10","<b>וכמשנ\"ת שם</b>: לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ פ\"ג ואילך. ד\"ה כל אשר חפץ ה' עשה על יד הערה 20 ועל יד הערה 34 ואילך."],["3952","11","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a> ואילך. (הועתק ב) סה\"מ תר\"ם ח\"א ע' קלט ואילך ובהנסמן שם."],["3953","12","<b>עלמא דאתכסיא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["3954","13","<b>נפרטו אח\"כ בט' מאמרי' פרטי'</b>: ראה גם לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ הערה 41."],["3955","14","<b>בר\"ה דל\"א ע\"א</b>: לעיל שם מציין: בר\"ה דל\"ב ע\"א. ואולי גם כאן צ\"ל כן."],["3956","15","<b>בדבר הוי' שמים נעשו</b>: תהלים לג, ו."],["3957","16","<b>בראשית כו' השמים</b>: בראשית א, א."],["3958","17","<b>שנת' בד\"ה כי תבואו כו' ושבתה</b>: נדפס לעיל — ושם פ\"ה ד\"ה ועוי\"ל."]]],[2001910394,"בו כל הפרטים שנפרטו אח\"כ בט\"מ פרטי' כו'. וגם צ\"ל מ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"3959\">18</sup>, שנת' במ\"א שיש ב' פי' בתי' חסד יבנה, הא' שהעולם נבנה ע\"י בחי' החסד וכמ\"ש מכלכל חיים בחסד<sup data-n=\"3960\">19</sup>, ולמעלה חסד אינו כמו למטה חסד, שלמטה החסד הוא רק גרם ההשפעה, אבל למעלה החסד עצמו הוא ההשפעה כו' כמ\"ש במ\"א, והב' שכדי שיהי' בחי' התהוות העולמות צריכים לבנות בחי' החסד, כי אוא\"ס הוא לאו מכל אילון מדות<sup data-n=\"3961\">20</sup> איהו כלל כמ\"ש בת\"ז, וכדי שיהי' מקור לעולמות צ\"ל כמה צמצומי' עד שיבנה מדת החסד כו', כי ענין המדות זהו לזולת דוקא<sup data-n=\"3962\">21</sup>, וא\"כ בכדי שיתהווה בחי' זולת זהו ע\"י המדות כו' וכדכתי' זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"3963\">22</sup> וכדפרי'<sup data-n=\"3964\">23</sup> בזח\"ג שמיני דל\"ט ע\"א<sup data-n=\"3965\">24</sup>, וע' בד\"ה לסוסתי בלק\"ת דרוש השני<sup data-n=\"3966\">25</sup>, ולב' הפירושים אין זה כמו הג' פי' הנ\"ל בתיבת בראשית שהוא מאמר כללי שלפי' הגמ' הוא בחי' הדבור ולא מדות, ולהת\"י זהו בחי' חכ' ולא מדות, וכ\"ש להת\"א שמפרש בקדמין שזהו בחי' הכתר כו'.\n<b>ואמנם</b> בעצם ענין ג' פירושים הנ\"ל צ\"ל ג\"כ הלא מצינו דכתי' כל אשר חפץ ה' עשה בשמים ובארץ<sup data-n=\"3967\">26</sup> משמע שברה\"ע זהו מבחי' חפץ הוי' שחפץ הוא בחי' פנימיות הרצון<sup data-n=\"3968\">27</sup> כנודע, וה\"ז קרוב לפי' הת\"א בקדמין שי\"ל שבקדמין כולל גם בחי' חפץ פנימיות הרצון, אך לפי' הת\"י והגמ' צ\"ל קרא דכל אשר חפץ כו', וכתי' מה רבו מעשיך כו' כולם בחכ' עשית<sup data-n=\"3969\">28</sup>, שמשמע שהכל נתהוה ע\"י החכ' שזהו כפי' הת\"י בחוכמתא ברא, והיינו כולם בחכ' עשית בבינה<sup data-n=\"3970\">29</sup>, וע\"ז רומז ש' אלקים שאחר בראשית שהוא בחי' אלקים חיים דבינה<sup data-n=\"3971\">30</sup> שהוא מלך עולם<sup data-n=\"3972\">31</sup> כו', אך להגמ' ות\"א צ\"ל זה, וכתיב בדבר כו' שמים נעשו שזהו כפי' הגמ' שלכאו' אין זה מובן לפי' שני<sup data-n=\"3973\">32</sup>",[["3959","18","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 106."],["3960","19","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע. ראה גם לעיל מאמר ד\"ה כל אשר חפץ ה' עשה ובהערה 12."],["3961","20","<b>לאו מכל אילון </b> [בבוך תרמ\"א 2086 — כת\"י מעתיק: אלין]<b> מדות</b>: ראה ת\"ז בהקדמה יז, ב."],["3962","21","<b>המדות זהו לזולת דוקא</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ."],["3963","22","<b>זכור רחמיך . . מעולם המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם לעיל מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 32 ואילך."],["3964","23","<b>וכדפרי'</b>: בבוך תרמ\"א 2086 — כת\"י מעתיק: וכדפי'."],["3965","24","<b>דל\"ט ע\"א</b>: ראה גם לעיל מאמר ד\"ה כי תבואו כו' ושבתה הארץ הערה 88 שלכאורה צ\"ל: דל\"ח ע\"א."],["3966","25","<b>בד\"ה לסוסתי בלק\"ת דרוש השני</b>: שה\"ש יא, ד ואילך."],["3967","26","<b>כל אשר חפץ ה' עשה בשמים ובארץ</b>: תהלים קלה, ו."],["3968","27","<b>שחפץ . . פנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["3969","28","<b>מה רבו . . כולם בחכ' עשית</b>: תהלים קד, כד."],["3970","29","<b>כולם בחכ' עשית בבינה</b>: זהר תזריע מג, א."],["3971","30","<b>אלקים חיים דבינה</b>: ואתחנן ה, כג. ראה זהר יתרו סח, ב ובהגהות הרח\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קסח־ קונטרסים ע' תקמ."],["3972","31","<b>אלקים חיים . . מלך עולם</b>: ע\"פ ברכת יוצר. ירמי' י, י."],["3973","32","<b>שני</b>: ע\"כ נרשם בגוכתי\"ק."]]],[2001910395,"<h3>וחג הקציר בכורי מעשיך</h3>\n<b>וחג הקציר דחה\"ש</b>\n<b>וחג</b> הקציר בכורי מעשיך<sup data-n=\"3974\">1</sup> אשר תזרע<sup data-n=\"3975\">2</sup> כו', וי\"ל למה כל המועדים נק' ע\"ש התבואה<sup data-n=\"3976\">3</sup>, והם בזמן שנגמרת התבואה, כי חג הפסח הוא בחדש האביב וכמ\"ש למועד חדש האביב<sup data-n=\"3977\">4</sup> שהוא זמן קצירת שעורים<sup data-n=\"3978\">5</sup>, וחה\"ש הוא בזמן ביכורי חטים<sup data-n=\"3979\">6</sup> כו' וחג הסוכות נק' חג האסיף באספך את מעשיך מן השדה<sup data-n=\"3980\">7</sup> כו'. אך להבין זה י\"ל<sup data-n=\"3981\">8</sup> מ\"ש והי' אמונת עתך חוסן ישועות חכ' ודעת יראת ה' היא אוצרו<sup data-n=\"3982\">9</sup>, ומפרש בגמ'<sup data-n=\"3983\">10</sup> אמונת זה סדר זרעים כו'<sup data-n=\"3984\">11</sup>, עתך זה סדר מועד, חסן זה סדר נשים, ישועות זה סדר נזיקין, חכ' זה סדר קדשים, ודעת זה סדר טהרות, ואפילו הכי אי איכא<sup data-n=\"3985\">12</sup> יראת ה' אין אי לא לא<sup data-n=\"3986\">13</sup>, ובמדרש מביא משל ע\"ז<sup data-n=\"3987\">14</sup> משל לא' שהי' לו אלף מדות שמן ואלף מדות יין ואלף מדות סלת א' לו א' יש לך אוצר להניחם שם מוטב וא\"ל אין לך בידך כלום, כך אי איכא יראת ה' אין אי לא לא כו'. והנה להבין כ\"ז י\"ל מתחלה מה שאמרו שאמונת הוא סדר זרעים, והנה התוס' מביא בשם הירושלמי<sup data-n=\"3988\">15</sup> דלכך נק' אמונת",[["3974","1","<b>וחג הקציר בכורי מעשיך</b>: מאמר זה מיוסד על שני מאמרים והם א) מאמר ד\"ה זה. ב) מאמר ד\"ה והי' אמונת עתך שנמצאים בבוך ”מאלמים אלומים\" 1029.\nבוך זה ”מאלמים אלומים\" כולל הנחות כ\"ק אדמו\"ר מהר\"ש שנרשמו בגוכתי\"ק מדרושי אביו כ\"ק אדמו\"ר הצ\"צ משנת תרט\"ז — ראה גם לעיל מאמר ד\"ה להבין שרשי וביאור הדברים בענין הציץ הערה י.\nבבוך הנ\"ל נרשם מקודם מאמר הב' ד\"ה והי' אמונת עתך ואח\"כ מאמר הא' ד\"ה זה ובמפתח הספר נרשם על שני דרושים אלו: ”של רב\"ק\" היינו שהם העתק הנחותיו של ר' בעריל קאליסקער — ראה גם לעיל מאמר ד\"ה קדש ישראל לה' בהערה 1.\nמההנחות מדרוש זה אנו לומדים שהדרוש נאמר בשני פעמים, היינו עד לקמן סוף פיסקא עתך נאמר ביום א' דשבועות. ומפיסקא חסן לקמן על יד הערה 82 נאמר ביום ב דשבועות בפתיחה והי' אמונת עתך. ובבוך 810 באה כותרת (על מאמר הב'): בס\"ד שבת יום שני דחה\"ש.\nהמאמר הועתק בכת\"י מעתיק וניתוספו הגהות בע' בפ\"ע בגוכתי\"ק ואח\"כ נכתב עוה\"פ בכת\"י מעתיק בשילוב ההגהות.\nהכותרת שמופיעה בריש המאמר נלקחה מע' הגהות שנרשמו למאמר זה.\nהנחה מדרוש זה נדפסה לקמן בחלק ההנחות."],["3975","2","<b>וחג הקציר בכורי מעשיך אשר תזרע</b>: משפטים כג, טז."],["3976","3","<b>כל המועדים נק' ע\"ש התבואה</b>: ראה גם לעיל מאמר ד\"ה שלש רגלים תחוג לי בתחילתו. ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה ובהנסמן שם."],["3977","4","<b>למועד חדש האביב</b>: תשא לד, יח."],["3978","5","<b>האביב . . קצירת שעורים</b>: ראה מנחות סח, ב. אבן עזרא משפטים כג, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730177\" data-slug=\"likkutei-sichot\" data-id=\"1301730177\">לקו\"ש משפטים כרך לו ע' 109</a> ואילך."],["3979","6","<b>וחה\"ש . . ביכורי חטים</b>: תשא לד, כב."],["3980","7","<b>באספך את מעשיך מן השדה</b>: משפטים כאן כג, טז."],["3981","8","<b>זה י\"ל</b>: בבוך ”מאלמים אלומים\" הנ\"ל הערה 1: כל זה יש להקדים."],["3982","9","<b>והי' אמונת עתך . . היא אוצרו</b>: ישעי' לג, ו."],["3983","10","<b>ומפרש בגמ'</b>: שבת לא, א."],["3984","11","<b>כו'</b>: בגמ' שם ובבוך ”מאלמים אלומים\" הנ\"ל ליתא."],["3985","12","<b>אי איכא</b>: בגמ' שם ליתא. אבל כ\"ה גם בדרשות ר\"י אבן שועב פ' עקב [ירושלים תשנ\"ב ח\"ב ע' תלט]."],["3986","13","<b>אין אי לא לא</b>: תיבות אלו מובאים בגמ' שם להלן בדברי רבא. אבל כ\"ה גם בדרשות ר\"י אבן שועב שם."],["3987","14","<b>ובמדרש מביא משל ע\"ז</b>: ראה שמו\"ר פ\"ל, יד. הובא גם באוה\"ת ישעי' כרך א ע' רכ."],["3988","15","<b>התוס' מביא בשם הירושלמי</b>: ד\"ה אמונת שבת שם. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011230\" data-slug=\"likkutei-sichot\" data-id=\"1300011230\">לקו\"ש פורים כרך א ע' 216</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181249\" data-slug=\"likkutei-sichot\" data-id=\"1300181249\">מצורע ע' 240</a>. ובאגרותיו חי\"ח ע' רפא [ושם: אמונה זה סדר זרעים — אוצ\"ל: אמונת]. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151383\" data-slug=\"likkutei-sichot\" data-id=\"1300151383\">לקו\"ש חנוכה כרך טו ע' 370</a> בשולי היריעה שמציין שלפנינו בירושלמי ליתא."]]],[2001910396,"זרעים ע\"ש שמאמין בחיי עולם וזורע<sup data-n=\"3989\">16</sup>, ולכאו' אינו מובן<sup data-n=\"3990\">17</sup> מה שייך ע\"ז אמונה שמאמין בחיי עולם וזורע, שהרי טבעית העולם כך הוא כשזורעין הוא מצמיח ולמה צריכים לזה אמונה. אך הענין הוא, דהנה כתי' ויזרע יצחק בארץ ההיא<sup data-n=\"3991\">18</sup> שהמצות נק' בשם זריעה<sup data-n=\"3992\">19</sup> וכמ\"ש זרעו לכם לצדקה וקצרו לפי חסד<sup data-n=\"3993\">20</sup>, זורע צדקות מצמיח ישועות<sup data-n=\"3994\">21</sup>, אשריכם זורעי על כל מים<sup data-n=\"3995\">22</sup> כו', והנה הזריעה זהו ענין מ\"ש אור זרוע לצדיק<sup data-n=\"3996\">23</sup>, דהיינו אור שנברא ביום ראשון שהיו מביטין בו מסוף העולם ועד סופו<sup data-n=\"3997\">24</sup> שנא' בו וירא אלקים את האור כי טוב<sup data-n=\"3998\">25</sup> לגנוז<sup data-n=\"3999\">26</sup> והיכן גנזו בתורה<sup data-n=\"4000\">27</sup>, והאור הזה ע\"י המצות הוא נזרע, והיכן זרעו בג\"ע, וזהו אור זרוע לצדיק כו'.\n<b>(לענין</b> אור שנברא ביום ראשון כו' מסוף העולם ועד סופו, וגנזו בתורה כו', יש לבאר, שלכאו' צ\"ל מהו מסוף העולם כו' דהל\"ל מתחלת העולם כו', אלא שהכוונה בב' עולמות עלמא דאתכסיא ועלמא דאתגלי'<sup data-n=\"4001\">28</sup> כמ\"ש בביאור אם בחוקתי (רכ\"ו<sup data-n=\"4002\">29</sup>) ע\"ש באריכות, ויש להוסיף כי כלליות ההשתלשלות נכלל בב' עולמות אלו,",[["3989","16","<b>שמאמין בחיי עולם וזורע</b>: וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 70. בתוס' שם: שמאמין בחי העולמים וזורע. ראה גם ילקוט שמעוני תהלים יט, ח רמז רדעת: שהוא מאמין בחייו של עולם וזורע. ילקוט המכירי שם אות לא כנ\"ל. שוח\"ט שם: שהוא מאמין בחיי העולם וזורע [הובא גם בכד הקמח מערכת תורה ע' תכב]. במדב\"ר פי\"ג, טז בסופו: שאדם מאמין בחייו של עולם וזורע. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500455\" data-slug=\"or-hatorah-hb\" data-id=\"8316500455\">אוה\"ת שבועות ע' עט</a> בשם התוס': בחיי [אבל במהדורת תשנ\"ה: בחי]. וכ\"ה באוה\"ת הושע כרך א ס\"ע תנה — נדפס גם בביאוה\"ז —להצ\"צ— וישלח ח\"ב ע' תשו. המשך תער\"ב ח\"ב ע' א'ז: מאמין בחיי עולם וזורע."],["3990","17","<b>ולכאו' אינו מובן</b>: ראה גם אוה\"ת שבועות עט סע\"א ואילך. ישעי' כרך א ס\"ע רכ ואילך. הושע וביאוה\"ז שם."],["3991","18","<b>ויזרע יצחק בארץ ההיא</b>: תולדות כו, יב. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' רפ\"ב."],["3992","19","<b>שהמצות נק' בשם זריעה</b>: ראה גם תו\"א שמות נג, ג. סה\"מ תרל\"ח ע' תי ואילך. תר\"ם ח\"א ע' רסב. וש\"נ. לקמן פיסקא והטעם."],["3993","20","<b>זרעו . . וקצרו לפי חסד</b>: הושע י, יב [ושם: קצרו — ראה גם לעיל מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה ובהערה 71]."],["3994","21","<b>זורע צדקות מצמיח ישועות</b>: נוסח ברכת יוצר."],["3995","22","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' בסופו. ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה על יד הערה 85 ואילך."],["3996","23","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["3997","24","<b>אור שנברא . . מביטין . . סופו</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב. רמ\"ז לזהר ר\"פ במדבר. בפיסקא הבאה. לקמן (בחלק ההנחות) בהנחה כאן. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת נח כרך ו ע' 2136. סה\"מ תרכ\"ט ע' ס. וש\"נ. תר\"ם ח\"ב ע' תקצח. וש\"נ."],["3998","25","<b>וירא אלקים . . כי טוב</b>: בראשית א, ד."],["3999","26","<b>כי טוב לגנוז</b>: ראה זהר בראשית מה, סע\"ב. לקו\"ת שמ\"ע פט, ד. שה\"ש ד, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670529\" data-slug=\"torat-chaim\" data-id=\"2300670529\">תו\"ח נח עג, ד</a> ובהערה 23. ויקהל ח\"ב שצ, ב ובהערה 87."],["4000","27","<b>גנזו בתורה</b>: ראה (לקמן בחלק ההנחות) בהנחה כאן ובהערה 51 בשם הבעש\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו\"ת במדבר יח, ד</a> ובהנסמן במ\"מ לשם. פלח הרמון תזריע ע' קמא. וש\"נ."],["4001","28","<b>עלמא דאתכסיא ועלמא דאתגלי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["4002","29","<b>בביאור אם בחוקתי (רכ\"ו)</b>: סה\"מ תרכ\"ו ע' צו. נדפס גם בסה\"מ תר\"ל ס\"ע קמא ואילך.\nעד\"ז ”בביאור אם בחוקתי\" הובא גם בסה\"מ תרכ\"ז ע' קיט. תר\"ם ח\"ב ס\"ע תצח. תרמ\"ג ע' קמו. תרכ\"ו ע' וש\"נ."]]],[2001910397,"ע\"ד ג\"ע שיש ריבוי בחי' ועכ\"ז נכלל בב' בחי' ג\"ע התחתון והעליון<sup data-n=\"4003\">30</sup> כן הגם דכתי' ועלמות אין מספר<sup data-n=\"4004\">31</sup> שפירוש ועולמות אין מספר ע' בד\"ה אז ישיר עלי באר הקטן<sup data-n=\"4005\">32</sup>, שלא נדפס, עכ\"ז נכללי' בב' בחי' עדאת\"כ ועלדאת\"ג, שע\"ז שאה\"כ ברוך כו' מן העולם ועד העולם<sup data-n=\"4006\">33</sup> מעדאת\"כ לעלמדאת\"ג כו', ושרש ב' עולמות אלו הוא ב' שמות הוי' שלפני יגמה\"ר<sup data-n=\"4007\">34</sup> כמ\"ש בזהר ויצא כמדומה דקנ\"ו<sup data-n=\"4008\">35</sup>, שנמצא ש' הוי' דלעילא הוא שרש עדאת\"כ וש' הוי' דלתתא הוא שרש עלמא דאתגלי', והנה אור שנברא ביום ראשון איתא במד\"ר שהי' מכהה גלגל חמה<sup data-n=\"4009\">36</sup>, והיינו כי שמש ומגן ה' אלקים<sup data-n=\"4010\">37</sup>, ששמש הוא בחי' ש' הוי', ואור שנברא ביום ראשון, י\"ל ז' ימי בראשית ז\"ת דע\"י<sup data-n=\"4011\">38</sup>, ואור שנברא י\"ל<sup data-n=\"4012\">39</sup> חסד דעתיק וענין מה שאמרו לשון שנברא הוא מל' וברא אותם בחרבותם<sup data-n=\"4013\">40</sup> או שמא הבריא<sup data-n=\"4014\">41</sup> שא' עולא גבי ושט שניקב, שהוא לשון גילוי, וא\"כ בחי' אור זה גבוה גם מבחי' ש' הוי', וע' מענין חמה בלק\"ת בדרוש המילואים<sup data-n=\"4015\">42</sup> ובד\"ה שחורה אני, בענין משתשקע החמה, וגבי נר חנוכה<sup data-n=\"4016\">43</sup>, והאור הנ\"ל הי' מכהה גלגל חמה להורות שזהו למעלה מבחי' ש' הוי', וע' במד\"ר בפי' תולדות מלא<sup data-n=\"4017\">44</sup> שהעולם על מילואו נברא<sup data-n=\"4018\">45</sup> וזהו שהאיר אור שנברא ביום ראשון, ולכן הי' אדם מביט (פי' שלא נגנז עד לאחר השבת בראשית והביט אדה\"ר בו משעה שנברא עד לאחר השבת) מסוף העולם ועד סופו פי' בב' עולמות הנ\"ל עדאתכ\"ס ועדאת\"ג, ששרשם ב' שמות הוי', ראה שאין העולם כדאי פי' ראה הוא צמצום החכמה שנק' קצת דין",[["4003","30","<b>נכלל בב' בחי' ג\"ע התחתון והעליון</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 85."],["4004","31","<b>ועלמות אין מספר</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). ראה זהר אחרי עא, ב. ע\"ז לה, ב. סה\"מ תרל\"ה ח\"א ע' נג. תרל\"ח ע' ב ואילך. תר\"ם ח\"א ע' רלה. ח\"ב ע' תקצח."],["4005","32","<b>בד\"ה אז ישיר עלי באר הקטן</b>: אוה\"ת חוקת ע' תתמד ואילך."],["4006","33","<b>שע\"ז שאה\"כ </b> [כ\"ה בגוכתי\"ק]<b> ברוך כו' . . ועד העולם</b>: תהלים קו, מח־ דברי הימים-א טז, לו. ראה זהר ויצא קנח, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a>. וש\"נ."],["4007","34","<b>ב' שמות הוי' שלפני יגמה\"ר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041347\" data-slug=\"likkutei-sichot\" data-id=\"1300041347\">לקו\"ש אלול כרך ד ע' 1348</a> ואילך. ובאגרותיו ח\"ב ע' שסט ואילך."],["4008","35","<b>בזהר ויצא כמדומה דקנ\"ו</b>: ראה הערה 33."],["4009","36","<b>אור . . במד\"ר . . מכהה גלגל חמה</b>: ראה ב\"ר פ\"ג, ו. ילקוט שמעוני בראשית א, ה (רמז ה). ישעי' ל, כו (רמז תלו)."],["4010","37","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב."],["4011","38","<b>ז' ימי בראשית ז\"ת דע\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380113\" data-slug=\"likkutei-torah\" data-id=\"4001380113\">לקו\"ת צו ט, ב</a>. וש\"נ."],["4012","39","<b>שנברא י\"ל</b>: אוצ\"ל: שנברא ביום ראשון י\"ל."],["4013","40","<b>וברא אותם בחרבותם</b>: יחזקאל כג, מז [ושם: אותהן, וכ\"ה ברש\"י שברי\"ף לחולין שבהערה הבאה].\nאבל הלשון שבפנים הובא גם ברבינו גרשום ורש\"י חולין [שבהערה הבאה] ד\"ה אין חוששין. רש\"י סוכה מד, ב ד\"ה וחד אברויי אילני. ועוד. ועד\"ז הובא לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 42."],["4014","41","<b>שמא הבריא</b>: חולין מג, ב."],["4015","42","<b>בלק\"ת בדרוש המילואים</b>: צו י, סע\"א ואילך."],["4016","43","<b>ובד\"ה שחורה אני . . חנוכה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381159\" data-slug=\"likkutei-torah\" data-id=\"4001381159\">לקו\"ת שה\"ש ז, ג</a>."],["4017","44","<b>במד\"ר בפי' תולדות מלא</b>: בראשית ב, ד. ראה ב\"ר פי\"ב ו. שמו\"ר פ\"ל, ג. לעיל מאמר ד\"ה כי תבואו וכו' ושבתה הארץ ובהערה 101."],["4018","45","<b>שהעולם על מילואו נברא</b>: ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם). ראה גם תו\"ח ח\"ש קלד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש בראשית כרך כה ע' 14</a> ואילך."]]],[2001910398,"כמ\"ש החייט הובא במערכת<sup data-n=\"4019\">46</sup>, גנזו כמ\"ש וימנע מרשעים אורם<sup data-n=\"4020\">47</sup> שלא יאיר בחי' אור הנ\"ל, כי שם בעצם כחשיכה כאורה בשני כפין כמ\"ש בד\"ה מצה זו בלק\"ת<sup data-n=\"4021\">48</sup>, וע\"ד מ\"ש במד\"ר ועדיין א\"י באיזהו מהן חפץ<sup data-n=\"4022\">49</sup>, פי' שבבחי' חפץ הוא פנימיות הרצון<sup data-n=\"4023\">50</sup> היינו בחי' עת\"י א\"י איזהו מהן כי אינו תופס מקום כלל, רק כשראה ע\"י בחי' צמצום דחכ' כנ\"ל גנזו, והיכן גנזו גנזו בתורה לפי שאורייתא מחכמה נפקת<sup data-n=\"4024\">51</sup> שהוא בחי' מ\"ה המברר<sup data-n=\"4025\">52</sup>, שבחכ' אתברירו<sup data-n=\"4026\">53</sup>, שלא יומשך כ\"א למקום הראוי וכמ\"ש בלק\"ת ד\"ה מצה זו<sup data-n=\"4027\">54</sup> הנ\"ל בענין לי ולא לו, שזהו ונפלינו<sup data-n=\"4028\">55</sup> שבקש משה שגם מבחי' פלא לא יומשך כ\"א לי ולא לו כו', וע\"י הזריעה של המצות יומשך לע\"ל הצמיחה בחי' גילוי אור שנברא ביום ראשון כו').\n<b>והטעם</b> שנק' המצות בשם זריעה דהיינו כמו למשל הזריעה שזורעין גרעין שאין בו טעם וריח ונרקב מקודם בארץ ועי\"ז הוא נצמח<sup data-n=\"4029\">56</sup> ונעשה אילן עם פירות שטוב למראה ונחמד למאכל, וכן ע\"י הזריעה נעשה ברכה בתוס' וריבוי, וכך ע\"י מעשה המצות אף שנתלבשו בגשמיות מאד אעפי\"כ עי\"ז נעשה צמיחה והמשכה למעלה תוס' אורות עליונים, וזהו ענין סדר זרעים שהוא קאי על המצות שנק' בחי' זריעה, וזהו שמפרש התוס' שמאמין בחיי עולם וזורע לפי שע\"ז שייך אמונה שמאמין שעי\"ז שיעשה המצוה למטה עי\"ז יומשך מלמעלה תוס' אורות, כמו ע\"י ל\"ב חוטין דציצית ימשיך ל\"ב נ\"ח<sup data-n=\"4030\">57</sup> וכו' שלזה צריך אמונה שעפ\"י שכל אינו מושג כלל למה יהי' זה שע\"י שילבש ציצית ל\"ב חוטין עי\"ז יהי' נמשך ל\"ב נ\"ח כו', וזהו שסדר",[["4019","46","<b>כמ\"ש החייט הובא במערכת</b>: כנראה הכוונה כמ\"ש החייט על מה שהובא במערכת — ראה מערכת האלקות פ\"ד מערכת שמות המדות ד\"ה השני' בסופה ובפי' החייט שם [מנטובה שי\"ח נא, ב]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. סה\"מ תר\"ם ח\"א ע' שז. וש\"נ."],["4020","47","<b>וימנע מרשעים אורם</b>: איוב לח, טו."],["4021","48","<b>כחשיכה כאורה . . מצה זו בלק\"ת</b>: תהלים קלט, יב. ראה שם צו יב, א. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["4022","49","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370464\" data-slug=\"torah-or\" data-id=\"3901370464\">ועדיין א</a>\"י באיזהו מהן חפץ</b>: ראה ב\"ר פ\"ב, ה. פ\"ג, ח. תו\"א ויחי קה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200144\" data-slug=\"or-hatorah-hb\" data-id=\"8159200144\">אוה\"ת אמור כרך ג ע' תתנח</a>. בראשית כרך ג' ע' תז ואילך. שמיני כרך א ס\"ע נה ואילך. ע' ס. עקב ע' תקה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151178\" data-slug=\"likkutei-sichot\" data-id=\"1300151178\">לקו\"ש ח\"ש כרך טו ע' 178</a> הערה 49."],["4023","50","<b>חפץ הוא פנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["4024","51","<b>שאורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4025","52","<b>מ\"ה המברר</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["4026","53","<b>שבחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."],["4027","54","<b>בלק\"ת ד\"ה מצה זו</b>: צו יב, ג."],["4028","55","<b>ונפלינו</b>: תשא לג, טז. ראה גם סה\"מ תר\"ם ח\"א ע' שח. וש\"נ."],["4029","56","<b>גרעין . . ונרקב . . הוא נצמח</b>: ראה אגה\"ק ס\"ח (קיג, א). לעיל מאמר ד\"ה את חג המצות תשמור ובהערה 14."],["4030","57","<b>ל\"ב חוטין . . ל\"ב נ\"ח</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380523\" data-slug=\"likkutei-torah\" data-id=\"4001380523\">לקו\"ת קרח נב, ב</a>. ד."]]],[2001910399,"זרעים הוא כנגד מדת החסד<sup data-n=\"4031\">58</sup>, והיינו לפי שענין המצות הוא רק בחי' חסד שהוא המשכת אלקות כי רמ\"ח פקודין רמ\"ח אברים דמלכא<sup data-n=\"4032\">59</sup> שממשיכים גילוי חיות הנפש, וכן בדרך פרט כל סדר זרעים הוא רק בחי' חסד, שענין סדר זרעים הוא ענין מצות פיאה תרומות ומעשרות לקט שכחה<sup data-n=\"4033\">60</sup> כו', וזהו והי' אמונת זה סדר זרעים כו'*.\n\n<i>*)נרשם בשולי היריעה:</i>\n(ובחי'<sup data-n=\"8661\">א</sup> זו שבתורה שמחכ' נפקת זהו בחי' נובלות חכ' כמ\"ש בלק\"ת בד\"ה תורה ציוה<sup data-n=\"8662\">ב</sup> הנ\"ל<sup data-n=\"8663\">ג</sup> בענין ותמלא כדה, אמנם שרש התורה הוא מבחי' הכתר<sup data-n=\"8664\">ד</sup> לכן היא הכלי לבחי' האור שנברא ביום ראשון הנ\"ל, שבגמר הבירורים שבחכמה איתברירו יאיר בחי' אור הנ\"ל ונגלה כבוד ה'<sup data-n=\"8665\">ה</sup> ולא יכנף כו' והי' עיניך רואות<sup data-n=\"8666\">ו</sup> כו', וכתי' ובאו במערות צורים<sup data-n=\"8667\">ז</sup>, ובנקיקי<sup data-n=\"8668\">ח</sup> כו'<sup data-n=\"8669\">ט</sup> מפני פחד ה'<sup data-n=\"8670\">י</sup> וכו', י\"ל מה שעכשיו מזלייהו חזי<sup data-n=\"8671\">יא</sup> כמ\"ש בביאור בשעה שהקדימו בלק\"ת<sup data-n=\"8672\">יב</sup>, ובד\"ה יונתי בחגוי<sup data-n=\"8673\">יג</sup>, שרק מזלייהו שורש ומקור הנשמה כמו שהיא למעלה רואה ושומעת, וג\"ז רק חזי לשון תרגום<sup data-n=\"8674\">יד</sup> בחי' אחוריים<sup data-n=\"8675\">טו</sup> ע\"ד וראית את אחורי דכתיב במשה, אחוריים דאבא<sup data-n=\"8676\">טז</sup>, קשר של תפילין<sup data-n=\"8677\">יז</sup>, או גם אחורים מבחי' כבודך<sup data-n=\"8678\">יח</sup> דכתר ע' בד\"ה הנה אנכי שולח מלאך<sup data-n=\"8679\">יט</sup>, ובד\"ה הנה אנכי כורת ברית דר\"י<sup data-n=\"8680\">כ</sup>, ועד\"ז יובן ענין מזלייהו שפי' בלק\"ת בד\"ה האזינו<sup data-n=\"8681\">כא</sup> הראשון בסופו שזהו ב' מזלות דנוצר ונקה, ששם חזי אבל למטה רק חרדה גדולה נפל עליהם מחמת הרגש המקיף כו', אבל לע\"ל שיהי' ונגלה כבוד ולא יכנף בבחי' לבושי' המסתירים לכן יאיר בחי' יראה עילאה דבחי' מזלייהו חזי בגילוי גמור עד שיורגש כ\"כ בחי' פחד ה' שיבוא במערות צורים כמו ונצבת על הצור<sup data-n=\"8682\">כב</sup> דמשה, וע' בלק\"ת בד\"ה כי ביום הזה יכפר בפ' אחרי<sup data-n=\"8683\">כג</sup> בענין ושמתיך בנקרת הצור, ובנקיקי הסלעים י\"ל ע\"ד ההפרש בין קטנות לגדלות כמ\"ש במ\"א בענין צור וסלע ע\"פ המד\"ר כשהוא קטן<sup data-n=\"8684\">כד</sup> רבו מכה אותו ומלמדו משהגדיל בדברים הוא מיסרו ודברתם אל הסלע, מפני בחי' פחד הוא בחי' יראה עילאה, ואותה אנו מבקשים בר\"ה ויוהכ\"פ שנק' ימים נוראים מקור היראה<sup data-n=\"8685\">כה</sup> ובכן תן פחדך<sup data-n=\"8686\">כו</sup> הוא גילוי בחי' יראה עילאה וע\"ד ובמורא גדול זה גילוי שכינה<sup data-n=\"8687\">כז</sup> מל' דא\"ס<sup data-n=\"8688\">כח</sup> ממה\"מ כו', רק שביצ\"מ הי' באתעדל\"ע לבד<sup data-n=\"8689\">כט</sup> לפי שעה, ולע\"ל בגמר הבירורים שיהי' בחי' ישמח ה' במעשיו<sup data-n=\"8690\">ל</sup> שמח אינו אומר אלא ישמח עתיד הקב\"ה לשמוח, שהשמחה הוא מצד הגילוי, והגילוי גורם שמחה כמ\"ש בד\"ה מי יתנך<sup data-n=\"8691\">לא</sup> כיוסף לבנימין, וע' מענין ישמח ה' במעשיו בלק\"ת בד\"ה ה' לי בעוזרי פ\"ד<sup data-n=\"8692\">לב</sup>).",[["4031","58","<b>שסדר זרעים . . החסד</b>: ראה ת\"ז בהקדמה ה, א. ספרי הקבלה שבהערה 64. ביאוה\"ז וישלח יט, ד ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370096\" data-slug=\"torah-or\" data-id=\"3901370096\">תו\"א תולדות כ, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">ויצא כג, סע\"ג</a>. יתרו סט, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380453\" data-slug=\"likkutei-torah\" data-id=\"4001380453\">לקו\"ת בהעלותך לה, סע\"ד</a>. שה\"ש יט, ב. מאמרי אדה\"ז תקס\"ד ע' רלו. פיה\"מ לה, סע\"ג. תו\"ח ויקהל ח\"ב תלט, ד. וש\"נ. סה\"מ תרל\"ח ע' שסב. וש\"נ."],["4032","59","<b>רמ\"ח פקודין רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4033","60","<b>פיאה . . שכחה</b>: השווה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 72.\n\n<b>א</b> ) <b>ובחי'</b>: מכאן עד סיום הקטע לא הועתק בהעתק ב [ראה לעיל הערה 1] ובבוך תרמ\"א 2086 — כת\"י מעתיק.\n\n<b>ב</b> ) <b>בלק\"ת בד\"ה תורה ציוה</b>: ברכה צד, סע\"א ואילך. צה, סע\"א ואילך.\n\n<b>ג</b> ) <b>הנ\"ל</b>: ניתוסף ממעל לשיטה. נזכר לעיל בחלק הנמחק בגוכתי\"ק.\n\n<b>ד</b> ) <b>שרש התורה . . הכתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">תו\"א לך יא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380336\" data-slug=\"likkutei-torah\" data-id=\"4001380336\">לקו\"ת במדבר ז, א</a>. סה\"מ תרל\"ח ע' סח. וש\"נ.\n\n<b>ה</b> ) <b>ונגלה כבוד ה'</b>: ישעי' מ, ה.\n\n<b>ו</b> ) <b>ולא יכנף . . רואות</b>: שם ל, כ.\n\n<b>ז</b> ) <b>ובאו במערות צורים</b>: שם ב, יט.\n\n<b>ח</b> ) <b>ובאו במערות צורים ובנקיקי כו'</b>: כ\"ה בזהר רע\"מ פינחס רמג, א.\n\n<b>ט</b> ) <b>ובנקיקי כו'</b>: ישעי' ז, יט.\n\n<b>י</b> ) <b>מפני פחד ה'</b>: שם ב, יט.\n\n<b>יא</b> ) <b>מזלייהו חזי</b>: מגילה ג, א.\n\n<b>יב</b> ) <b>בביאור בשעה שהקדימו בלק\"ת</b>: ראה שם במדבר טז, א.\n\n<b>יג</b> ) <b>ובד\"ה יונתי בחגוי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>.\n\n<b>יד</b> ) <b>חזי לשון תרגום</b>: ראה תרגום אונקלוס לך יג, טו.\n\n<b>טו</b> ) <b>תרגום בחי' אחוריים</b>: ראה טעהמ\"צ פ' ואתחנן ענין שמו\"ת. שעהמ\"צ שם. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450434\" data-slug=\"or-hatorah-hb\" data-id=\"8316450434\">אוה\"ת</a> צפני' כרך ב ע' תתקד.\n\n<b>טז</b> ) <b>וראית את אחורי . . דאבא</b>: תשא לג, כג. ראה גם לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 226.\n\n<b>יז</b> ) <b>קשר של תפילין</b>: ברכות ז, א. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה על יד הערה 114 ואילך.\n\n<b>יח</b> ) <b>כבודך</b>: תשא שם, יח.\n\n<b>יט</b> ) <b>בד\"ה הנה אנכי שולח מלאך</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו.\n\n<b>כ</b> ) <b>בד\"ה הנה אנכי כורת ברית דר\"י</b>: ראה הערה שלפנ\"ז.\n\n<b>כא</b> ) <b>בלק\"ת בד\"ה האזינו</b>: עג, סע\"ב ואילך.\n\n<b>כב</b> ) <b>ונצבת על הצור</b>: תשא לג, כא.\n\n<b>כג</b> ) <b>בלק\"ת . . בפ' אחרי</b>: כו, ג.\n\n<b>כד</b> ) <b>צור וסלע . . כשהוא קטן</b>: ראה ילקוט שמעוני חוקת כ, ח סוף רמז תשסג. תהלים עח, כ רמז תתיט. אוה\"ת חוקת ע' תתכא ואילך.\n\n<b>כה</b> ) <b>ימים נוראים מקור היראה</b>: ראה גם המשך מים רבים תרל\"ו פ\"נ. סה\"מ תרל\"ו ח\"ב ע' של. ע' שמז. תר\"ם ח\"ב ע' תתקיג.\n\n<b>כו</b> ) <b>ובכן תן פחדך</b>: תפלת העמידה לימים נוראים.\n\n<b>כז</b> ) <b>ובמורא גדול זה גילוי שכינה</b>: תבוא כו, ח. ראה ספרי שם. הגדה של פסח.\n\n<b>כח</b> ) <b>מל' דא\"ס</b>: ראה גם שע\"ת קמה, ד ובהערה 41. תו\"ח בא ח\"א ק, ג. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה שלש רגלים תחוג לי על יד הערה 97.\n\n<b>כט</b> ) <b>שביצ\"מ הי' באתעדל\"ע לבד</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381227\" data-slug=\"likkutei-torah\" data-id=\"4001381227\">שה\"ש כד, ג</a>.\n\n<b>ל</b> ) <b>ישמח הוי' במעשיו</b>: תהלים קד, לא. ראה ויק\"ר פ\"כ, ב. לקו\"ת שהובא בסמוך בפנים. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650264\" data-slug=\"or-hatorah-hb\" data-id=\"8316650264\">אוה\"ת שבועות ע' קלד</a> ואילך — נדפס גם באוה\"ת תהלים כרך ב ע' תתקצג.\n\n<b>לא</b> ) <b>בד\"ה מי יתנך</b>: סה\"מ תרל\"א ח\"א ע' קיח.\n\n<b>לב</b> ) <b>בלק\"ת בד\"ה ה' לי בעוזרי פ\"ד</b>: שמע\"צ פט, א ואילך."]]],[2001910400,"ך הוא סדר מועד, והענין הוא דהנה סדר זרעים שהוא מעשה המצות הוא רק בחי' הזריעה, זורע צדקות, אך מהזריעה נעשה צמיחה, והצמיחה הוא ענין סדר מועד כו', שבמועדים הוא ענין הצמיחה שנעשה מהזריעה, ועיקר הצמיחה יהי' לע\"ל שאז יהי' התגלות אלקות למטה ממש, ישמח ה' במעשיול, ישמח ישראל בעושיו<sup data-n=\"4034\">61</sup>, שענין הצמיחה הוא בחי' שמחה וכמ\"ש ברנה יקצורו<sup data-n=\"4035\">62</sup> שהוא קאי על",[["4034","61","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["4035","62","<b>ברנה יקצורו</b>: שם קכו, ה."]]],[2001910401,"לע\"ל, אך במועדים מאיר ג\"כ התגלות מעט בחי' צמיחה שנעשה ע\"י זריעת מעשה המצות וכמ\"ש מועדים לשמחה<sup data-n=\"4036\">63</sup>, שבכל יו\"ט נמשך התגלות בחי' שמחה עילאה שהוא ענין הצמיחה כנ\"ל. וזהו שמועד הוא כנגד מדת הגבורה<sup data-n=\"4037\">64</sup>, והיינו לפי שמועד הוא מתחיל במס' שבת, והנה ענין השבת הוא בחי' גבורה<sup data-n=\"4038\">65</sup> וכן יש בו ג\"כ דינין<sup data-n=\"4039\">66</sup> כי שבת הוא בחי' העלאת העולמות<sup data-n=\"4040\">67</sup>, והנה כל העלאה א\"א להיות כ\"א ע\"י גבורה, וע\"כ מועד הוא בחי' גבורה, וכן יש בו ג\"כ בחי' המשכה למטה כו' כי מועדים הוא ענין המשכה וכמ\"ש מקדש ישראל והזמנים<sup data-n=\"4041\">68</sup> שהוא בחי' המשכה מבחי' קדש בזמנים, והיינו שמה שמועד הוא בבחי' גבורה אינו בחי' גבורה בעצם רק שהוא בחי' גבורה שבחסד<sup data-n=\"4042\">69</sup>, וכמו מיכאל וגבריאל ששניהם הם מבחי' החסד<sup data-n=\"4043\">70</sup>, רק שמיכאל הוא מחסד שבחסד<sup data-n=\"4044\">71</sup> וגבריאל הוא מבחי' גבורה שבחסד<sup data-n=\"4045\">72</sup>, וכך הוא ענין סדר זרעים וסדר מועד שסדר מועד הוא מבחי' גבורה שבחסד וע\"כ יש בו בחי' העלאה והמשכה ג\"כ שבת הוא העלאה ומועדים הוא בחי' המשכה. ובזה יובן מה שהמועדים נקבעו בזמן הקציר, פסח הוא ע\"ש קצירת שעורים, והענין הוא דהנה שעורים הוא שיעור ה'<sup data-n=\"4046\">73</sup>, ה' הוא בחי' בהבראם בה' בראם<sup data-n=\"4047\">74</sup>, ושיעור ה' הייינו שנמשך בכל חד וחד לפום שיעורא דילי'<sup data-n=\"4048\">75</sup>, דהיינו להתבונן ברוממות אלקות איך ששרש כל העולמות הוא רק מבחי' ה' שהוא בחי' אתא קלילא דלית בי' מששא<sup data-n=\"4049\">76</sup> שהוא רק בחי' זיו והארה בעלמא ועי\"ז נופל עליו יראה ופחד מאלקות, לפי שע\"י התבוננות הרוממות עי\"ז נמשך בחי' יראה, וזהו ענין קבלת עומ\"ש, והנה פסח הוא ענין התגלות היראה וכמ\"ש בפסח ובמורא גדול<sup data-n=\"4050\">77</sup>, שאז ביצ\"מ קבלו עליהם עומ\"ש, וע\"כ נק' הפסח ע\"ש קציר שעורים",[["4036","63","<b>מועדים לשמחה</b>: נוסח תפלת העמידה וקידוש ליו\"ט."],["4037","64","<b>שמועד . . מדת הגבורה</b>: ראה ת\"ז בהקדמה ה, א. פע\"ח שער הנהגת הלימוד שי\"ז (ד\"ה סדר מועד — שנט, ריש ע\"ב). שער המצות ואתחנן (ד\"ה אח\"כ יקרא — פד, א). טעמי המצות שם (ד\"ה סדר קכיעות התורה — רלט, ד). מ\"ח סדר מועד מסכת ת\"ת פ\"א, ה\"י. ביאוה\"ז וישלח כ, א. פיה\"מ לה, סע\"ג ואילך. מאמרי אדה\"א קונטרסים ס\"ע רב. ע' רג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550891\" data-slug=\"torat-chaim\" data-id=\"2300550891\">תו\"ח ויקהל ח\"ב תלט, סע\"ד</a>. אוה\"ת שבועות ס\"ע עא. בהערה הבאה."],["4038","65","<b>השבת הוא בחי' גבורה</b>: ראה גם ביאוה\"ז שם. אוה\"ת תצא ע' תתקצח. הושע כרך א ע' תנז — נדפס גם בביאוה\"ז (להצ\"צ) וישלח ח\"ב ע' תשז."],["4039","66","<b>השבת . . דינין</b>: ראה טור ברקת הל' יו\"ט סתקט\"ו, ס\"ט (נו, ג) כי השבת נמי הוא בחינת דין כנודע מן הזוהר. ביאוה\"ז שם."],["4040","67","<b>שבת . . העלאת העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["4041","68","<b>מקדש ישראל והזמנים</b>: נוסח ברכת היום דיו\"ט."],["4042","69","<b>שמועד . . גבורה שבחסד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550450\" data-slug=\"torat-chaim\" data-id=\"2300550450\">תו\"ח ויקהל ח\"ב שצ, ב</a> ובהערה 190."],["4043","70","<b>מיכאל . . החסד</b>: ראה זהר ויחי רלה, ב. נשא קמה, ב. סה\"מ תרל\"ח ע' קטז. וש\"נ."],["4044","71","<b>שמיכאל הוא מחסד שבחסד</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 86."],["4045","72","<b>וגבריאל . . גבורה שבחסד</b>: ראה ביאורי הזהר פקודי נז, ב. ולהצ\"צ ח\"א שם ע' רצג ואילך. ע' רצה. שער היחוד קכה, ב."],["4046","73","<b>שעורים הוא שיעור ה'</b>: זהר בלק קפח, ב."],["4047","74","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["4048","75","<b>בכל חד וחד לפום שיעורא דילי'</b>: ראה תניא בהקדמה (ד, א) ע\"פ זהר וירא קג, ריש ע\"ב. וראה גם זהר ח\"ש קכט, ב."],["4049","76","<b>ה' . . אתא קלילא דלית בי' מששא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, ד</a>: והה' הוא . . מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48."],["4050","77","<b>ובמורא גדול</b>: תבוא כו, ח."]]],[2001910402,"לפי שאז נמשך בהתגלות בכאו\"א בחי' שעורה שיעור ה'. ושבועות נק' ע\"ש קציר חטים לפי שאז הי' מ\"ת<sup data-n=\"4051\">78</sup> שהוא ענין חטים כי חטה הוא ך\"ב אתוון דאורייתא<sup data-n=\"4052\">79</sup>, וזהו ענין שתי הלחם שהיו מביאין בעצרת<sup data-n=\"4053\">80</sup> שהוא ענין תשב\"כ ותשבע\"פ<sup data-n=\"4054\">81</sup>, והיינו שבשבועות הוא ענין השגת אלקות בבחי' פנימיות רזין דאורייתא, וחג הסוכות הוא בחי' אסיפה מן השדה לבית, כי פסח ושבועות אף שהוא זמן קצירה שהוא בחי' גילוי, אך כ\"ז הוא רק בבחי' שדה, דהיינו שהוא המשכה למעלה, אבל בסוכות הוא זמן אסיפה לבית, דהיינו שיומשך בכאו\"א בפנימיותו כו'.\n<b>חסן</b><sup data-n=\"4055\">82</sup> זה סדר נשים<sup data-n=\"4056\">83</sup>, והענין הוא דהנה ידוע שיש עולם שנה נפש<sup data-n=\"4057\">84</sup>, והנה זרעים מועד הוא המשכה בבחי' עולם ושנה שהוא זרעים המשכה בעולם כי הזריעה היא בארץ דוקא, והזריעה צריכה לגשמים מן השמים וכמ\"ש כאשר ירד הגשם והשלג מן השמים והרוה<sup data-n=\"4059\">86</sup> את הארץ והולידה והצמיחה<sup data-n=\"4058\">85</sup>, נמצא שענין סדר זרעים הוא המשכה בעולם, ומועד הוא המשכה בבחי' שנה כי מועדים הוא בזמן דוקא שיש זמן ועת מיוחד לכל מועד ומועד, ונשים הוא המשכה בבחי' נפש שהוא המשכה בבחי' פנימי' בבחי' נפש שזהו ענין סדר נשים שהוא יחוד וזיווג שהוא המשכה פנימי' כו'. וזהו שסדר נשים הוא כנגד מדת התפארת<sup data-n=\"4060\">87</sup> שהיא בחי' יעקב<sup data-n=\"4061\">88</sup> שהוא בריח התיכון המבריח מן הקצה אל הקצה<sup data-n=\"4062\">89</sup>, שיש קצה וקצה וכמ\"ש ולמקצה השמים דלעילא עד קצה השמים<sup data-n=\"4063\">90</sup> דלתתא, קצה השמים דלעילא",[["4051","78","<b>ושבועות . . שאז הי' מ\"ת</b>: ראה נוסח התפלה וקידוש לשבועות. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש שבועות כרך ח ע' 21</a>."],["4052","79","<b>חטה הוא ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["4053","80","<b>שתי הלחם . . בעצרת</b>: אמור כג, טו ואילך. סהמ\"צ להרמב\"ם מ\"ע מו. רמב\"ם הל' תמידין ומוספין רפ\"ח."],["4054","81","<b>שתי הלחם . . תשב\"כ ותשבע\"פ</b>: ראה זח\"א השמטות רס, א."],["4055","82","<b>חסן</b>: מכאן מתחיל מאמר חדש שנאמר ביום ב' דחג השבועות בפתיחה והי' אמונת עתך. ראה גם לעיל הערה 1. הנחה מדרוש זה נדפסה לקמן בחלק ההנחות בפתיחה והי' אמונת עתך כנ\"ל."],["4056","83","<b>חסן זה סדר נשים</b>: ישעי' לג, ו. שבת לא, א."],["4057","84","<b>עולם שנה נפש</b>: ראה ס\"י פ\"ג, מ\"ג ואילך. מאמרי אדה\"א בראשית ע' נו ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540053\" data-slug=\"torat-chaim\" data-id=\"2300540053\">תו\"ח וארא ח\"א נג, ב</a> ובהערה 13. סה\"מ תרל\"ח ע' מג. וש\"נ."],["4059","86","<b>והרוה</b>: ישעי' שם [ושם: כי אם הרוה — וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן ד\"ה והי' אמונת עתיך ראה שם הערה 7]."],["4058","85","<b>כאשר ירד הגשם . . והצמיחה</b>: ישעי' נה, י [בדילוג]."],["4060","87","<b>שסדר נשים . . התפארת</b>: ראה ת\"ז בהקדמה ה, א. פרדס שכ\"ג, פ\"ח שעה\"כ מערכת חוסן. ספרי הקבלה שבהערה 64. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550891\" data-slug=\"torat-chaim\" data-id=\"2300550891\">תו\"ח ויקהל ח\"ב תלט, סע\"ד</a>. פיה\"מ לה, רע\"ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500457\" data-slug=\"or-hatorah-hb\" data-id=\"8316500457\">אוה\"ת הושע כרך א ע' תנז</a> — נדפס גם בביאוה\"ז (להצ\"צ) וישלח ח\"ב ע' תשח. וראה מאו\"א מערכת חוסן אות סב [וכן צ\"ל באוה\"ת ישעי' כרך א ע' רכה]."],["4061","88","<b>התפארת שהיא בחי' יעקב</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג (תוספות) שב, א. פרדס שער הכנויים שכ\"ב, פ\"ד."],["4062","89","<b>יעקב שהוא בריח . . אל הקצה</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381181\" data-slug=\"likkutei-torah\" data-id=\"4001381181\">לקו\"ת שה\"ש יג, סע\"א</a> ואילך. מאמרי אדה\"א שמות ח\"א ע' יט. וש\"נ. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["4063","90","<b>ולמקצה השמים . . עד קצה השמים</b>: ואתחנן ד, לב [ושם: ועד]. ראה זהר ויקהל ריא, א. אוה\"ת ויחי ע' שצה. ואתחנן ע' קסו."]]],[2001910403,"הוא בחי' סוכ\"ע, וקצה השמים דלתתא הוא בחי' ממכ\"ע<sup data-n=\"4064\">91</sup>, ויעקב הוא המבריח וממשיך מבחי' סוכ\"ע בממכ\"ע. והנה כתי' אלה תולדות יעקב יוסף<sup data-n=\"4065\">92</sup>, ולכאו' אינו מובן שהרי ליעקב היו י\"ב שבטים ולמה א' רק תולדות יעקב יוסף לבד, אך הענין הוא דהנה יוסף הוא ע\"ש תוס' אורות וכמ\"ש יוסיף ה' שנית ידו<sup data-n=\"4066\">93</sup>, וזהו בן פורת יוסף, פורת הוא מל' פרי' ורבי'<sup data-n=\"4067\">94</sup>, שיוסף שהוא בחי' תוס' אורות וע\"י בחי' תוס' אורות עי\"ז הוא נמשך למטה ג\"כ, וזהו ענין נשים שהוא בחי' הולדה שנמשך בבחי' תוס' וריבוי כו'. וזהו פי' חסן שהוא לשון חיזוק<sup data-n=\"4068\">95</sup>, כי נשים הוא המשכה מבחי' בריח התיכון המבריח מן הקצה אל הקצה שהוא ענין חוזק, וכמו בגשמיות שהבריח התיכון הי' מחזק את הכתלים, וכך למעלה המשכת בחי' בריח התיכון הוא המשכה חזקה דהיינו המשכה מעצמות אוא\"ס ב\"ה. ועוי\"ל חסן הוא בחי' ירושה<sup data-n=\"4069\">96</sup> וכמ\"ש בזהר בן מסטרא דדעת<sup data-n=\"4070\">97</sup> דירית אחסנתי' מאבא ואמא, וזהו מ\"ש מי כמוכה חסין י\"ה<sup data-n=\"4071\">98</sup>, והענין הוא דהנה לפעמים כתי' אין השם שלם<sup data-n=\"4072\">99</sup> דהיינו שאינו מאיר בחי' י\"ה בו\"ה<sup data-n=\"4073\">100</sup>, ולמטה בנפש האדם היינו שאינו מאיר בחי' מוחין במדות אף שהוא משיג אלקות בהשגה ושכל מ\"מ אינו נוגע כלל לפנימיותו, והיינו לפי שאינו מאיר ההשגה שמשיג במוחו ללב, וזהו אין השם שלם, אך חסין י\"ה היינו שיהי' הבן שהוא בחי' מדות שהוא בחי' ו\"ה יהי' ירית בחי' י\"ה שיהי' מאיר גילוי עצם בחי' י\"ה בו\"ה, וע\"ז נא' חסין י\"ה דירית מאבא ואמא שהוא בחי' ירושה שמקבל מפנימי' י\"ה, וזהו חסן זה סדר נשים כי סדר נשים הוא המשכה פנימי' בבחי' תוס' וריבוי מבחי' בריח התיכון כו' שהוא המשכה מפנימי' או\"א וע\"כ נקרא חסן שהוא בחי' ירושה דירית מאבא ואמא.\n<b>ישועות</b> זה סדר נזיקין<sup data-n=\"4074\">101</sup>, והענין הוא דהנה יש ארבע אבות נזיקין<sup data-n=\"4075\">102</sup>, זהו ענין עון ומשחית אף וחימה<sup data-n=\"4076\">103</sup>, וע\"ז נא' והוא רחום יכפר",[["4064","91","<b>סוכ\"ע . . ממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["4065","92","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה ב\"ר פפ\"ד, ו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480137\" data-slug=\"or-hatorah-hb\" data-id=\"8316480137\">אוה\"ת וישב כרך ה ע' תתק</a> ואילך. סה\"מ תרכ\"ט ע' שפו. תרכ\"ז ע' ריט. וש\"נ. לעיל מאמר ד\"ה קדש ישראל לה' ספ\"א."],["4066","93","<b>יוסיף ה' שנית ידו</b>: ישעי' יא, יא."],["4067","94","<b>בן פורת יוסף . . פרי' ורבי'</b>: ויחי מט, כב וברש\"י שם."],["4068","95","<b>חסן שהוא לשון חיזוק</b>: ראה רד\"ק ומצודת ציון לישעי' לג, ו. פרדס שבהערה 87. אוה\"ת שבועות ע' פ. סה\"מ תרל\"ב ח\"ב ע' תמג."],["4069","96","<b>חסן הוא בחי' ירושה</b>: רש\"י שבת לא, א ד\"ה חוסן. ראה אוה\"ת שבועות ע' עא. ע' עב. ישעי' כרך א ע' רכד."],["4070","97","<b>בן מסטרא דדעת</b>: ראה זהר אד\"ז האזינו רצא, א."],["4071","98","<b>מי כמוכה חסין י\"ה</b>: תהלים פט, ט [ושם: כמוך]."],["4072","99","<b>אין השם שלם</b>: ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231268\" data-slug=\"likkutei-sichot\" data-id=\"1300231268\">לקו\"ש</a> י\"ג סיון כרך כג ע' 268 הערה 33."],["4073","100","<b>שאינו מאיר בחי' י\"ה בו\"ה</b>: ראה גם אוה\"ת שבועות ע' עב. (יהל אור) תהלים ע' שכ. לעיל מאמר ד\"ה מגילה נקראת הערה 186."],["4074","101","<b>ישועות זה סדר נזיקין</b>: ישעי' לג, ו. שבת לא, א."],["4075","102","<b>ארבע אבות נזיקין</b>: ראה ב\"ק ב, א (במשנה)."],["4076","103","<b>עון ומשחית אף וחימה</b>: ראה מאו\"א אות ד סל\"ב. זהר רע\"מ משפטים קיח, סע\"א. של\"ה תושב\"כ שובבים ת\"ת פ' משפטים שכ, סע\"א. מעשה רוקח לר' אלעזר בר' שמואל לב\"ק שם (עו, ב בדפי הספר).\nולהעיר מסה\"מ תרל\"ב ח\"ב ע' תמג: ארבעה אבות נזיקין הם ד' קליפות אף וחימה קצף ומשחית.\nוראה גם זהר רע\"מ בא מא, ב. מב, א. קרח קעט, ב. פינחס רכז, ב. תצא רעט, ב. תוספת שז, ב. לקו\"ת מלכים י, כט. חסד לאברהם מעין שני עין הקורא נהר יב. פע\"ח שער מנחה ומעריב שט\"ו, רפ\"ג. מ\"ח סדר מועד מסכת הבריאה דערבית פ\"ו, מ\"ב. סידור האריז\"ל — הרש\"ר וקול יעקב — תפלת ערבית. וראה פרדס שכ\"ג, פי\"ג שעה\"כ מערכת משחית."]]],[2001910404,"עון<sup data-n=\"4077\">104</sup> כנגד קליפת עון ולא ישחית כנגד משחית והרבה להשיב אפו כנגד אף, ולא יעיר כל חמתו כנגד חימה, והיינו שבפסוק והוא רחום יכפר עון יש י\"ג תיבות<sup data-n=\"4078\">105</sup> כנגד י\"ג מדה\"ר<sup data-n=\"4079\">106</sup> שממשיכים יגמה\"ר כדי להציל מד' קליפות אלו, וזהו ענין ישועות הוא סדר נזיקין, דהנה ענין סדר נזיקין הוא ענין דין ומשפט שיש בין אדם לחבירו, והנה בדין ומשפט שבין אדם לחבירו צריך שלשה דיינים וכמ\"ש במשנה סנהדרין פ\"א דיני ממונות בג', ויש ג\"כ איזה דינים שצריכים ך\"ג וע\"א<sup data-n=\"4080\">107</sup>, אך שלשה הוא אפי' בדיני ממונות לבד. והנה לכאו' אינו מובן שהרי באיסור והיתר יחיד יכול להורות ובדיני ממונות צריך דוקא שלשה, והנה שלשה יש להם כח הרבה יותר מאחד וכמ\"ש בברכת הזימון בשלשה אומר נברך<sup data-n=\"4081\">108</sup>, שאחד מי שיהי' אפי' משה רבינו אינו יכול לברך, שענין נברך היינו להמשיך בחי' בריכה עליונה מקור כל הברכות כידוע שיש ג' בחי' מעיין בריכה ומקור<sup data-n=\"4082\">109</sup>, וכדי להמשיך בחי' בריכה עליונה ממקור זהו דוקא בשלשה שלשלשה דוקא יש להם כח להמשיך את הבריכה, משא\"כ א' אינו יכול לומר נברך רק ברוך שהוא המשכה מצומצמת, אבל בחי' בריכה אינו יכול להמשיך, וא\"כ כיון שיש לשלשה זה הכח למה צריך לדיני ממונות שלשה דוקא. אך הענין הוא, דהנה דיני ממונות היינו מה שיש בין אדם לחבירו שהוא ענין עת אשר ישלוט האדם באדם<sup data-n=\"4083\">110</sup> לרע לו, דהיינו שמקבל אדם בליעל<sup data-n=\"4084\">111</sup> מאדם דקדושה, ולזה צריך שלשה דוקא כי לא' ולשנים אין להם זה הכח להציל את העשוק מיד עושקו דהיינו להציל אדם דקדושה מאדם בליעל, כי את זה לעו\"ז עשה האלקים<sup data-n=\"4085\">112</sup> כי לעומת ימין יש שמאל ע\"כ כדי שיכול לעשות דין ומשפט זהו ע\"י שלשה דוקא כי שלשה ממשיכים מבחי' כי לא אדם הוא<sup data-n=\"4086\">113</sup> שלמעלה מבחי' אדם",[["4077","104","<b>והוא רחום יכפר עון</b>: תהלים עח, לח. ראה זהר בראשית כג, ב. ת\"ז תל\"ז. תקוני ז\"ח קח סע\"ג ואילך. עמה\"מ שער עולם התהו ש\"ו, פמ\"ט הובא ב (יהל אור) אוה\"ת תהלים ע' תרכו [וכן צ\"ל שם ע' עדר]. חסד לאברהם ושל\"ה שם. מ\"ח שם מ\"ג. סידור האריז\"ל שם."],["4078","105","<b>והוא רחום . . י\"ג תיבות</b>: ראה פע\"ח־ מ\"ח וסידור האריז\"ל שם."],["4079","106","<b>י\"ג תיבות כנגד י\"ג מדה\"ר</b>: ראה עמה\"מ־ פע\"ח־ מ\"ח וסידור האריז\"ל שם."],["4080","107","<b>במשנה סנהדרין . . בג' . . ך\"ג וע\"א</b>: ב, א."],["4081","108","<b>בשלשה אומר נברך</b>: ברכות פ\"ז, מ\"ג (מט, ב). ראה סידור שער בהמ\"ז קב, א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450538\" data-slug=\"or-hatorah-hb\" data-id=\"8316450538\">אוה\"ת עקב ע' תקלח</a> ואילך. סה\"מ תרכ\"ו ריש ע' ריט."],["4082","109","<b>ג' בחי' מעיין בריכה ומקור</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 39."],["4083","110","<b>עת אשר ישלוט האדם באדם</b>: קהלת ח, ט [ושם: שלט]. ראה זהר סבא משפטים צה, ב. מאמרי אדה\"ז תקס\"ד ע' קסו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' עתר. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540449\" data-slug=\"torat-chaim\" data-id=\"2300540449\">תו\"ח שמות ח\"א ל, ד</a>."],["4084","111","<b>אדם בליעל</b>: משלי ו, יב."],["4085","112","<b>את זה לעו\"ז עשה האלקים</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["4086","113","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."]]],[2001910405,"שאין שם לעו\"ז כלל וכמ\"ש בזהר לית שמאלא בהאי עתיקא<sup data-n=\"4087\">114</sup> וע\"כ עי\"ז יכולים להציל את העשוק מיד עושקו מאדם בליעל. וזהו מ\"ש הושיעה ימינך וענני<sup data-n=\"4088\">115</sup>, שכשצריך להתגבר על השמאל צריך להמשיך בחי' ישועה בימין, כי לעומת ימין יש שמאל ע\"כ צריך להמשיך ישועה בימין מבחי' שלמעלה מב' הבחי' כדי לאכללא שמאלא בימינא<sup data-n=\"4089\">116</sup>, שענין זה אין בכח הימין עצמו להתגבר על השמאל רק שנמשך ישועה מלמעלה בימין כדי להתגבר על בחי' שמאל, ובנפש האדם הוא ענין מ\"ש כי יעמוד לימין אביון להושיע<sup data-n=\"4090\">117</sup> כו'. וזהו ענין ישועות הוא סדר נזיקין, שכדי להציל את העשוק מיד עושקו ולעשות דין בין אדם לחבירו זהו ע\"י הישועות שנמשך מלמעלה שהוא ע\"י שלשה שיש להם כח זה להמשיך את בחי' הישועות הנ\"ל. ובזה יובן משארז\"ל בשני דרב יהודא כולי תנויי בנזיקין הוה<sup data-n=\"4091\">118</sup>, דלכאו' אינו מובן שהרי רב יהודא הי' גדול מאד שהרי הוה מצלי מתלתין יומין לתלתין יומין<sup data-n=\"4092\">119</sup>, מפני שתורתו אומנתו<sup data-n=\"4093\">120</sup> פטור מהתפילה<sup data-n=\"4094\">121</sup>, וכל תנויי לא הוה רק בנזיקין. אך לפי הנ\"ל מובן זה לפי שעיקר לימודם הי' כדי להציל מיד ארבעה אבות נזיקין, וזהו ישועות הוא סדר נזיקין כי כדי להציל מיד ארבעה אבות נזיקין צריך להמשיך מבחי' ישועות הושיעה ימינך וענני, וזהו חסין י\"ה בחי' חוסן ישועות וכמו אמונת עתך שאמונת שייך לעתיך כך חוסן ישועות, וע\"י חוסן שהוא סדר נשים שהוא המשכה פנימי' עי\"ז נמשך ישועות דהיינו שיהי' הושיעה בבחי' חוסן בבחי' חיזוק שיהי' ישועה באמת. וזהו שמרו משפט ועשו צדקה כי קרובה ישועתי לבוא<sup data-n=\"4095\">122</sup>, שע\"י משפט וצדקה נמשך בחי' ישועה. וע\"כ ישועות הוא סדר נזיקין כו'.\n<b>חכ'</b> הוא בחי' סדר קדשים ודעת הוא סדר טהרות<sup data-n=\"4096\">123</sup>, והנה לכאו' אינו מובן שהרי דעת הוא למעלה מחכ', וכמו שפרש\"י דעת עדיף מחכ'<sup data-n=\"4097\">124</sup>, וקדשים הוא למעלה מסדר טהרות, שהרי טהרה מביאה לידי קדושה<sup data-n=\"4098\">125</sup> וא\"כ למה חכ' הוא קדשים ודעת",[["4087","114","<b>לית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["4088","115","<b>הושיעה ימינך וענני</b>: תהלים קח, ז. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381041\" data-slug=\"likkutei-torah\" data-id=\"4001381041\">לקו\"ת סוכות עט, ב</a>."],["4089","116","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["4090","117","<b>כי יעמוד לימין אביון להושיע</b>: תהלים קט, לא."],["4091","118","<b>בשני דרב יהודא כולי תנויי בנזיקין הוה</b>: ברכות כ, א. ראה גם מאמרי אדה\"א דברים ח\"ב ע' שעד. וש\"נ. סה\"מ תרל\"ח ע' קנג. וש\"נ."],["4092","119","<b>רב יהודא . . מצלי . . לתלתין יומין</b>: ר\"ה לה, א. ראה גם שע\"ת קג, ב ובהערה 15."],["4093","120","<b>רב יהודא . . שתורתו אומנתו</b>: ראה גם שע\"ת שם ובהערה 9."],["4094","121","<b>שתורתו אומנתו פטור מהתפילה</b>: שבת יא, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550526\" data-slug=\"torat-chaim\" data-id=\"2300550526\">תו\"ח יתרו ח\"ב רנו, ב</a> ובהערה 331."],["4095","122","<b>שמרו משפט . . ישועתי לבוא</b>: ישעי' נו, א."],["4096","123","<b>חכ' . . קדשים ודעת . . טהרות</b>: ישעי' לג, ו. שבת לא, א."],["4097","124","<b>שפרש\"י דעת עדיף מחכ'</b>: שבת שם ד\"ה דעת."],["4098","125","<b>טהרה מביאה לידי קדושה</b>: ראה ירושלמי שבת פ\"א, ה\"ג. שקלים ספ\"ג. שהש\"ר א, א, (ט). רי\"ף לע\"ז כ, ב. הקדמת הרמב\"ם לסדר טהרות קרוב לסופה. רמב\"ם הל' טומאת אוכלין ספט\"ז ובכ\"מ שם. בעלי הנפש להראב\"ד ריש שער הקדושה. ארחות צדיקים שער הזריזות. מנורת המאור הנר הראשון אות כ. הנר השלישי אות קפ. הנר השביעי אות של. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ק.\nראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380389\" data-slug=\"likkutei-torah\" data-id=\"4001380389\">לקו\"ת נשא כ, ב</a> ושם: ”ע' בר\"ח\" — ראה שם שער האהבה פי\"א. ובהגהות כ\"ק אדמו\"ר מהורש\"ב ללקו\"ת שם (בהוספות יח, ג): ”ובמס\"י (כי\"ק)\" — ובמסילת ישרים [מבנה הספר הוא לפי סדר הברייתא דרפב\"י כפי הגירסא שבגמ' שלפנינו]."]]],[2001910406,"הוא טהרות. אך הענין הוא דהנה במשנה מתחיל קודם מאימתי קורין את שמע בערבית<sup data-n=\"4099\">126</sup> ופריך בגמ' למה אינו מתחיל מאימתי קורין את שמע בשחרית, ומשני<sup data-n=\"4100\">127</sup> כברייתו של עולם ברישא חשוכא<sup data-n=\"4101\">128</sup> והדר נהורא, והנה אנו רואים שענין קדשים הוא חלוק מברייתו ש\"ע, שברייתו ש\"ע היום הולך אחר הלילה<sup data-n=\"4102\">129</sup> וכן שבת ומועדים מתחיל מהלילה, ובקדשים הוא להיפוך שהלילה הולך אחר היום<sup data-n=\"4103\">130</sup>, שהרי קדשים שנאכלין ליום ולילה א' היינו הלילה שאחר היום<sup data-n=\"4104\">131</sup>, וכן הקטר חלבים ואברים<sup data-n=\"4105\">132</sup> מצותן עד שיעלה עמוד השחר שהלילה הולך אחר היום, והענין הוא דהנה ארז\"ל מ\"ט עיזי מסגי ברישא והדר אימרי<sup data-n=\"4106\">133</sup> ומשני כברייתו ש\"ע ברישא חשוכא והדר נהורא, והיינו כי עזי הוא בחי' הרשעים<sup data-n=\"4107\">134</sup>, ואימרי הוא בחי' צדיקים<sup data-n=\"4108\">135</sup> ע\"ש את ה' האמרת היום<sup data-n=\"4109\">136</sup>, ומ\"ט מסגי ברישא ומשני כברייתו ש\"ע, והיינו לפי שטבע הבריאה הוא שמתחלה הוא החשך ואח\"כ התגלות האור כי קליפה קדמה לפרי<sup data-n=\"4110\">137</sup> וכן קש ותבן נגדלים מקודם ואח\"כ התבואה<sup data-n=\"4111\">138</sup>, אך אח\"כ כשנגמר התבואה זורקין את הקש והתבן לחוץ ונוטלין את התבואה כי העיקר הוא התבואה רק שא\"א ליצמח כ\"א שמתחלה יהי' נגדל הקש כו', וכן ביחזקאל נא' והנה רוח סערה וענן גדול ואש מתלקחת ונוגה לו סביב<sup data-n=\"4112\">139</sup>, שמתחלה ראה את הקליפות הסובבים את המרכבה ואח\"כ ונוגה לו שאז נגה מעט אור, ואח\"כ ראה את המרכבה בשלימות כו', והיינו כי טבע הבריאה שהקליפה היא קדמה לפרי כו', וע\"כ נא' ויהי ערב ויהי בקר<sup data-n=\"4113\">140</sup>",[["4099","126","<b>מאימתי קורין את שמע בערבית</b>: כ\"ה הגי' במשניות ריש ברכות, ובמשנה שבגמרא ברכות ב, א: בערבין. וכ\"ה גם בהמשך תער\"ב ח\"ג ע' א'שעט."],["4100","127","<b>ומשני</b>: התוכן."],["4101","128","<b>כברייתו . . ברישא חשוכא</b>: שבת עז, ב (כגי') רש\"י. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380055\" data-slug=\"likkutei-torah\" data-id=\"4001380055\">לקו\"ת פקודי ג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540050\" data-slug=\"torat-chaim\" data-id=\"2300540050\">תו\"ח וארא ח\"א מט, ג</a> ואילך. הנסמן בסה\"מ תרכ\"ז ע' תנד."],["4102","129","<b>היום הולך אחר הלילה</b>: חולין פג, סע\"א במשנה."],["4103","130","<b>ובקדשים . . שהלילה הולך אחר היום</b>: חולין שם."],["4104","131","<b>קדשים . . הלילה שאחר היום</b>: ראה רמב\"ם הל' מעשה הקרבנות פ\"י, ה\"ז."],["4105","132","<b>הקטר חלבים ואברים</b>: משנה ברכות שם."],["4106","133","<b>מ\"ט עיזי . . והדר אימרי</b>: שבת שם."],["4107","134","<b>עזי הוא בחי' הרשעים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680454\" data-slug=\"torat-chaim\" data-id=\"2300680454\">תו\"ח תולדות קסא, ב</a>. סה\"מ ה'ש\"ת ע' 56."],["4108","135","<b>ואימרי הוא בחי' צדיקים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו\"ת פינחס עח, ד</a>. סה\"מ תרכ\"ט ע' קיט. תר\"ל ע' ש."],["4109","136","<b>ואימרי . . את ה' האמרת היום</b>: תבוא כו, יז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380636\" data-slug=\"likkutei-torah\" data-id=\"4001380636\">לקו\"ת שם עט, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560053\" data-slug=\"or-hatorah-hb\" data-id=\"8316560053\">אוה\"ת תולדות כרך ג ס\"ע תצג</a>. סה\"מ תרכ\"ט שם."],["4110","137","<b>קליפה קדמה לפרי</b>: ראה זהר סבא משפטים קח, ריש ע\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381168\" data-slug=\"likkutei-torah\" data-id=\"4001381168\">לקו\"ת שה\"ש ט, ד</a>. מאמרי אדה\"א ויקרא ח\"א ע' רט. וש\"נ."],["4111","138","<b>קש ותבן . . התבואה</b>: ראה יל\"ש ס\"פ וישלח. וש\"נ [במהדורת ירושלים תשל\"ג ע' 714]. אוה\"ת תבוא ע' תתרפה. סה\"מ תרכ\"ט ע' קיח. תרל\"ח ע' קלט."],["4112","139","<b>והנה רוח סערה . . סביב</b>: יחזקאל א, ד [בדילוג. שם: ענן — אבל כ\"ה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 68. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380692\" data-slug=\"likkutei-torah\" data-id=\"4001380692\">לקו\"ת מסעי צב, א</a>. מאמרי אדה\"א נ\"ך ע' כא. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ס\"ע קכג. סה\"מ תרל\"ח ע' קלז. וש\"נ]."],["4113","140","<b>ויהי ערב ויהי בקר</b>: בראשית א, ה."]]],[2001910407,"שמתחלה הוא הערב ואח\"כ נעשה בוקר שהוא האור, אך כ\"ז הוא בבחי' בריאת העולם הוא ברישא חשוכא לפי שבעולם הוא בחי' הסתר, אבל בקדשים הוא להיפוך שהלילה הי' הולך אחר היום, והיינו לפי שארז\"ל שההוד זו בהמ\"ק<sup data-n=\"4114\">141</sup>, והנה בהוד יש שני פירושים<sup data-n=\"4115\">142</sup> הא' ל' הודאה, והב' הוא מל' הודו על ארץ ושמים<sup data-n=\"4116\">143</sup> שהוא בחי' הוד וזיו וכן כתי' כסה שמים הודו<sup data-n=\"4117\">144</sup>, ובאמת שני הפירושים הם א', דהיינו שע\"י הודאה וביטול עי\"ז נמשך בחי' הוד וזיו שהוא בחי' התגלות האור, והיינו שבבהמ\"ק הי' מאיר גילוי אלקות בחי' הוד וזיו כו' וע\"כ שם הי' הלילה הולך אחר היום, לפי שהי' הלילה בטל ליום לפי שהי' מאיר גילוי בחי' אלקות שהוא בחי' יום, וזהו חכ' זה סדר קדשים, כי חכ' הוא בחי' התגלות וכמ\"ש חכמת אדם תאיר פניו<sup data-n=\"4118\">145</sup>, יאר הוי' פניו אליך<sup data-n=\"4119\">146</sup> שהוא בחי' הארת פנים שמאיר בבחי' גילוי כו' וזה הי' בבהמ\"ק ע\"כ חכ' הוא בחי' סדר קדשים. (ועוי\"ל שענין ברישא חשוכא, זהו בשביל בירור התהו, שקליפה קדמה במעלה לפרי רק שנפלה בשבה\"כ, וקודם חטא עה\"ד שהיתה שומר לפרי<sup data-n=\"4120\">147</sup> י\"ל בחי' או\"מ לפי שא\"א לבא בבחי' הפנימי', רק שע\"י חטא עה\"ד נעשה מנגד, וע\"י הבירור נמשך יתרון האור מתוך החשך<sup data-n=\"4121\">148</sup>, וזהו דכתיב וראיתי שיש יתרון לחכ' מן הסכלות<sup data-n=\"4122\">149</sup> דוקא, שע\"י בירור הסכלות נמשך יתרון בבחי' החכ', ולכן ד' סדרים הראשונים שהם בחי' הבירורים בעולם שנה נפש כמשנ\"ת לעיל היום הולך אחר הלילה פי' יום הוא גילוי האור והוא הולך אחר הלילה פי' לפי ערך בירור הלילה הוא בחי' חשך דתהו כמ\"ש והארץ כו' וחושך ע\"פ תהום<sup data-n=\"4123\">150</sup>, ולפי ערך בירור החשך שהוא ברישא חשוכא הוא ענין כמו הראש שקדם במעלה על הגוף, כן התהו קדם במעלה לגבי התקון<sup data-n=\"4124\">151</sup>, רק שנפל, ולפי ערך הבירור נמשך הגילוי, ולכן היום שהוא גילוי נמשך אחר הלילה פי' לפ\"ע בירור שמבררים מבחי' החשך דלילה כו', משא\"כ בקדשים ובהמק\"ד שענין הקרבן שהוא המשכת אורות עליונים בזה אינו שייך שהיום ילך אחר הלילה, והלילה בטל כנ\"ל).\n\nלענין חכמת זה סדר קדשים, בענין ההפרש בין ד' סדרי' הראשונים שזהו הנמשך ע\"פ סדר השתלשלות, ולכן זהו כמו בברה\"ע ברישא חשוכא כו' משא\"כ בהמק\"ד הקרבנות ז\"ע יחודים להמשיך אורות עליונים כו'.",[["4114","141","<b>שההוד זו בהמ\"ק</b>: ברכות נח, סע\"א."],["4115","142","<b>בהוד יש שני פירושים</b>: ראה מאמרי אדה\"ז אתהלך ליאזניא ע' קמג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600712\" data-slug=\"or-hatorah-hb\" data-id=\"8316600712\">אוה\"ת</a> דברי הימים כרך א ע' תשיב. סה\"מ תרכ\"ז ע' מג."],["4116","143","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."],["4117","144","<b>כסה שמים הודו</b>: חבקוק ג, ג."],["4118","145","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["4119","146","<b>יאר הוי' פניו אליך</b>: נשא ו, כה."],["4120","147","<b>שקליפה . . שהיתה שומר לפרי</b>: ראה גם סה\"מ תרל\"ח ע' קלה. וש\"נ."],["4121","148","<b>יתרון האור מתוך החשך</b>: ראה הערה הבאה."],["4122","149","<b>וראיתי שיש יתרון לחכ' מן הסכלות</b>: קהלת ב, יג [בדילוג]."],["4123","150","<b>והארץ . . ע\"פ תהום</b>: בראשית א, ב."],["4124","151","<b>התהו קדם במעלה לגבי התקון</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תקצז. וש\"נ."]]],[2001910408,"ודעת הוא סדר טהרות, והענין הוא דהנה בבהמ\"ק אף שהי' מאיר שם גילוי אלקות בבחי' גילוי ממש, מ\"מ זה הי' רק בבהמ\"ק לבד, אבל העולם לא נזדכך עדיין והי' בעולם רע ג\"כ, ולא הי' נוגע זה כלל מה שבבהמ\"ק הי' גילוי אוא\"ס, אך לע\"ל כתי' ואת רוה\"ט אעביר מן הארץ<sup data-n=\"4125\">152</sup> שלא יהי' בחי' רע כלל לפי שהעולם יזדכך וכמ\"ש ושמחת עולם על ראשם<sup data-n=\"4126\">153</sup>, וזהו ענין טהרות שיטהר העולם לגמרי ולא יהי' בחי' רע כלל, וזהו שטהרות הוא למעלה מקדשים, כי קדשים הוא רק בחי' חכ' והנה חכ' הוא מברר בין טוב לרע וכמ\"ש בחכ' אתברירו, אך החכ' הוא רק מברר דהיינו שהוא מפריד בין טוב לרע, אבל הרע נשאר בתוקפו, וזהו כמו שהי' בבהמ\"ק שבבהמ\"ק הי' מאיר בחי' גילוי ובעולם הי' בחי' רע ג\"כ, משא\"כ טהרות הוא ענין טהרה לגמרי, שלא יהי' בחי' רע כלל. ודרך כלל בעבודה חכ' הוא בחי' אתכפי' שמפריד הטוב מן הרע, אבל הרע נשאר עדיין בתקפו, אך טהרות הוא בחי' אתהפכא שנתהפך מחשוכא לנהורא. ועוי\"ל שענין טהרות הוא כמ\"ש ביוהכ\"פ לפני הוי' תטהרו<sup data-n=\"4127\">154</sup>. דהנה יוכ\"פ נק' שבת שבתון<sup data-n=\"4128\">155</sup>, והיינו כמו שיומין דחול לגבי שבת אינו בערך שזה נק' חול וזה נק' קדש, כך אין ערך שבת לגבי יוכ\"פ שיוכ\"פ הוא בחי' קדש הקדשים, וע\"כ ביוכ\"פ הי' כה\"ג נכנס לפני ולפנים שהוא קדה\"ק, וע\"כ כתיב ביוכ\"פ לפני הוי' תטהרו שהוא מטהר לגמרי כמו למשל מי שטובל במקוה שהוא נעשה טהור, כך יוכ\"פ ע\"י תשובה שהוא מטהר לגמרי שזדונות נעשו כזכיות<sup data-n=\"4129\">156</sup>, ובזה הוא למעלה מבהמ\"ק שבבהמ\"ק שהיו מקריבין לא הי' מכפר כ\"א על שוגג<sup data-n=\"4130\">157</sup>, אבל על המזיד לא הי' מכפר<sup data-n=\"4131\">158</sup>, אך יוכ\"פ הוא מכפר גם על המזיד, וזהו ג\"כ ענין טהרות שהוא כמ\"ש מי יתן טהור מטמא<sup data-n=\"4132\">159</sup>, שהטמא נעשה טהור ולא יהי' בחי' רע כלל, וזהו שטהרות הוא בחי' דעת, כי דעת הוא בחי' ומדרגה דלע\"ל וכמ\"ש\n\nלענין<sup data-n=\"8693\">לג</sup> טהרות, מה שמביא ראי' שמקדש קדשים הי' אומר הכה\"ג תטהרו שטהרה גבוה מקדושה, צ\"ע שפי' תטהרו הוא שפועל הטהרה בזולתו וזהו גבוה מקדושה, אבל עצם מדריגת הטהרה אינו ראי' שגבוה יותר, והרי אמרו טהרה מביא לידי קדושה כנ\"ל בשם המהרש\"א<sup data-n=\"8694\">לד</sup>.",[["4125","152","<b>ואת רוה\"ט אעביר מן הארץ</b>: זכרי' יג, ב."],["4126","153","<b>ושמחת עולם על ראשם</b>: ישעי' לה, י. נא, יא."],["4127","154","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["4128","155","<b>יוכ\"פ נק' שבת שבתון</b>: אחרי טז, לא. אמור כג, לב."],["4129","156","<b>שזדונות נעשו כזכיות</b>: ראה יומא פו, ב."],["4130","157","<b>מקריבין </b> [אוצ\"ל: מקריבין קרבן]<b> . . מכפר כ\"א על שוגג</b>: ראה רמב\"ם הל' שגגות רפ\"א ואילך. אגה\"ק סוסכ\"ח."],["4131","158","<b>על המזיד לא הי' מכפר</b>: ראה סה\"מ תרל\"ג ח\"א ע' קמט בשולי היריעה. תר\"ם ח\"ב ע' תר. וש\"נ."],["4132","159","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה לקו\"ת חוקת ס, א.\n\n<b>לג</b> ) <b>לענין</b>: נכתב בסוף ההגהות. וכנראה ששייך כאן.\n\n<b>לד</b> ) <b>כנ\"ל בשם המהרש\"א</b>: הכוונה לכאורה להקושי' שבריש פיסקא ”חכ' הוא בחי' סדר קדשים\", שהובא במהרש\"א שבת שם ד\"ה וחכמה."]]],[2001910409,"ומלאה הארץ דעה<sup data-n=\"4133\">160</sup> את הוי' כו' וכתי' ולא ילמדו עוד איש את רעהו כי כולם ידעו אותי<sup data-n=\"4134\">161</sup> כו', וטהרות קאי ג\"כ על בחי' דלע\"ל וע\"כ דעת מוקי הגמרא שהוא טהרות שלמעלה מקדשים כו', ואעפ\"כ יראת ה' היא אוצרו<sup data-n=\"4135\">162</sup> אי אית בי' יראה אין<sup data-n=\"4136\">163</sup> אי לא לא.\n<b>והענין</b> הוא, דהנה אהבה נק' דכר<sup data-n=\"4137\">164</sup> וכמ\"ש כי זכר חסדו<sup data-n=\"4138\">165</sup>, משא\"כ יראה היא בחי' נוק'<sup data-n=\"4139\">166</sup> וכמ\"ש אשה יראת ה' היא תתהלל<sup data-n=\"4140\">167</sup>, שהיא בחי' כלי, והיינו שיראה היא בחי' כלי שמחזיק, והנה אנו רואים שהעיקר הוא הכלי, שאם אין כלי אינו כלום*, וכמו למשל שאנו רואים שכח הצומח מלובש בארץ דוקא, וכשזורעין בארץ אז מצמיח לפי שהארץ היא כלי להצמיח כו', וכן בנמשל שהמצות נק' בשם זריעה צריך שיהי' ג\"כ בחי' כלי לזה שעי\"ז יצמח, דהיינו שישראל דוקא יקיים את המצות לפי שישראל הם כלי לזה משא\"כ עובדי כוכבים אף שיקיים מצות ויניח תפילין לא יצמיח כלל ולא ימשיך עי\"ז כלום לפי שאינו כלי לזה כלל, וכך יראה דוקא היא בחי' כלי, ע\"כ העיקר הוא היראה ואם אין לו יראה אינו כלום לפי שאין לו כלי כו'. וזהו ענין המשל של המדרש לא' שהיו לו אלף מדות שמן ואלף מדות יין ואלף מדות סולת, דהיינו שהוא ענין חב\"ד כי שמן הוא חכ'<sup data-n=\"4141\">168</sup> ויין הוא בחי' בינה<sup data-n=\"4142\">169</sup> ודעת הוא בחי' סלת<sup data-n=\"4143\">170</sup> וכמשארז\"ל אין התינוק יודע לקרות או\"א<sup data-n=\"4144\">171</sup> עד\n\n*)להעיר<sup data-n=\"8695\">לה</sup> מענין אין עוד כלי<sup data-n=\"8696\">לו</sup> ויעמוד השמן.",[["4133","160","<b>ומלאה הארץ דעה</b>: ישעי' יא, ט [ושם כי מלאה — אבל כ\"ה גם בב\"מ ומהם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 85. מאמרי אדה\"א ויקרא ח\"א ע' רסט־ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540850\" data-slug=\"torat-chaim\" data-id=\"2300540850\">תו\"ח בשלח ח\"א קס, ד</a>־ סה\"מ תרל\"ח ע' קמט ובהנסמן בהנ\"ל]."],["4134","161","<b>ולא ילמדו. . ידעו אותי</b>: ירמי' לא, לג [בדילוג]."],["4135","162","<b>יראת ה' היא אוצרו</b>: המשך הכתוב והי' אמונת עתך — ישעי' לג, ו."],["4136","163","<b>אי אית בי' יראה אין</b>: ראה שבת לא, א בדברי רבא. וראה גם לעיל בריש המאמר ובהערה 14. לקמן (בחלק ההנחות) הנחה ד\"ה וחג הקציר בכורי מעשיך ובהערה 11."],["4137","164","<b>אהבה נק' דכר</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא פמ\"ג (סב, א</a>)."],["4138","165","<b>כי זכר חסדו</b>: תהלים צח, ג [בהוספת תיבת ”כי\" — ראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 90. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540683\" data-slug=\"torat-chaim\" data-id=\"2300540683\">תו\"ח שמות ח\"א לד, ג</a>. וש\"נ].\nראה גם לעיל סוף מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 276."],["4139","166","<b>יראה היא בחי' נוק'</b>: ראה זהר ח\"ש קכב, א. פקודי רלט, ב."],["4140","167","<b>אשה יראת ה' היא תתהלל</b>: משלי לא, ל."],["4141","168","<b>שמן הוא חכ'</b>: ראה זהר יתרו פז, ב־ תרומה קמז, ב ובהגהת הרח\"ו שם. מאורי אור מערכת שמן אות מח וביאיר נתיב שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. מאמרי אדה\"א קונטרסים ע' תקמה. וש\"נ. סה\"מ תרל\"ח ע' כג. וש\"נ. תר\"ם ח\"א ע' מט. וש\"נ."],["4142","169","<b>ויין הוא בחי' בינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["4143","170","<b>ודעת הוא בחי' סלת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380480\" data-slug=\"likkutei-torah\" data-id=\"4001380480\">לקו\"ת שלח מב, א</a>. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 102 ואילך."],["4144","171","<b>אין התינוק יודע לקרות או\"א</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540734\" data-slug=\"torat-chaim\" data-id=\"2300540734\">תו\"ח בא ח\"א צה, ב</a>. וש\"נ.\n\n<b>לה</b> ) <b>להעיר</b>: נרשם בע' ההגהות ולא הועתק בהעתק ב' — ראה לעיל הערה 1.\n\n<b>לו</b> ) <b>אין עוד כלי</b>: מלכים-ב ד, ו."]]],[2001910410,"שיטעום דגן דוקא כו', ואעפ\"כ אי אית לי' אוצר י\"ש אין אי לא לא, שהעיקר הוא היראה שהוא הכלי כו'. וזהו ענין שבע ביום הללתיך<sup data-n=\"4145\">172</sup> שהוא בחי' השבעה בחי' אלו, דהיינו מה שחשיב כאן בחי' הששה סדרי משנה עם היראה שהוא כנגד הז\"מ לך הוי' הגדולה והגבורה<sup data-n=\"4146\">173</sup>, וז\"ע יחוד ו\"ה, וי\"ו הוא בחי' ששה סדרי משנה שהוא בחי' המשכה גבוה בחי' יחיד חי העולמים מלך<sup data-n=\"4147\">174</sup>, חי העולמים הוא בחי' וי\"ו<sup data-n=\"4148\">175</sup> שהוא בחי' המשכת הקו<sup data-n=\"4149\">176</sup> שהוא אות אמת כי אות אמת דא אות וי\"ו<sup data-n=\"4150\">177</sup> שהוא מחבר מבחי' יחיד למלך, והמשכה צריך שיהי' נמשך בה' שהוא בחי' מל'<sup data-n=\"4151\">178</sup> בחי' יראה<sup data-n=\"4152\">179</sup> דוקא כי היראה הוא הכלי שיומשך בה כל ההמשכות כו' כנ\"ל.\n\nלענין<sup data-n=\"8697\">לז</sup> הקבלת פני רבו<sup data-n=\"8698\">לח</sup> יש להעיר מענין תיקון ואמת שנת' בלק\"ת בביאור מסעי השלישי, פ\"ג דצ\"ג ע\"ב<sup data-n=\"8699\">לט</sup>, ומענין תרין תפוחין שנת' שם<sup data-n=\"8700\">מ</sup> וגם ממארז\"ל הא דחכימנא מחבראי<sup data-n=\"8701\">מא</sup> דחזיתי לר\"מ מאחוריו, ומענין דכתי' לע\"ל ולא יכנף, והי' עיניך רואותו את מוריך.",[["4145","172","<b>שבע ביום הללתיך</b>: תהלים קיט, קסד."],["4146","173","<b>לך הוי' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["4147","174","<b>יחיד חי העולמים מלך</b>: נוסח ברכת ברוך שאמר."],["4148","175","<b>חי . . וי\"ו</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן."],["4149","176","<b>וי\"ו . . המשכת הקו</b>: ראה גם לעיל מאמר ד\"ה קא מפלגי במתיבתא דרקיעא ספ\"א ובהנסמן שם."],["4150","177","<b>כי אות אמת דא אות וי\"ו</b>: ראה זהר ויחי רמא, ב. ויקרא ב, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. ביאוה\"ז להצ\"צ כרך א ויקרא ע' שיג ואילך."],["4151","178","<b>בה' שהוא בחי' מל'</b>: ראה פרדס שער האותיות שכ\"ז, פ\"ח."],["4152","179","<b>מל' בחי' יראה</b>: ראה ת\"ז בהקדמה ו, א.\n\n<b>לז</b> ) <b>לענין</b>: נרשם בע' ההגהות ולא הועתק בהעתק ב' — ראה לעיל הערה 1.\n\n<b>לח</b> ) <b>הקבלת פני רבו</b>: ר\"ה טז, ב. ראה גם שע\"ת קג, ג ובהנסמן במ\"מ לשם.\n\n<b>לט</b> ) <b>פ\"ג דצ\"ג ע\"ב</b>: פ\"ג מסתיים צג, א. ובדפו\"א צג, ריש ע\"ב.\n\n<b>מ</b> ) <b>תרין תפוחין שנת' שם</b>: צג, ג.\n\n<b>מא</b> ) <b>הא דחכימנא מחבראי</b>: ראה ערובין יג, ב."]]],[2001910411,"<h3>רני ושמחי</h3>\n<b>בס\"ד פ' בהעלותך</b>\n<b>רני</b> ושמחי<sup data-n=\"4153\">1</sup> בת ציון<sup data-n=\"4154\">2</sup> כי הנני בא ושכנתי בתוכך, פי' בת הוא ע\"ד דאיתא במד\"ר ס\"פ פקודי<sup data-n=\"4155\">3</sup> ובכ\"ד, שאל רשב\"י את ר' אלעזר בר\"י, כלום שמעת מאביך מהו בעטרה שעטרה לו אמו<sup data-n=\"4156\">4</sup>, א\"ל משל למלך שהי' לו בת וחיבבה ביותר לא זז מחבבה<sup data-n=\"4157\">5</sup> עד שקראה בתי<sup data-n=\"4158\">6</sup> לא זז מחבבה עד שקראה אחותי לא זז מחבבה עד שקראה אמי, כך הקב\"ה בתחלה קראן לישראל בת שנא' (תלים מ\"ב) שמעי בת וראי הטי אזנך שכחי עמך ובית אביך<sup data-n=\"4159\">7</sup> ויתאוו המלך יפיך<sup data-n=\"4160\">8</sup>, לא זז מחבבן עד שקראן אחותי שנאמר פתחי לי אחותי רעייתי יונתי תמתי (בשה\"ש ה')<sup data-n=\"4161\">9</sup>, לא זז מחבבן עד שקראן אמי שנא' הקשיבו אלי עמי ולאומי אלי האזינה (ישעי' נ\"א)<sup data-n=\"4162\">10</sup> ולאמי כתיב<sup data-n=\"4163\">11</sup>, וזהו בעטרה שעטרה לו אמו שהוא מה שקראן אמי.\n<b>והנה</b> ג' בחי' אלו הם בבחי' שכאשר המל'<sup data-n=\"4164\">12</sup> היא מקבלת מבחי' ז\"א אז היא נק' בתי שהיא בחי' מקבל, ובחי' אחותי היא כאשר ז\"א ומל' שוין בקומתן<sup data-n=\"4165\">13</sup> שזהו שני",[["4153","1","<b>רני ושמחי</b>: חלק ממאמר ד\"ה זה שנדפס בסה\"מ תרכ\"ז ע' שכא ואילך (ג' פרקים). וש\"נ. והמשכו (פרקים ד-ו) נדפס לקמן מאמר ד\"ה ומעתה צ\"ל מפני מה כל הנשמה.\nנעתק מבוך תרמ\"א 2086 — כת\"י מעתיק."],["4154","2","<b>רני ושמחי בת ציון</b>: זכרי' ב, יד."],["4155","3","<b>במד\"ר ס\"פ פקודי</b>: בשינויים."],["4156","4","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["4157","5","<b>לא זז מחבבה</b>: בהמשך מים רבים תרל\"ו ע' קמט בהערה מציין: ראה שמו\"ר ס\"פ נב. במ\"ר פי\"ב, ח. שהש\"ר ספ\"ג. פסיקתא דר\"כ פ\"א. בסה\"מ מלוקט ד ע' קצה בהערה 34 מציין: כ\"ה הלשון ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370165\" data-slug=\"torah-or\" data-id=\"3901370165\">תו\"א מקץ לו, א</a>. ובאוה\"ת בא שם ע' רנח. ובכ\"מ. שם ע' רפג בהערה 9 מציין: כ\"ה הלשון ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370165\" data-slug=\"torah-or\" data-id=\"3901370165\">תו\"א [מקץ לו, א</a>] וברד\"ה תרכ\"ז הנ\"ל שם [סה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' רצז — ובמהדורת תש\"ס ע' שכא]. ובכ\"מ.\nראה גם לקו\"א להה\"מ יב, סע\"ב (אות סא). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380156\" data-slug=\"likkutei-torah\" data-id=\"4001380156\">לקו\"ת שמיני יט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380466\" data-slug=\"likkutei-torah\" data-id=\"4001380466\">שלח לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380616\" data-slug=\"likkutei-torah\" data-id=\"4001380616\">בלק עד, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380660\" data-slug=\"likkutei-torah\" data-id=\"4001380660\">מטות פד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380843\" data-slug=\"likkutei-torah\" data-id=\"4001380843\">פ' ראה לא, ד</a>. נצבים מד, ד. בהערה הבאה."],["4158","6","<b>לא זז מחבבה עד שקראה בתי</b>: רש\"י שה\"ש שם. וכ\"ה גם בילקוט שמעוני פקודי לט, לג [רמז תיז]. שה\"ש שם [אלא שבילקוט שה\"ש הסדר: אחותי אמי בתי. וכן הוא הסדר בפ' פקודי, אבל כשמביא (בפ' פקודי שם) הפסוקים אז הסדר: בתי אחותי אמי]."],["4159","7","<b>(תלים מ\"ב) שמעי בת . . אביך</b>: וכ\"ה בסה\"מ תרכ\"ז כאן. תהלים מה, יא [ושם: והטי . . ושכחי].\nהכתוב הובא גם בשמו\"ר ותו\"א שם. בבמד\"ר שם חסר. בשהש\"ר־ בפסיקתא־ וברש\"י וילקוט שמעוני שם־ וכן בתנחומא באבער פקודי ח הובא רק: שמעי בת וראי."],["4160","8","<b>ויתאוו המלך יפיך</b>: שם שם, יב [ושם: ויתאו]. פסוק זה הובא גם בתו\"א שם. אבל לא הובא במדרשים וברש\"י שם."],["4161","9","<b>פתחי לי אחותי . . תמתי (שה\"ש ה')</b>: פסוק ב. וכ\"ה בשמו\"ר שם."],["4162","10","<b>הקשיבו אלי . . (ישעי' נ\"א)</b>: פסוק ד [ושם: האזינו]."],["4163","11","<b>ולאומי . . ולאמי כתיב</b>: לפנינו כתוב: ולאומי. אבל ראה במד\"ר־ שהש\"ר־ פסיקתא־ תנחומא־ רש\"י־ וילקוט שמעוני שם. ראה גם מתנות כהונה לשמו\"ר שם. בזהר ואתחנן רסב, א: אל תקרי לאומי אלא לאמי דלא זז קב\"ה מחבבה לכנס\"י עד דקראה אמי. מנחת שי ישעי' שם. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכד. מאמרי אדה\"א בראשית ע' שכט. וראה במ\"מ ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370165\" data-slug=\"torah-or\" data-id=\"3901370165\">תו\"א לו, א</a> ד\"ה ולאמי כתיב."],["4164","12","<b>בבחי' שכאשר המל'</b>: אוצ\"ל: בבחי' המל' שכאשר."],["4165","13","<b>ז\"א ומל' שוין בקומתן</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. פ\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג ואילך."]]],[2001910412,"המאורות הגדולים<sup data-n=\"4166\">14</sup> שגם המל' היא בחי' הלבנה<sup data-n=\"4167\">15</sup> מדרגת נש\"י שלכן ישראל מונים ללבנה<sup data-n=\"4169\">17</sup> שרש מדריגתן<sup data-n=\"4168\">16</sup> היא שוה בקומתה לבחי' ז\"א ושניהם מקבלים מבחי' חכמה שכמו בחי' ז\"א מקבלים מבחי' חו\"ב ככה גם המל' מקבלת ג\"כ מבחי' חו\"ב שזהו מ\"ש וגם אמנה אחותי בת אבי<sup data-n=\"4170\">18</sup> שכאשר היא בחי' ומדריגת אחותי אז היא מקבלת מבחי' אבי בחי' חכמה, ובחי' אמי היא כאשר המל' עולה לבחי' בינה אז היא נעשה בחי' משפיע לבחי' ז\"א, וזהו בעטרה שעטרה לו אמו שהוא כאשר המל' עולה להיות במדריגת בינה כו'.\n<b>ולהבין</b> ג' בחי' אלו בעבודה שיש בנש\"י, כי כנס\"י היא בחי' מל'<sup data-n=\"4171\">19</sup> ומאחר שנמצא בבחי' מל' ג' מדרגות אלו עכצ\"ל שבנש\"י יש ג\"כ ג' בחי' אלו. והענין הוא דהנה כתיב נר הוי' נשמת אדם<sup data-n=\"4172\">20</sup> שנש\"י הם נר הוי', וכמו דאיתא במד\"ר ע\"פ בהעלותך<sup data-n=\"4173\">21</sup> את הנרות שאתם מאירים למי שמאיר לכל העולם, הרי כי נש\"י הם נר הוי', ופעם כתיב כי אתה נרי הוי' והוי' יגיה חשכי<sup data-n=\"4174\">22</sup>, הרי כי נק' הקב\"ה נר שמאיר לישראל שזהו שאומר דוד בחי' מל'<sup data-n=\"4175\">23</sup> שורש נש\"י אתה נרי הוי'. אך הענין יובן בהקדם ענין מ\"ש כל הנשמה תהלל י\"ה<sup data-n=\"4176\">24</sup> (ומה שהקדים רבינו ז\"ל<sup data-n=\"4177\">25</sup> בפסוק כל הנשמה מפני כי עליית המל' בבחי' אמי היא בינה, ונשמה הוא ג\"כ בחי' בינה<sup data-n=\"4178\">26</sup> כמ\"ש ונשמת שדי תבינם<sup data-n=\"4179\">27</sup> לכן הקדים בפסוק זה) פי' תהלל הוא מל' בהילו נרו על ראשי<sup data-n=\"4180\">28</sup> שהוא ל' הארה, דהנה התהוות כל העולמות הוא מהארה בעלמא שלכן אני ה' לא שניתי<sup data-n=\"4181\">29</sup> ואתה הוא קודם שנברא העולם<sup data-n=\"4182\">30</sup> ואתה הוא לאחר שנבה\"ע שאין בו ית' שום שינוי מפני שלא כמו שהנשמה מחי' את הגוף הקב\"ה מחי' את העולם",[["4166","14","<b>שני המאורות הגדולים</b>: בראשית א, טז."],["4167","15","<b>המל' היא בחי' הלבנה</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לבנה."],["4169","17","<b>ישראל מונים ללבנה</b>: ראה סוכה כט, א."],["4168","16","<b>שלכן . . מדריגתן</b>: בסה\"מ תרכ\"ז מהדורת תש\"ס כאן: (שלכן . . מדריגתן)."],["4170","18","<b>וגם אמנה אחותי בת אבי</b>: וירא כ, יב."],["4171","19","<b>כנס\"י היא בחי' מל'</b>: ראה זהר בלק קצז, א."],["4172","20","<b>נר הוי' נשמת אדם</b>: משלי כ, כז. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370182\" data-slug=\"torah-or\" data-id=\"3901370182\">תו\"א מקץ מ, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">מא, א</a>."],["4173","21","<b>וכמו דאיתא במד\"ר ע\"פ בהעלותך</b>: בהעלותך ח, ב. ראה במד\"ר פט\"ו, ה. תנחומא בהעלותך ד. וראה גם שמו\"ר פל\"ו, ב.\nבסה\"מ תרכ\"ז (שבהערה 5) מובא הלשון: וכמו שפרש\"י ע\"פ בהעלותך. בסה\"מ מלוקט ד ע' רפד בשולי היריעה מעיר: בסה\"מ שם וכמו שפרש\"י ע\"פ בהעלותך. וכפה\"נ הוא ט\"ס וצ\"ל: וכמו [שפי'] במד\"ר ע\"פ בהעלותך."],["4174","22","<b>כי אתה נרי . . חשכי</b>: שמו\"ב כב, כט."],["4175","23","<b>דוד בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["4176","24","<b>כל הנשמה תהלל י\"ה</b>: תהלים קנ, ו."],["4177","25","<b>ומה שהקדים רבינו ז\"ל</b>: כ\"ק אדמו\"ר הזקן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370165\" data-slug=\"torah-or\" data-id=\"3901370165\">תו\"א מקץ כאן לו, א</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכד."],["4178","26","<b>ונשמה . . בחי' בינה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. סה\"מ תר\"מ ח\"ב ע' תרכח. וש\"נ."],["4179","27","<b>ונשמת שדי תבינם</b>: איוב לב, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600675\" data-slug=\"or-hatorah-hb\" data-id=\"8316600675\">אוה\"ת איוב כרך א ע' תרעה</a> ואילך."],["4180","28","<b>בהילו נרו על ראשי</b>: איוב כט, ג [ושם: עלי]."],["4181","29","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["4182","30","<b>ואתה הוא קודם שנברא העולם</b>: ראה נוסח תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."]]],[2001910413,"שהנשמה מחי' את הגוף היא מתלבשת בתוך הגוף ולכן היא מתפעלת ממקרי הגוף<sup data-n=\"4183\">31</sup>, אבל הקב\"ה אינו כמו הנשמה שאינו מתלבש כלל, ולכן אינו פועל העולם בו ית' שום שינוי שזהו מ\"ש כי לא מחשבותי מחשבותיכם<sup data-n=\"4184\">32</sup> שלא כמו באדם הנה הנפש מתלבש מהמחשבה שהמח' היא מלביש את הנפש וכאשר האדם חושב מח' אחת אינו יכול לחשוב מחשבה אחרת כ\"א שיפשוט תחלה את המחשבה זו וילביש אח\"כ המחשבה השני', אבל למעלה הנה לא כמחשבותיכם מחשבותי שאינו מתלבש כלל בהמח', ולכן אני ה' לא שניתי כלל ואתה הוא קודם שנברא העולם ואתה הוא אחר שנבה\"ע בלי שום שינוי כלל וכלל כו', וזהו מ\"ש נפלאותיך ומחשבותיך אלינו אין ערוך אליך<sup data-n=\"4185\">33</sup> פי' נפלאותיך הוא בחי' כתר ומחשבותיך חכ' אין ערוך אליך לעצמיותו ית', כי הוא למעלה<sup data-n=\"4186\">34</sup> מבחי' כתר וחכ' כו'.\n<b>קיצור</b> לא זז מחבבה עד שקראה בתי אחותי אמי, בת היא שכשהמל' מקבלת מז\"א, אחותי כששוין בקומתן והמל' מקבלת מחו\"ב כמו ז\"א, אחותי בת אבי, אמי כשהמל' משפיע בז\"א. ובחי' אלו בעבודה בנש\"י, הנה נר הוי', וצ\"ל הלא כי אתה נרי כו', הנה כל הנשמה כו', פי' תהלל ל' בהלו נרו כי התהוות כל העולמות מהארה בעלמא, לא שניתי, שלא כמו הנשמה שמתלבשת ומתפעלת כו', אבל למעלה לא מחשבותי מחשבותיכם שאינו מתלבש, וזהו נפלאותיך כתר מחשבותיך חכ' אין ערוך אליך.\nב) <b>ובזה</b> יובן ל' רז\"ל גלוי וידוע לפני מי שאמר והי' העולם<sup data-n=\"4187\">35</sup>, וכיוונו בלשון ידוע שידוע לפניו ממילא ואינו בבחי' התלבשות בבחי' המחשבה, שזהו מ\"ש הרמב\"ם שהוא היודע<sup data-n=\"4188\">36</sup> והוא הידוע והוא הדיעה עצמה, פי' כי יש ב' בחי' דעת ד\"ת וד\"ע, ד\"ת הוא הדעת המאיר בע\"ס שזהו הוא היודע שהידיעה הוא מחמת בחי' ההתלבשות בע\"ס, והוא הידוע הוא בחי' ד\"ע שכולם נסקרים בסקירה אחת<sup data-n=\"4189\">37</sup>, ואעפ\"כ גם בבחי' דעת עליון זה ידוע לפניו הכל בפרטיות, וכמשארז\"ל בר\"ה כל באי העולם<sup data-n=\"4190\">38</sup> עוברין לפניו כבני מרון שידוע לפניו כאו\"א בפרטיות כמו בני מרון, ולמדו זה מפסוק<sup data-n=\"4191\">39</sup> היוצר יחד לבם<sup data-n=\"4192\">40</sup> המבין אל כל מעשיהם, ופי' היוצר יחד לבם הוא מה שנסקרים לפניו כולם בסקירה אחת, והמבין אל כל מעשיהם הוא שכאו\"א",[["4183","31","<b>שהנשמה . . מתפעלת ממקרי הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>). לעיל מאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיע ובהערה 10."],["4184","32","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["4185","33","<b>נפלאותיך ומחשבותיך . . אליך</b>: תהלים מ, ו. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370148\" data-slug=\"torah-or\" data-id=\"3901370148\">תו\"א מקץ לא, ד</a>. ראה גם לעיל מאמר ד\"ה וירא ישראל את היד הגדולה פ\"ב."],["4186","34","<b>הוא למעלה</b>: בסה\"מ תרכ\"ז כאן ע' שכב: הוא ית' למעלה."],["4187","35","<b>גלוי וידוע . . והי' העולם</b>: ערובין יג, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370066\" data-slug=\"torah-or\" data-id=\"3901370066\">תו\"א וירא יד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550112\" data-slug=\"torat-chaim\" data-id=\"2300550112\">תו\"ח משפטים ח\"ב רעט, ג</a>. וש\"נ. סהמ\"צ להצ\"צ פא, ב. הנסמן בסה\"מ תרכ\"ז כאן ע' שכב."],["4188","36","<b>מ\"ש הרמב\"ם שהוא היודע</b>: הל' יסוה\"ת פ\"ב, ה\"י."],["4189","37","<b>שכולם נסקרים בסקירה אחת</b>: ר\"ה יח, א."],["4190","38","<b>וכמשארז\"ל בר\"ה כל באי העולם</b>: טז, א [במשנה. ושם: עולם. אבל במשנה שבמשניות ובשינויי נוסחות שם, ובגמרא יח, א כבפנים]."],["4191","39","<b>ולמדו זה מפסוק</b>: ראה ר\"ה, יח, א."],["4192","40","<b>היוצר יחד לבם</b>: תהלים לג, טו."]]],[2001910414,"נזכר לפניו בפרטיות, והיינו אף שנזכרים לפניו כל באי עולם כבני מרון בפרטיות וכמ\"ש בדה\"א ך\"ח ט' כי כל מחשבות<sup data-n=\"4193\">41</sup> לבבות דורש ה' וכל יצר מחשבות מבין, וארז\"ל בב\"ר עד שלא נוצרה המחשבה<sup data-n=\"4194\">42</sup> בלבו של אדם גלוי וידוע לפניו ית', אך כ\"ז הוא בסקירה א' בדרך גלוי וידוע לפניו שאינו מתלבש כלל בידיעה זו רק שהיא ידוע מאליו וממילא.\n<b>ובזה</b> תירץ רבינו ז\"ל<sup data-n=\"4195\">43</sup> מה שלכאו' הידיעה שמבין מחשבת כל הנבראי', הוא למעלה כמו מחשבות זרות כי האדם יכול לחשוב דברי הבאי, ואף גם כל מחשבות הנבראי' לעוצם פחיתותם נק' למעלה דברים זרים, וא\"כ הם כמו מחשבות זרות חלילה, ותירץ שאין זו בחי' התלבשות המח' כלל כ\"א שהוא בדרך גלוי וידוע, וכמו שמצינו שטעו אחי יוסף במה שדימו שיוסף הוא איש פשוט מפני שראו אותו עוסק בדברי העולם, כי הם בחרו יותר להיות רועי צאן<sup data-n=\"4196\">44</sup> מפני שלמלאכת רועי צאן אינו נצרך המח' כלל ולכן הי' המחשבה פנוי אצלם מהמלאכה והיו יכולים להיות תמיד מרכבה<sup data-n=\"4197\">45</sup> לאלקות, אבל את יוסף ראו שהוא עוסק בדברי העולם ולכן דימו שהוא באמת איש פשוט ואינו מרכבה כלל, אבל באמת טעו בזה והיינו מפני כי אצלם מפני כי שרשם הוא מעולם הבריאה<sup data-n=\"4198\">46</sup> לכן אם היו עוסקים במו\"מ בדברי העולם הוא<sup data-n=\"4199\">47</sup> המחשבה מדברי העולם מעכב לבלתי יכולים<sup data-n=\"4200\">48</sup> להיות בבחי' מרכבה, אבל יוסף מפני שהי' מאצי'<sup data-n=\"4201\">49</sup> וגם באצי' גופא הי' מבחי' גבוה מאד לכן לא הי' המחשבה מדברי העולם מבלבל אותו כלל, וזהו שאמר יוסף לאחיו התחת אלקים אני<sup data-n=\"4202\">50</sup>, פי' הרי אני למעלה מבחי' שם אלקים מל' דאצי' ולא התחת שם אלקי' כמו אתם. ועד\"ז יובן למעלה בענין גלוי וידוע אף שזהו מחשבות האדם אעפ\"כ אינם נק' חלילה בשם מח' זרה למעלה כלל כמו שלגבי יוסף לא היו המחשבות מדברי העולם מבלבלים (וזהו שפעל הבעש\"ט ז\"ל בסוף ימיו<sup data-n=\"4203\">51</sup> שאף שהי' למטה בעוה\"ז הגשמי לא יהי' לו שום סתירה כלל להיות ג\"כ בעולמות עליונים, וכנודע ממה שבליל ש\"ק הי' ב' שליש למעלה ושליש אחד למטה ובשאר ימי החול בהיפוך כו'). וזהו קדוש קדוש",[["4193","41","<b>מחשבות</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. והוא הוספה על לשון הכתוב."],["4194","42","<b>עד שלא נוצרה המחשבה</b>: ראה ב\"ר פ\"ט, ג."],["4195","43","<b>תירץ רבינו ז\"ל</b>: כ\"ק אדמו\"ר הזקן במאמרי אדה\"ז תקס\"ה ח\"א ע' קצג. תו\"ח מקץ קג, ג ואילך. אוה\"ת וישב כרך ו ע' תתשב, א ואילך. הנסמן בסה\"מ תרכ\"ז כאן ע' שכג."],["4196","44","<b>אחי יוסף . . רועי צאן</b>: וישב לז, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קצב. תקע\"א ע' פח. סה\"מ תרכ\"ט ע' קעב. וש\"נ. ע' רפא. וש\"נ."],["4197","45","<b>אחי יוסף . . תמיד מרכבה</b>: ראה זהר ויחי רמא, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370131\" data-slug=\"torah-or\" data-id=\"3901370131\">תו\"א וישב כח, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680072\" data-slug=\"torat-chaim\" data-id=\"2300680072\">תו\"ח ויחי רמג, ב</a> ובהערה 32. לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 179."],["4198","46","<b>שרשם הוא מעולם הבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370455\" data-slug=\"torah-or\" data-id=\"3901370455\">תו\"א</a> וישב וד\"ה קדש ישראל שם. וראה גם תו\"א ויחי קג, סע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680040\" data-slug=\"torat-chaim\" data-id=\"2300680040\">תו\"ח ויחי רמב, ד</a>."],["4199","47","<b>הוא</b>: בסה\"מ תרכ\"ז כאן ע' שכג: הי'."],["4200","48","<b>לבלתי יכולים</b>: שם: לבלתי יהיו יכולים."],["4201","49","<b>יוסף מפני שהי' מאצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370131\" data-slug=\"torah-or\" data-id=\"3901370131\">תו\"א וישב כח, א</a> ואילך. סה\"מ תרכ\"ט ע' רפב. וש\"נ."],["4202","50","<b>התחת אלקים אני</b>: ויחי נ, יט. ראה גם סה\"מ תרכ\"ט ריש ע' שנ."],["4203","51","<b>שפעל הבעש\"ט ז\"ל בסוף ימיו</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קצג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680384\" data-slug=\"torat-chaim\" data-id=\"2300680384\">תו\"ח ויחי רמט, ג</a> ובהערה 40. סה\"מ תרל\"ג ח\"א ע' סו. וש\"נ."]]],[2001910415,"קדוש ה' צבאות<sup data-n=\"4204\">52</sup> פי' כדי להיות ה' צבאות זהו ע\"י שיהי' תחלה ג\"פ קדוש, לפי שהוא ית' קדוש ומובדל ואינו מתלבש כלל כ\"א גלוי וידוע כו', לכן צ\"ל ג\"פ קדוש עד שיהי' ה' צבאות אות הוא בצבא שלו<sup data-n=\"4205\">53</sup> כו'.\n<b>קיצור</b> ובזה יובן ל' רז\"ל גלוי וידוע, פי' שידוע מאליו וממילא בלתי התלבשות, ופי' הוא היודע בחי' ד\"ת מחמת ההתלבשות בע\"ס, והוא הידוע בבחי' ד\"ע שנסקרי' בסקירה א', ואעפ\"כ ידוע כל דבר בפרטיות, כבני מרון בפרטיות, וזהו היוצר יחד לבם ואעפ\"כ המבין אל כל מעשיהם, ובזה תי' רבינו ז\"ל מה שלכאו' זהו כמו מח' זרות, אך באמת ז\"א לפי שאינו בבחי' התלבשות כלל<sup data-n=\"4206\">54</sup>, וכמו שהשבטי' דימו שיוסף הוא איש פשוט, לפי שעסק בעניני העולם, ובאמת לא בלבלו לו כלל עניני העוה\"ז ובעת מעשה הי' מרכבה, להיותו בחי' ומדריגה גבוה שבאצי', וזהו התחת אלקי' אני כו', וכש\"כ<sup data-n=\"4207\">55</sup> שכמו\"כ יובן למעלה כו' שזהו רק בדרך גלוי וידוע מאליו וממילא כו', ולכן צ\"ל ג\"פ קדוש עד שיהי' הוי' צבאות שזהו מה שמתייחד עם מלאכי' ונשמות דבי\"ע ע' בת\"א בפ' בא בד\"ה ויהי בעצם<sup data-n=\"4208\">56</sup> כו' יצאו כו'.\nג) <b>והנה</b> כתיב כי בי\"ה ה' צור עולמים<sup data-n=\"4209\">57</sup> ביו\"ד נברא העוה\"ב<sup data-n=\"4210\">58</sup> ובה' נברא העוה\"ז, פי' עוה\"ב הוא מ\"ש להנחיל אוהבי יש<sup data-n=\"4211\">59</sup>, קנה חכ' קנה בינה<sup data-n=\"4212\">60</sup> גימ' יש<sup data-n=\"4213\">61</sup>. ולהבין זה הנה כתיב אכן יש הוי' במקום הזה<sup data-n=\"4214\">62</sup> ואנכי לא ידעתי, ולכאו' הלא כתיב מכה\"כ<sup data-n=\"4215\">63</sup>, ולית אתר פנוי מיני'<sup data-n=\"4216\">64</sup>, ומהו זה שאמר יעקב אכן יש הוי' במקום הזה שמשמע שבמקום הזה דוקא יש הוי' ולא בשאר מקומות, אך הענין יובן ממה שאנו רואים בהנפש<sup data-n=\"4217\">65</sup> שמחי' את הגוף הנה התלבשות הנפש הוא במוח ששם הוא עיקר גילוי הנפש ואף שגם בכל הגוף ישנו השראת הנפש<sup data-n=\"4218\">66</sup>, אך הנה בכל הגוף אם כי ישנו",[["4204","52","<b>קדוש . . ה' צבאות</b>: ישעי' ו, ג."],["4205","53","<b>אות הוא בצבא שלו</b>: ראה חגיגה טז, רע\"א (לגי' הע\"י. רש\"י סנהדרין צב, א ד\"ה שתי אותיות). ילקוט שמעוני שה\"ש ו, א (רמז תתקצב). מערכת האלקות פ\"ד מערכת שמות המדות ד\"ה הששית (ע' סה). פט\"ו בבאור כונת . . הקדושה (ע' רה). פי' הראב\"ד לס\"י פ\"א, מ\"א (טו, ג). פ\"ב, מ\"ג (לט, סע\"ב ואילך). פרדס שעה\"כ שכ\"ג, פי\"ח מערכת צבא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540396\" data-slug=\"torat-chaim\" data-id=\"2300540396\">תו\"ח בא ח\"א קיד, ד</a>. וש\"נ."],["4206","54","<b>כלל</b>: בסה\"מ תרכ\"ז כאן ע' שכט: כו'."],["4207","55","<b>אני כו' וכש\"כ</b>: שם: כו' וכ\"ש."],["4208","56","<b>בת\"א בפ' בא בד\"ה ויהי בעצם</b>: ס, ב ואילך. וראה ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540063\" data-slug=\"torat-chaim\" data-id=\"2300540063\">תו\"ח</a> שם.\nבתו\"א שם הפתיחה היא: בעצם היום הזה. וכן הוא במאמרי אדה\"ז תקס\"ה ח\"א ע' רו. ובהנחת כ\"ק אדה\"א [שלא נדפסה לע\"ע]. וראה ב' הגירסאות בתו\"ח בא ח\"א קיב, א ובהערה 2."],["4209","57","<b>כי בי\"ה ה' צור עולמים</b>: ישעי' כו, ד."],["4210","58","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב. לעיל מאמר ד\"ה מגילה נקראת ובהערה 94."],["4211","59","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["4212","60","<b>קנה חכ' קנה בינה</b>: משלי ד, ה."],["4213","61","<b>קנה . . קנה . . גימ' יש</b>: ראה לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 58."],["4214","62","<b>אכן יש הוי' במקום הזה</b>: ויצא כח, טז. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"ב ובהנסמן שם."],["4215","63","<b>מכה\"כ</b>: ישעי' ו, ג."],["4216","64","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["4217","65","<b>בהנפש</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' רצט. אבל במהדורת תש\"ס ע' שכד: בנפש האדם."],["4218","66","<b>התלבשות הנפש . . השראת הנפש</b>: ראה תניא פנ\"א ואילך. וראה גם לעיל מאמר ד\"ה קדש ישראל לה' הערה 91."]]],[2001910416,"גם שם הנפש שמחי' אך הוא בהעלם, משא\"כ במוח שבראש ששם מאיר גילוי הנפש. וכמו\"כ יובן במה שאמר יעקב אכן יש הוי' במקום הזה מפני כי במקום הזה מאיר אוא\"ס ב\"ה בבחי' גילוי, משא\"כ בשאר המקומות אף שמכה\"כ אך זהו בהעלם והיינו כי המקום הזה הי' מקום בית מקדשינו כמ\"ש אין זה כ\"א בית אלקים<sup data-n=\"4219\">67</sup>, לכן הי' מאיר שם שם הוי' בבחי' גילוי שזהו יש הוי'. וכמו\"כ הו\"ע להנחיל אוהבי יש שהוא בחי' עוה\"ב שמאיר שם גילוי אלקות.\n<b>וכדי</b> להיות בחי' עוה\"ב זהו ביו\"ד נברא העוה\"ב שצ\"ל תחלה בחי' יו\"ד שהוא צמצום<sup data-n=\"4220\">68</sup> שיוכל להיות אח\"כ בחי' ומדריגת עוה\"ב, כי הנה אנו אומרים אין ערוך לך<sup data-n=\"4221\">69</sup> כו' בעוה\"ז ואין זולתך מלכנו לחיי העוה\"ב שגם בחי' עוה\"ב ג\"כ אין ערוך לך כו' לכן כדי שיהי' עוה\"ב זהו ע\"י יו\"ד וצמצום. וגם זהו ע\"ד צמצם שכינתו בין שני בדי ארון<sup data-n=\"4223\">71</sup>, וכמו אנכי ולא יהי' לך מפי הגבורה שמענו<sup data-n=\"4224\">72</sup>, וכן קודם עשה\"ד נא' וידבר אלקים<sup data-n=\"4225\">73</sup> בחי' צמצום<sup data-n=\"4226\">74</sup> שכדי להיות גילוי זהו ע\"י צמצום דוקא כו'<sup data-n=\"4222\">70</sup>. ובה' נברא העוה\"ז שעוה\"ז צ\"ל בה\"א דוקא ולא ביו\"ד, דהנה כתי' שרי אשתך לא תקרא שמה שרי כי שרה שמה<sup data-n=\"4227\">75</sup>, דכדי שתוכל שרה להוליד צריכה שתהא נקרית שרה בה\"א דוקא, ולכאו' הרי היו\"ד גבוה מבחי' הה\"א שביו\"ד נברא העוה\"ב, והענין הוא דהנה שרה הוא בחי' שררה<sup data-n=\"4228\">76</sup> מלכותך מלכות כל עולמים<sup data-n=\"4229\">77</sup> מקור התהוות כל העולמות, וזהו ע\"י ה' דוקא, כי יו\"ד הוא בחי' צמצום ואם הי' בריאת עוה\"ז ע\"י יו\"ד הי' החיות מצומצם יותר מדאי והי' יכול להיות יניקה לחיצונים, כי מדת המל' בעצם היא בחי' הגבהה והתנשאות, ואם ע\"י<sup data-n=\"4230\">78</sup> יו\"ד הי' ריבוי צמצומים ויהי' מזה יניקה לחיצונים, אך כדי להיות עוה\"ב שזהו בהכרח שיהי' ע\"י צמצום היו\"ד דוקא וכמו שמצינו בענין השערות שארז\"ל שער באשה ערוה<sup data-n=\"4231\">79</sup>, ולמעלה הנה עיקר ההמשכה הוא ע\"י השערות דוקא כמ\"ש ושער רישי'<sup data-n=\"4232\">80</sup> כו', וכמו\"כ הוא בענין היו\"ד דעוה\"ב בהכרח שיהי' ע\"י יו\"ד דוקא, אבל עוה\"ז צריך שיהי' ע\"י ה\"א דוקא. והנה מתחלת הבריאה נברא",[["4219","67","<b>אין זה כ\"א בית אלקים</b>: ויצא כח, יז."],["4220","68","<b>יו\"ד שהוא צמצום</b>: ראה גם אגה\"ת פ\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540145\" data-slug=\"torat-chaim\" data-id=\"2300540145\">תו\"ח בשלח ח\"א קנ, ב</a>. וש\"נ."],["4221","69","<b>אין ערוך לך</b>: ברכת יוצר לשבת."],["4223","71","<b>צמצם שכינתו . . ארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380223\" data-slug=\"likkutei-torah\" data-id=\"4001380223\">לקו\"ת אמור לד, ב</a>. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["4224","72","<b>אנכי ולא יהי' לך מפי הגבורה שמענו</b>: מכות כד, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131119\" data-slug=\"likkutei-sichot\" data-id=\"1300131119\">לקו\"ש מסעי כרך יג ע' 119</a> ואילך. סה\"ש תנש\"א ע' 302 ואילך. סה\"מ תר\"ם ח\"ב ע' תרלט. וש\"נ."],["4225","73","<b>וידבר אלקים</b>: יתרו כ, א."],["4226","74","<b>אלקים בחי' צמצום</b>: ראה שער היחוה\"א רפ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."],["4222","70","<b>וגם זהו . . דוקא כו'</b>: בסה\"מ תרכ\"ז ליתא."],["4227","75","<b>שרי אשתך . . שרה שמה</b>: לך יז, טו [ושם: את שמה. אבל כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370057\" data-slug=\"torah-or\" data-id=\"3901370057\">תו\"א</a> המובא בסמוך]. ראה תו\"א לך יג, ב."],["4228","76","<b>שרה . . שררה</b>: רש\"י נח יא, כט. וראה רש\"י לך יז, טו. ברכות יג, א. ב\"ר רפמ\"ז."],["4229","77","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["4230","78","<b>ואם ע\"י</b>: אוצ\"ל: ואם הי' ע\"י."],["4231","79","<b>שער באשה ערוה</b>: ברכות כד, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380213\" data-slug=\"likkutei-torah\" data-id=\"4001380213\">לקו\"ת אמור לא, סע\"ד</a> ואילך. מאמרי אדה\"א דברים ח\"א ע' קיב. וש\"נ. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"ה."],["4232","80","<b>ושער רישי'</b>: ע\"פ דניאל ז, ט."]]],[2001910417,"העוה\"ב והעוה\"ז מחמת כי חפץ חסד<sup data-n=\"4233\">81</sup> הוא<sup data-n=\"4234\">82</sup>, אבל עכשיו זאת היא עבודת האדם להמשיך בחי' אלו ע\"י עבודתו בתומ\"צ<sup data-n=\"4235\">83</sup>, אך ע\"י מה ממשיכים בחי' אלו זהו ע\"י בחי' המצות שזהו מ\"ש לעבדה ולשמרה<sup data-n=\"4236\">84</sup> לעבדה בה\"א ולשמרה בה\"א שב' ההי\"ן אלו הם העוה\"ב והעוה\"ז, ומשארז\"ל שביו\"ד נברא העוה\"ב היינו שנברא ביו\"ד, אבל עוה\"ב בעצם הם<sup data-n=\"4238\">86</sup> בחי' ה\"א<sup data-n=\"4237\">85</sup>, וע\"י לעבדה ולשמרה שהם בחי' המצות כי לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת<sup data-n=\"4239\">87</sup> ממשיכי' בחי' עוה\"ב ועוה\"ז. וזהו כל הנשמה תהלל י\"ה שעבודת האדם להמשיך בחי' יו\"ד ה\"א, שזהו פי' תהלל בהילו נרו ל' הארה היינו שיהי' הארת יו\"ד ה\"א להיות ביו\"ד נברא העוה\"ב ובה\"א נברא העוה\"ז.\n<b>קיצור</b> והנה כתי' כי בי\"ה כו' וארז\"ל במנחות ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז, עוה\"ב להנחיל אוהבי יש קנה חכ' קנה בינה גימ' יש, ע\"ד שיעקב אמר היש הוי'<sup data-n=\"4240\">88</sup>, וצ\"ל הלא לית אתר פנוי כו', מכה\"כ, אך כמו הנפש מחי' כל<sup data-n=\"4241\">89</sup> הגוף מ\"מ עיקר השראת הנפש הוא בראש, כמו\"כ יובן הגם כי מכה\"כ מ\"מ הבהמ\"ק הי' שער השמים<sup data-n=\"4242\">90</sup> ששם הי' גילוי ש' הוי' וזהו היש הוי', וכמו\"כ יובן ענין להנחיל אוהבי יש, וכדי להיות עוה\"ב זהו ע\"י צמצום דיו\"ד, כי גם העוה\"ב אין ערוך לך כו'. ובה' נברא העוה\"ז יובן ממה שכדי שתוכל שרה להוליד הוסיפו לה ה\"א, והלא היו\"ד גבוה יותר, אך שרה ל' שררה בחי' מל'<sup data-n=\"4243\">91</sup> ואם הי' ע\"י יו\"ד מחמת ריבוי הצמצומים הי' נמשך יניקה לחיצונים, אבל עוה\"ב צ\"ל דוקא ביו\"ד, וכמו שער באשה ערוה, ולמעלה עיקר ההמשכות הוא ע\"י שערות דוקא, קדושה תלוי בשערות<sup data-n=\"4244\">92</sup> ואבא יונק ממזלא<sup data-n=\"4245\">93</sup>, והנה מתחלת הבריאה הי' מחמת כי חפץ חסד הוא, אבל עכשיו באתעדל\"ת תליא מילתא, והינו ע\"י לעבדה בה\"א ולשמרה בה\"א רמ\"ח מ\"ע ושס\"ה מצות ל\"ת, ב' ההי\"ן ה' ראשונה עוה\"ב, שעוה\"ב נברא ביו\"ד, אבל עצם העוה\"ב הוא בחי' ה' עילאה, וה' אחרונה בהבראם בה' בראם<sup data-n=\"4246\">94</sup>, וזהו כל הנשמה תהלל ל' בהלו נרו, י\"ה היינו מה שביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז.",[["4233","81","<b>מתחלת הבריאה . . חפץ חסד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נצבים מז, ב</a>. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["4234","82","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["4235","83","<b>עכשיו . . ע\"י עבודתו בתומ\"צ</b>: ראה ע\"ח־ לקו\"ת־ וש\"א שבהערה 81."],["4236","84","<b>לעבדה ולשמרה</b>: נסמן בסמוך הערה 87."],["4238","86","<b>הם</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' ש. אבל במהדורת תש\"ס ע' שכד: הוא."],["4237","85","<b>שביו\"ד . . העוה\"ב . . בעצם . . ה\"א</b>: ראה גם אוה\"ת חנוכה ח\"ב שיד, ב."],["4239","87","<b>לעבדה רמ\"ח . . שס\"ה מל\"ת</b>: בראשית ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["4240","88","<b>שיעקב אמר היש הוי'</b>: ראה לעיל בפנים ובהערה 62."],["4241","89","<b>כל</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' שה. אבל במהדורת תש\"ס ע' שכד: את כל."],["4242","90","<b>שער השמים</b>: ויצא כח, יז."],["4243","91","<b>שרה . . מל'</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381222\" data-slug=\"likkutei-torah\" data-id=\"4001381222\">לקו\"ת</a> להאריז\"ל ח\"ש כג, ב."],["4244","92","<b>קדושה תלוי בשערות</b>: זהר תזריע מח, ב."],["4245","93","<b>ואבא יונק ממזלא</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540755\" data-slug=\"torat-chaim\" data-id=\"2300540755\">תו\"ח שמות ח\"א לו, א</a> הערה 455."],["4246","94","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."]]],[2001910418,"<h3>ומעתה וכו' כל הנשמה</h3>\n<b>פ' שלח</b>\nד) <b>ומעתה</b> צ\"ל מפני מה כל הנשמה<sup data-n=\"4247\">95</sup> תהלל י\"ה דוקא, הלא בנפש האדם יש ג' בחי' נר\"ן<sup data-n=\"4248\">96</sup> ומפני מה בחי' נשמה דוקא, אך הענין הוא דהנה נשמה הוא מל' נשימה<sup data-n=\"4249\">97</sup>, ל' אשום ואשוף יחד<sup data-n=\"4250\">98</sup>, ומל' פי פערתי ואשאפה (בתלים סי' קי\"ט פסוק קל\"א), פי' אשום ואשוף הוא ענין רצוא ושוב, כי כדי לשאוף את ההבל שהוא חיות האדם צ\"ל ברו\"ש דוקא. ולהבין ענין ההבל, הנה כתי' הבל הבלים אמר קהלת<sup data-n=\"4251\">99</sup> הבל הבלים הכל הבל, שאמר ז' הבלים, וששה הבלים הם כנגד ששה ימי בראשית והבל הז' הוא כנגד יום השבת שנק' ג\"כ הבל, אך הבל זה דיום השבת הוא מדרגה גבוה ועל הבל זה נאמר וישע ה' אל הבל<sup data-n=\"4252\">100</sup>, וכמו\"כ מ\"ש ומותר האדם מן הבהמה אין כי הכל הבל<sup data-n=\"4253\">101</sup> הוא כמו הבל הז', שהבל זה שהוא מותר האדם מן הבהמה הוא מבחי' אין מבחי' והחכ' מאין תמצא<sup data-n=\"4254\">102</sup>, אך לגבי אוא\"ס ב\"ה נק' בשם הבלים, וכדי לקבל הבל זה צ\"ל ברו\"ש שזהו בחי' הנשימה.\n<b>ולהבין</b> ענין הרו\"ש הנה הרצוא הוא בק\"ש שהוא למס\"נ באחד<sup data-n=\"4255\">103</sup>, ופי' מס\"נ הוא מסירת הרצון<sup data-n=\"4256\">104</sup>, כי נפש נק' בשם רצון כמ\"ש אין נפשי אל העם הזה<sup data-n=\"4257\">105</sup>, ופרש\"י אין רצוני, נמצא כי נק' הנפש בשם רצון, וא\"כ מסירת הרצון הוא מס\"נ והיינו שיבטל כל הרצונות שלו ולא יהי' לו כ\"א רק רצון א' לאביו שבשמים שזהו מ\"ש מי לי בשמים<sup data-n=\"4258\">106</sup> ועמך לא חפצתי בארץ, שכל מה שעמך לא חפצתי כלל כ\"א אותך לבד, ואף שצ\"ל גם רצון לדברי העולם אך הרצון שיהי' לדברי העולם יהי' רק בבחי' עראי וטפל ועיקר הרצון יהי' רק לו ית', והוא ע\"י ההתבוננות בתיבות ה' אלקינו ה' אחד שכולו שלו כמ\"ש לי הכסף ולי הזהב אמר ה' צבאות<sup data-n=\"4259\">107</sup>, פי' כסף",[["4247","95","<b>ומעתה צ\"ל מפני מה כל הנשמה</b>: המשך להמאמר שלפנ\"ז ד\"ה רני ושמחי. נדפס גם בסה\"מ תרכ\"ז ע' שכה ואילך.\nבהעתקה גכתי\"ק אדמו\"ר מהורש\"ב המאמר מתחיל וה' ברך את אברהם בכל ונרשם שהוא על מז\"ט של אחי הרשז\"א שי' מ\"א.\nהמאמר נעתק מבוך תרמ\"א 2086 — כת\"י מעתיק."],["4248","96","<b>ג' בחי' נר\"נ</b>: ראה זהר ויגש רו, א."],["4249","97","<b>נשמה הוא מל' נשימה</b>: ראה ב\"ר ספי\"ד. מאמרי אדה\"א דברים ח\"ג ע' תת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550088\" data-slug=\"torat-chaim\" data-id=\"2300550088\">תו\"ח תצוה ח\"ב שיח, ד</a>. וש\"נ."],["4250","98","<b>אשום ואשוף יחד</b>: ישעי' מב, יד."],["4251","99","<b>הבל הבלים אמר קהלת</b>: קהלת א, ב. ראה קה\"ר וילקוט שמעוני עה\"פ. שוח\"ט רפצ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380293\" data-slug=\"likkutei-torah\" data-id=\"4001380293\">לקו\"ת בחוקותי נ, ד</a>."],["4252","100","<b>וישע ה' אל הבל</b>: בראשית ד, ד."],["4253","101","<b>ומותר האדם . . הכל הבל</b>: קהלת ג, יט. ראה לקו\"ת שם."],["4254","102","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["4255","103","<b>למס\"נ באחד</b>: ואתחנן ו, ד. ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["4256","104","<b>מס\"נ הוא מסירת הרצון</b>: ראה לקו\"ש לך ח\"ב ע' 456. שע\"ת נג, ב ואילך ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540673\" data-slug=\"torat-chaim\" data-id=\"2300540673\">תו\"ח וארא ח\"א עט, ג</a> ובהערה 483."],["4257","105","<b>אין נפשי אל העם הזה</b>: ירמי' טו, א."],["4258","106","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה זאת תהי' תורת המצורע ובהנסמן שם."],["4259","107","<b>לי הכסף ולי הזהב אמר ה' צבאות</b>: חגי ב, ח [ושם: נאום ה' צבאות — וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו\"א כאן לו, ב</a>. אבל כ\"ה בכ\"מ ומהם: מס' דרך ארץ זוטא פ\"ד. שמו\"ר פל\"ג, ד. ילקוט שמעוני מלכים-ב רפכ\"ד (רמז רמט). חגי שם!. בחיי שמות כב, כד. סה\"מ תרכ\"ז כאן]."]]],[2001910419,"וזהב הנה ארז\"ל כסף טבעא ודהבא פרי<sup data-n=\"4260\">108</sup>, ולכאו' הלא הזהב יותר חשוב מן הכסף וכמשארז\"ל במד\"ר בראשית פ' ט\"ז ע\"פ וזהב הארץ ההיא טוב<sup data-n=\"4262\">110</sup>, לא הי' העולם<sup data-n=\"4261\">109</sup> כדאי להשתמש בזהב ולא נברא אלא לבנין בהמ\"ק כו', ואעפ\"כ הזהב הוא רק פרי והכסף טבעא ולכן הזהב קונה את הכסף<sup data-n=\"4263\">111</sup>, והכסף אינה קונה את הזהב, ופי' כסף הוא טבעא שהטבע הוא בחי' הנהגת העולם והעולם אינו יכול להתנהג כ\"א ע\"פ החסד דוקא שזהו מדרגת הכסף כי כסף וזהב בשרשן הם חו\"ג<sup data-n=\"4264\">112</sup>, והתנהגות העולם הוא ע\"פ החסד דוקא כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4265\">113</sup>, אבל מבחי' הגבורות אינו יכול העולם לקבל רק לע\"ל יאמרו ליצחק כי אתה אבינו<sup data-n=\"4266\">114</sup>, אבל עכשיו אינו יכול העולם לקבל כו', ולכן כסף טבעא וזהב פרי. והנה כאשר יתבונן שלי הכסף ולי הזהב, שהכסף והזהב שלמעלה שהם חו\"ג הם בטלים לעצמותו ית', וגם למטה הנה גלגל הוא החוזר בעולם<sup data-n=\"4267\">115</sup> שנוטל הכסף והזהב מזה ונותן לזה, וזהו לי הכסף והזהב שלי הם ואני נוטלם מזה ונותנם לזה כו', עי\"ז יבוא למס\"נ באחד למסור הרצון לו ית' שכל הרצונות בהבלי העולם אינם תופסים מקום כלל. והנה ע\"י רצוא זה בק\"ש עי\"ז הוא ממשיך ביו\"ד נברא העוה\"ב, כי ע\"י שמוסר הרצון עי\"ז ממשיך למעלה ג\"כ צמצום היו\"ד להיות בחי' העוה\"ב. והנה איתא בס\"י אם רץ לבך שוב לאחד<sup data-n=\"4268\">116</sup>, לכן צ\"ל אחר הרצוא בק\"ש באחד בחי' השוב, וזהו ודברת בם<sup data-n=\"4269\">117</sup> בחי' התומ\"צ ועי\"ז ממשיך בחי' ה\"א להיות בה\"א נברא העוה\"ז, כי הה\"א הוא בחי' ג' קוין וע\"י התומ\"צ ממשיך בחי' הג' קוין להיות בה\"א נברא העוה\"ז בהבראם בה\"א בראם כו', וזהו נר ה' נשמת אדם שנשמת האדם הוא הממשיך נר הוי' להיות בחי' יו\"ד ה\"א שע\"י המס\"נ בק\"ש ממשיך בחי' יו\"ד להיות ביו\"ד נברא העוה\"ב, וע\"י תומ\"צ ממשיך בחי' ה' להיות בה' נברא העוה\"ז בהבראם בה' בראם כו', וזהו מ\"ש בית יעקב לכו ונלכה באור ה'<sup data-n=\"4270\">118</sup> באור המאיר בש' הוי' כו'<sup data-n=\"4271\">119</sup>, כי ישראל עושים בחי' ש' הוי' וכמ\"ש ה' צלך ופי' הבעש\"ט ז\"ל<sup data-n=\"4272\">120</sup>",[["4260","108","<b>כסף טבעא ודהבא פרי</b>: ב\"מ מד, ב. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600505\" data-slug=\"or-hatorah-hb\" data-id=\"8316600505\">אוה\"ת חגי כרך א ע' תקה</a>."],["4262","110","<b>וזהב הארץ ההיא טוב</b>: בראשית ב, יב."],["4261","109","<b>במד\"ר בראשית פט\"ז . . לא הי' העולם</b>: ראה שם סימן ב. ראה גם סה\"מ תרכ\"ט ע' י ואילך. וש\"נ.\nבסה\"מ תרכ\"ט שם מציין: וכ\"ה בגמ' ב\"ב דט\"ז. ויש לעיין הכוונה בזה."],["4263","111","<b>הזהב קונה את הכסף</b>: ב\"מ מד, א."],["4264","112","<b>כסף וזהב בשרשן הם חו\"ג</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061170\" data-slug=\"likkutei-sichot\" data-id=\"1300061170\">לקו\"ש תרומה כרך ו ע' 159</a>. וש\"נ."],["4265","113","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["4266","114","<b>לע\"ל . . כי אתה אבינו</b>: ישעי' סג, טז. ראה שבת פט, ב."],["4267","115","<b>גלגל הוא החוזר בעולם</b>: ראה שבת קנא, ב."],["4268","116","<b>בס\"י אם רץ לבך שוב לאחד</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ\"נ</a> [ושם: ואם] ובמ\"מ הגהות והערות קצרות לכ\"ק אדמו\"ר זי\"ע לשם מציין (פ\"א ). ראה ת\"ז בהקדמה ז, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460166\" data-slug=\"or-hatorah-hb\" data-id=\"8316460166\">אוה\"ת יתרו ע' תתקפא</a>. סה\"מ תרנ\"ט ע' ריא בהערה."],["4269","117","<b>ודברת בם</b>: ואתחנן ו, ז. ראה גם לעיל מאמר ד\"ה [נקדישך] וביאור הענין הערה 44."],["4270","118","<b>בית יעקב לכו ונלכה באור ה'</b>: ישעי' ב, ה. ראה זהר אד\"ר נשא קל, א . לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 109."],["4271","119","<b>כו'</b>: בסה\"מ תרכ\"ז כאן ע' שכו ליתא."],["4272","120","<b>ה' צלך ופי' הבעש\"ט ז\"ל</b>: תהלים קכא, ה. ראה תולעת יעקב בהקדמה ד, א. של\"ה שער הגדול ל, א־ תושב\"כ משפטים שכא, סע\"א בשם המדרש. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370075\" data-slug=\"torah-or\" data-id=\"3901370075\">תו\"א ח\"ש טז, ב</a>. מקץ לו, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכו. פרשיות התורה ח\"א ע' שמה. מאמרי אדה\"א בראשית ס\"ע שלט ואילך. דברים ח\"ד ע' א'שעד. סה\"מ תרכ\"ז כאן ע' שכו. וש\"נ. כתר שם טוב קה\"ת מהדורת תשס\"ד בהוספות סע\"ח ס\"ע שכד ואילך. וש\"נ."]]],[2001910420,"ונמצא פי' זה במדרש שמואל<sup data-n=\"4274\">122</sup> ג\"כ<sup data-n=\"4273\">121</sup>, שם הוי' הוא כמו הצל, שכמו שהצל עושה הכל מה שיעשה האדם ככה הוא שם הוי' ג\"כ שכאשר האדם מוסר הרצון שלו שהוא בחי' מס\"נ בק\"ש נעשה למעלה יו\"ד של שם הוי' כו' כנ\"ל, וזהו נר הוי' נשמת אדם כו'.\n<b>קיצור</b> אך עדיין צ\"ל מהו כל הנשמה דוקא הלא יש נר\"נ ומהו נשמה דוקא, אך הנה נשמה ל' נשימה ל' אשום ואשוף, פי פערתי ואשאפה, ופי' אשום ואשוף הו\"ע רצו\"ש, כי שאיפת ההבל הוא ברצו\"ש דוקא, ויובן ענין ההבל ממ\"ש הבל הבלים, ששה הבלים נגד וי\"ב, והבל הז' היינו הכל הבל נגד יום השבת, וכמו\"כ מותר האדם אין כי הכל הבל שמותר האדם וכן הבל דשבת הגם שהוא מבחי' אין היינו והחכ' מאין תמצא מ\"מ לגבי אוא\"ס נק' בשם הבל, וכדי לקבל הבל זה הוא ע\"י רצו\"ש, וענין הרצוא הוא המס\"נ בק\"ש שהוא מסירת הרצון, שנפש פי' רצון כמו אין נפשי פרש\"י ז\"ל אין רצוני, והיינו שיבטל כל הרצונות ולא יהי' לו כ\"א רצון פשוט לאלקות מי לי בשמים כו' וכל מה שעמך לא חפצתי כ\"א אותך, והוא ע\"י ההתבוננות איך שהכל שלו, וכמ\"ש לי הכסף ולי הזהב, שהכסף טבעא ודהבא פרי, והגם כי הזהב הוא ביוקר יותר ולא נברא זהב אלא לבנין בהמ\"ק, מ\"מ כסף וזהב הם חו\"ג והנהגת העולמות הוא ע\"י כסף דוקא, בחי' חסד כי אמרתי עולם חסד כו' מכלכל חיים בחסד<sup data-n=\"4275\">123</sup>, ולע\"ל יאמרו ליצחק גבורה<sup data-n=\"4277\">125</sup><sup data-n=\"4276\">124</sup> כי אתה אבינו, משא\"כ עכשיו, ולכן כסף טבעא, והנה שורש כסף וזהב שהם חו\"ג הם בטלים בתכלית כמ\"ש לך ה' הגדולה<sup data-n=\"4278\">126</sup> כו', וגם למטה נוטל מזה ונותן לזה לפי שהכל שלו, אשר עי\"ז יבוא למסור הרצון לו ית' שלא יהי' לו כ\"א רצון פשוט לאלקות כו', וע\"י מס\"נ זה ממשיך למעלה צמצום היו\"ד להיות ביו\"ד נברא העוה\"ב, ואיתא בס\"י אם רץ לבך שוב לאחד, היינו ודברת בם בד\"ת, ועי\"ז ממשיך להיות בה\"א נברא העוה\"ז, כי הה\"א הוא ג' קוין וע\"י תומ\"צ ממשיך הקוין כו', וזהו שע\"י הנשמה בחי' הנשימה ברצו\"ש תהלל ל' בהלו י\"ה היינו בחי' היו\"ד שבו נברא העוה\"ב והה\"א שבו נברא העוה\"ז כו', וזהו ה' צלך שכמו הצל עושה כל מה שהאדם עושה כו', כמו\"כ ע\"י רצו\"ש האדם<sup data-n=\"4279\">127</sup> נמשך בחי' יו\"ד ה\"א דש' הוי' כו'.",[["4274","122","<b>במדרש שמואל</b>: לאבות פ\"ג, מי\"ז."],["4273","121","<b>ונמצא . . ג\"כ</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' שב. אבל במהדורת תש\"ס ע' שכו: (ונמצא . . ג\"כ)."],["4275","123","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע."],["4277","125","<b>גבורה</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' שו. אבל במהדורת תש\"ס ע' של ליתא."],["4276","124","<b>ליצחק גבורה</b>: ראה פרדס שער הכינויים שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["4278","126","<b>לך ה' הגדולה</b>: דבהי\"א כט, יא."],["4279","127","<b>רצו\"ש האדם</b>: אוצ\"ל: רצו\"ש של האדם."]]],[2001910421,"ה) <b>ומעתה</b> צ\"ל מ\"ש כי אתה נרי הוי' והוי' יגיה חשכי שמשמע שהקב\"ה הוא המאיר את נש\"י כו', אך הענין דאף שנש\"י הם נר הוי' שעושין יו\"ד ה\"א כנ\"ל, אך כדי שיוכלו נש\"י לעשות יו\"ד ה\"א כו' צריך שיותן להם כח מלמעלה שיוכלו לעשות כו', והענין הוא דהנה כתיב מום בו את לחם אלקיו לא יגש להקריב<sup data-n=\"4280\">128</sup>, פי' דהנה רמ\"ח פקודין הם רמ\"ח אברים דמלכא<sup data-n=\"4281\">129</sup> כמו שהאבר הוא כלי להשראת הנפש ככה למעלה רמ\"ח פקודין הם רמ\"ח אברים דמלכא, והנה כאשר האדם פוגם בהעדר עשיית מצות עשה או בעשותו אחת ממצות ה' אשר לא תעשינה<sup data-n=\"4282\">130</sup> אז נעשה פגם באבר ההוא שזהו כמו באברי האדם כאשר יש מום באבר אזי החיות שבמקום ההוא מקולקל, ככה יובן למעלה בנמשל. והנה מום בגימ' אלקים<sup data-n=\"4283\">131</sup> והיינו שעיקר העבודה בתומ\"צ להמשיך בחי' יחוד ה' באלקי', אך כאשר יש איזה מום באיזה אבר שפוגם באיזה מ\"ע או במל\"ת עי\"ז פוגם וא\"א להיות בחי' היחוד כו', ואעפ\"כ הנה עיקר הפגם הוא בנש\"י כמ\"ש שיחת לו לא בניו מומם<sup data-n=\"4284\">132</sup>, פי' השיחת שעושין נש\"י ע\"י שפגמו באיזה מצוה לו להקב\"ה לא אינו שום פגם מזה, כ\"א בניו מומם שהפגם הוא בנש\"י אעפ\"כ א\"א להיות יחוד הוי' באלקים ואף שלמעלה אינו מגיע הפגם כ\"כ<sup data-n=\"4285\">133</sup> מ\"מ א\"א להיות היחוד כו'. והתיקון לזה הוא מ\"ש כי אתה נרי הוי' והוי' יגיה חשכי, שע\"ז ניתן כח מלמעלה כמו שמצינו בתורה שנק' עוז לנה\"א ותושי'<sup data-n=\"4286\">134</sup> לנה\"ב ככה הוא בחי' אתה תאיר נרי הוא כח לנה\"א, והוי' יגיה חשכי הוא כח לנה\"ב שלא לבוא לבחי' חטא כלל שהוא הפגם במ\"ע או במל\"ת, ואם פגם לזה הו\"ע התשובה, וזהו כי אתה נרי הוי' שזה הכח שניתן מלמעלה לנש\"י שיהיו יכולים להאיר בחי' נר הוי' כו'.\n<b>וזהו</b> שנק' נש\"י בשם בת כי בחי' בת הוא מקבל והיינו שמקבלים הכח מלמעלה להיות יכולים לבוא אח\"כ לבחי' נר הוי' נשמת אדם. וע\"פ הקבלה בחי' בת הוא יחוד המל' עם בחי' חג\"ת, שזהו מ\"ש ובמות אביה ואמה לקחה מרדכי לו לבת<sup data-n=\"4287\">135</sup>, וארז\"ל א\"ת לבת אלא לבית<sup data-n=\"4288\">136</sup>, ופי' בית הוא בחי' חג\"ת כי יש שדה ובית, שדה נה\"י ובית בחי' חג\"ת, והיינו כאשר המל' מקבלת היחוד מבחי' חג\"ת אבל לא מבחי' חב\"ד (ע' במאו\"א אות ב' סי' י\"ד ובאות שי\"ן סי' יו\"ד), וזהו מארז\"ל אשתך",[["4280","128","<b>מום בו את לחם . . להקריב</b>: אמור כא, כא."],["4281","129","<b>רמ\"ח פקודין הם רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4282","130","<b>בעשותו אחת ממצות . . תעשינה</b>: ע\"פ ויקרא ד, כז."],["4283","131","<b>מום בגימ' אלקים</b>: ראה מאו\"א מערכת מום אות יז. רמ\"ז לזהר וארא כו, סע\"ב. ערכי הכינויים לבעל סדר הדורות בערכו. אוה\"ת חנוכה ע' 632. תשא ע' א'תתמד. אמור ע' קנה וע' קנז. חוקת ע' תשסג. ע' תתיג. יו\"כ ע' א'תקנו. שה\"ש כרך ב ע' תכ. סה\"מ תרל\"ג ח\"א ע' כז. ח\"ב ע' תקכ [ושם: ובספרי. והוא טעוה\"ד וצ\"ל: ובספרי']. ר\"ע תתקצד."],["4284","132","<b>שחת לו לא בניו מומם</b>: האזינו לב, ה."],["4285","133","<b>אינו מגיע הפגם כ\"כ</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה שוש תשיש הב' על יד הערה 89."],["4286","134","<b>בתורה שנק' עוז לנה\"א ותושי'</b>: ראה בסמוך הערה 139."],["4287","135","<b>ובמות אביה ואמה . . לבת</b>: אסתר ב, ז."],["4288","136","<b>א\"ת לבת אלא לבית</b>: מגילה יג, א."]]],[2001910422,"גוצה גחין ולחיש לה<sup data-n=\"4289\">137</sup>, פי' אשתך גוצה היינו שעדיין היא בבחי' בת שאינה יכולה לקבל מבחי' חב\"ד, גחין ולחיש לה השפל עצמך והשפיע<sup data-n=\"4290\">*138</sup> לה כו'.\n<b>קיצור</b> ומעתה צ\"ל מ\"ש כי אתה נרי שמשמע שהוא ית' הוא המאיר לנש\"י, והענין דהגם שנשמת האדם היא נר הוי' שעושין וממשיכי' בחי' י\"ה כנ\"ל, מ\"מ כדי שיוכלו להמשיך צ\"ל כח ע\"ז מלמעלה, דהנה כתיב מום בו כו', פי' כי רמ\"ח פקודין הם רמ\"ח אברים דמלכא שכמו האבר הוא כלי להשראת הנפש, כמו\"כ המצות הם כלים להשראת אלקותו ית', וכשהאדם פוגם במ\"ע או במצות ל\"ת עי\"ז נעשה פגם בהאבר שז\"ע מום שמחוסר אבר שאינו נמשך הכח מהנפש החיות<sup data-n=\"4291\">138</sup> של האבר ההוא, והנה מום בגימ' אלקים, והיינו כי ע\"י המצות ממשיכי' יחוד הוי' באלקי', וע\"י הפגם הגם כי עיקר הפגם הוא בנש\"י כמ\"ש שחת לו לא כ\"א בניו מומם, מ\"מ לא נמשך היחוד מבחי' ש' הוי' באלקי' מה שהי' נמשך ע\"י קיום המצוה כו', והתיקון לזה הוא כי אתה נרי שכמו התורה נק' עוז ותושי'<sup data-n=\"4292\">139</sup> שנותנת עוז וכח לנה\"א ותושי' לנה\"ב כמו\"כ מ\"ש כי אתה נרי הוי' הוא כח ועוז לנה\"א, והוי' יגיה חשכי היינו חשך הנה\"ב שלא לבוא לבחי' חטא ופגם ח\"ו, ואם פגם הו\"ע התשובה, ובזה יובן מה שקראן בת, כי בת היא בחי' מקבל, וכמו\"כ מה שנש\"י ממשיכים בחי' יו\"ד ה\"א זהו ע\"י שמקבלים הכח מלמעלה שזהו מ\"ש כי אתה נרי הוי' כו' ולכן קראן בת כנ\"ל. וע\"פ הקבלה היינו כשהמל' מתייחד עם חג\"ת אז היא בחי' בת, משא\"כ מה שלפעמים נק' המל' שדה זהו בחי' יחוד המל' עם נה\"י, וזהו כמ\"ש במרדכי לקחה לו לבת וארז\"ל לבית היינו יחוד המל' עם חג\"ת, אבל לא עם חב\"ד, וזהו מארז\"ל אשתך גוצה שאינה יכולה לקבל מחב\"ד גחין ולחיש לה השפל עצמך להשפיע לה כו'.\nוא\"ו) <b>ולהבין</b> ביאור ענין אחותי שזה משארז\"ל לא זז מחבבה עד שקראה אחותי, הנה אחותי קאי על מארי תורה<sup data-n=\"4293\">140</sup> שתורתן אומנתן<sup data-n=\"4294\">141</sup> שהם הממשיכים דירה בתחתונים גילוי אלקות למטה, וכדי שיהי' גילוי אלקות צ\"ל מתחלה העברת רוח הטומאה וזהו ע\"י דיבור התורה כו', וכמו כאשר מכינים דירה לפני המלך<sup data-n=\"4295\">142</sup> צריכין לנקותה מכל צואה ופסולת, ככה בתורה הוא בחי' כשר פסול טמא טהור, וזהו מ\"ש אמור לחכמה אחותי את<sup data-n=\"4296\">143</sup>, שקאי על בחי' התורה שאחותי הוא כאשר המל' מקבלת מבחי' חכמה, שזהו מ\"ש וגם אמנה אחותי בת אבי היא שכאשר היא בחי' אחותי היא מקבלת מבחי' אבי בחי' חכ', והיינו שענין אחותי היא כאשר ז\"א ומל' הם שוין בקומתן וכמו שארז\"ל לא<sup data-n=\"4297\">144</sup> היא גדולה ממני<sup data-n=\"4298\">145</sup> כו' וזהו תמתי תאומתי<sup data-n=\"4299\">146</sup>.\nועוד יש פי' בתיבת אחותי שהוא",[["4289","137","<b>אשתך גוצא גחין ולחיש לה</b>: ראה ב\"מ נט, א."],["4290","*138","<b>והשפיע</b>: לקמן בסוף הקיצור: להשפיע."],["4291","138","<b>הכח מהנפש החיות</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' שז. אבל במהדורת תש\"ס ס\"ע של: מהנפש הכח והחיות."],["4292","139","<b>התורה נק' עוז ותושי'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו\"א יתרו סז, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541054\" data-slug=\"torat-chaim\" data-id=\"2300541054\">תו\"ח בשלח ח\"א קפד, א</a>. וש\"נ."],["4293","140","<b>מארי תורה</b>: לשון הזהר רע\"מ משפטים קיט, ב. ועוד."],["4294","141","<b>אומנתן</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171305\" data-slug=\"likkutei-sichot\" data-id=\"1300171305\">לקו\"ש בהר כרך יז ע' 305</a> הערה 22."],["4295","142","<b>כאשר מכינים דירה לפני המלך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380809\" data-slug=\"likkutei-torah\" data-id=\"4001380809\">לקו\"ת פ' ראה כג, ב</a>."],["4296","143","<b>אמור לחכמה אחותי את</b>: משלי ז, ד (צויין בפיסקא הבאה בפנים). ראה גם שע\"ת טו, ג. אוה\"ת חנוכה כאן ע' שיז."],["4297","144","<b>לא</b>: בסה\"מ תרכ\"ז כאן ע' שכז: כביכול לא אני גדול ממנה ולא."],["4298","145","<b>לא היא גדולה ממני</b>: ראה שהש\"ר פ\"ה, ב (ב)."],["4299","146","<b>תמתי תאומתי</b>: ראה זהר אד\"ז האזינו רצו, א. שהש\"ר שם."]]],[2001910423,"ל' איחוי<sup data-n=\"4300\">147</sup> וחיבור, והיינו שזהו כמ\"ש ותתצב אחותו מרחוק<sup data-n=\"4301\">148</sup> וארז\"ל בסוטה די\"א ע\"א כל הפסוק הזה ע\"ש שכינה נאמרה, אחותי<sup data-n=\"4302\">149</sup> דכתי' אמור לחכ' אחותי את (משלי ז' ד'), מרחוק דכתי' מרחוק הוי' נראה לי (ירמי' ל\"א)<sup data-n=\"4303\">150</sup>, והיינו כי הגם דכתי' אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"4304\">151</sup>, אבל מ\"מ ע\"י התורה היא בחי' מרחוק ה' נראה לי שע\"י התורה מושג כו', לדעה<sup data-n=\"4305\">152</sup> דכתיב כי אל דעות הוי'<sup data-n=\"4306\">153</sup>, והיינו שהוא חיבור ב' הדיעות, ד\"ת וד\"ע, וזהו בחי' אחותי.\n<b>אבל</b> בחי' אמי הוא יותר נעלה שהיא כאשר המל' נעשה בחי' משפיע, וזהו שארז\"ל ביבמות דק\"ט ע\"ב כל האומר אין לי אלא תורה אפי' תורה אין לו, והיינו שצ\"ל תורה וגמ\"ח<sup data-n=\"4307\">154</sup> דוקא, כי גמ\"ח הוא בחי' מעשה, וגם אמרו אין התורה מתקיימת<sup data-n=\"4308\">155</sup> אלא במי שממית עצמו עליה, פי' ממית עצמו הוא בחי' המס\"נ בק\"ש, וזהו מי יתנך כאח לי<sup data-n=\"4309\">156</sup> שהמי הוא בחי' המס\"נ הוא הוא הנותן להיות כאח לי בחי' דירה בתחתונים, ולכן אפי' מי שתורתו אומנתו מפסיק לק\"ש<sup data-n=\"4310\">157</sup>, ונמצא כי יש ג' בחי' בתי אחותי אמי, בת הוא כאשר המל' היא עדיין בחי' מקבל מבחי' ז\"א, ואחותי היא כאשר המל' נעשה שוה בקומתן, ואמי היא כאשר המל' עולה במדריגת הבינה להיות ממנה נעשה כתר ועטרה לז\"א שזהו בעטרה שעטרה לו אמו.\n<b>והנה</b> לע\"ל כתי' רני ושמחי בת ציון כי הנני בא ושכנתי בתוכך דוקא בבחי' בת דוקא, והענין דהנה לע\"ל תתעלה בחי' מל' שלע\"ל יהי' מעשה גדול<sup data-n=\"4311\">158</sup> וכמו שבירושלמי פ\"ק דשבת סוף הלכה ב' מפרשי' שרשב\"י לא הי' מפסיק<sup data-n=\"4312\">159</sup> גם לק\"ש,",[["4300","147","<b>אחותי שהוא ל' איחוי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770135\" data-slug=\"or-hatorah-hb\" data-id=\"8316770135\">אוה\"ת שה\"ש כרך ב ע' תקא</a>. ע' תקיג."],["4301","148","<b>ותתצב אחותו מרחוק</b>: שמות ב, ד."],["4302","149","<b>אחותי</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. בכתוב ובסוטה שם: אחותו. וכ\"ה לקמן בהקיצור כאן."],["4303","150","<b>מרחוק הוי' . . (ירמי' לא)</b>: פסוק ב."],["4304","151","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["4305","152","<b>לדעה</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. בכתוב ובסוטה שם: לדעת."],["4306","153","<b>כי אל דעות הוי'</b>: שמואל-א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11."],["4307","154","<b>ביבמות . . כל האומר . . וגמ\"ח</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ספ\"ג ובהנסמן שם."],["4308","155","<b>אין התורה מתקיימת</b>: ראה שבת פג, סע\"ב."],["4309","156","<b>מי יתנך כאח לי</b>: שה\"ש ח, א."],["4310","157","<b>מי שתורתו אומנתו מפסיק לק\"ש</b>: שבת יא, א. ראה גם שה\"א עח, ב ובהערה 32."],["4311","158","<b>שלע\"ל יהי' מעשה גדול</b>: ראה מאמרי אדה\"ז תקס\"ז ע' שטז וע' שיז."],["4312","159","<b>שבירושלמי . . שרשב\"י לא הי' מפסיק</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תשפז בהערה."]]],[2001910424,"לפי שזה חידוד וזה חידוד<sup data-n=\"4313\">160</sup> ע\"ש, ואעפ\"כ למצות מעשיות כמצות סוכה ולולב הי' מפסיק, והיינו שהוא ע\"ד כמו שלע\"ל יתעלה בחי' המעשה, והוא ע\"ד מ\"ש ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"4314\">161</sup>, שקודם החטא הי' דירת אדה\"ר בג\"ע שעכשיו הוא תשלום שכר, וכמו\"כ לע\"ל שיתעלה בחי' המעשה יהי' ג\"כ ע\"ד כמו קודם החטא<sup data-n=\"4315\">162</sup> ויותר מזה<sup data-n=\"4316\">163</sup> כו', וזהו משארז\"ל בת הי' לאברהם ובכל שמה<sup data-n=\"4317\">164</sup>, ופי' רש\"י בכל שלא חסר לו כל טוב<sup data-n=\"4318\">165</sup>, פי' כי האבות הם השלשה שהטעימן הקב\"ה מעין עוה\"ב<sup data-n=\"4319\">166</sup>, והיינו שלא חסר אצלו כל טוב, פי' כי לע\"ל יהי' כולו הטוב והמטיב<sup data-n=\"4320\">167</sup>, כי עכשיו לא כמו שמברך על הרעה מברך על הטובה שעל הטובה מברך הטוב והמטיב ועל הרעה מברך דיין האמת, אבל לע\"ל יהי' כולו הטוב והמטיב, וזהו שלע\"ל יהי' נק' כמו שנכתב<sup data-n=\"4321\">168</sup>, וכמו\"כ פי' בת הי' לאברהם ובכל שמה שהטעימו מעין עוה\"ב שלא חסר לו כל טוב שהי' הכל הטוב והמטיב, וכמו\"כ לע\"ל שיתעלה בחי' בת להיות בחי' כתר ועטרה לז\"א, וזהו יותר מבחי' אמי כי פי' אמי הוא בעטרה שעטרה לו אמו שע\"י בחי' אמו נמשך עטרה לז\"א, אבל לע\"ל כשיתעלה בחי' בת תהי' א\"ח עט\"ב<sup data-n=\"4322\">169</sup>, שבחי' המל' עצמה תהי' בחי' עטרה כו', וזהו משארז\"ל כסא דמלכא משיחא מחזיק רכ\"א לוגין גימ' ארך<sup data-n=\"4323\">170</sup>, שעכשיו המל' הוא בחי' כוס<sup data-n=\"4324\">171</sup> אבל לע\"ל תהי' בחי' א\"א כו'. וזהו רני ושמחי בת, פי' רני הוא שמחה שמתוך עצבות כמ\"ש קומי רוני בלילה<sup data-n=\"4325\">172</sup>, שזהו מחמת עצבות והיינו שעכשיו מדת המל' היא פעם כך ופעם כך שיש ך\"ח עתים<sup data-n=\"4326\">173</sup> י\"ד לטובה וי\"ד בהיפוך, אבל לע\"ל שיהי' כולו הטוב והמטיב יהי' בחי' רינה ושמחה כו'.\n<b>ועוי\"ל</b> ענין עליית המל' בא\"א, כי הנה יש עבד ובן ועבד, פי' עבד הוא בחי' מל'<sup data-n=\"4327\">174</sup> דוד עבדי<sup data-n=\"4328\">175</sup>, ובן הוא בחי' אהבה<sup data-n=\"4329\">176</sup> בחי' ז\"א ויש בחי' אה\"ר בחי'",[["4313","160","<b>שזה חידוד וזה חידוד</b>: בירושלמי שם: זה שינון וזה שינון."],["4314","161","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["4315","162","<b>לע\"ל . . כמו קודם החטא</b>: ראה גם שע\"ת ח, א. בהערה הבאה."],["4316","163","<b>לע\"ל . . ויותר מזה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540665\" data-slug=\"torat-chaim\" data-id=\"2300540665\">תו\"ח בשלח ח\"א קנו, ג</a>. וש\"נ. סה\"מ תרל\"ה ח\"א ע' רסו."],["4317","164","<b>בת הי' לאברהם ובכל שמה</b>: ב\"ב טז, ב. ראה (ובהבא בסמוך) אוה\"ת ח\"ש ע' 250 ואילך. חנוכה כאן ע' שיח."],["4318","165","<b>ופי' רש\"י בכל . . טוב</b>: ב\"ב יז, רע\"א ד\"ה בכל [ושם: לא חסרו שום טובה]."],["4319","166","<b>האבות . . שהטעימן . . מעין עוה\"ב</b>: ב\"ב טז, סע\"ב ואילך."],["4320","167","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450658\" data-slug=\"or-hatorah-hb\" data-id=\"8316450658\">לע\"ל</a> . . הטוב והמטיב</b>: ראה פסחים נ, א. אוה\"ת תבוא ע' תתשכח."],["4321","168","<b>שלע\"ל יהי' נק' כמו שנכתב</b>: ראה הערה שלפנ\"ז."],["4322","169","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["4323","170","<b>כסא . . גימ' ארך</b>: ראה יומא עו, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' כג. שע\"ת כב, ג הערה 23. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה בסופו."],["4324","171","<b>המל'. . כוס</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ג מערכת כוס. מאו\"א מערכת כוס אות כא."],["4325","172","<b>קומי רוני בלילה</b>: איכה ב, יט."],["4326","173","<b>ך\"ח עתים</b>: קהלת ג, ב-ח. ראה גם ש\"א ע' 172."],["4327","174","<b>עבד הוא בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פט\"ז מערכת עבד."],["4328","175","<b>דוד עבדי</b>: שמואל-ב ג, יח. ועוד."],["4329","176","<b>ובן . . אהבה</b>: ראה תניא פט\"ז. מאמרי אדה\"א שמות ח\"א ע' נג. וש\"נ."]]],[2001910425,"בינה, ועבד הוא בחי' יראה עילאה בחי' חכ'<sup data-n=\"4330\">177</sup> משה עבדי<sup data-n=\"4331\">178</sup> כו', ולע\"ל יהי' עליות המל' מבחי' דוד עבדי לבחי' משה עבדי כו', וזהו הנה ישכיל עבדי כאשר ישכיל בחי' דוד עבדי שיהי' במדרגת משה עבדי אז יהי' ירום ונשא וגבה מאד<sup data-n=\"4332\">179</sup> ה' עליות, משא\"כ עכשיו הוא רק ג' עליות בתי אחותי אמי אבל לע\"ל ה' עליות כמ\"ש במ\"א<sup data-n=\"4333\">180</sup>.\n<b>קיצור</b> וביאור ענין אחותי, הנה אחותי קאי על בעלי תורה שתורתן אומנתן שממשיכי' דירה בתחתונים, אך כדי שיהי' דירה בתחתונים צריכי' לנקות הדירה מכל לכלוך, וזהו מ\"ש ואת רוח הטומאה<sup data-n=\"4334\">181</sup> כו', והיינו ע\"י דיבור התורה כשר פסול טמא טהור שעי\"ז מנקים הדירה שתהא ראוי' לדירת המלך כו', וזהו מ\"ש (משלי י'<sup data-n=\"4335\">182</sup>) אמור לחכ' אחותי את שקאי על התורה שאחותי היא כאשר מקבלת מבחי' חכ', וזהו כמ\"ש אחותי בת אבי שכאשר נק' אחותי אז מקבלת מבחי' אבי בחי' חכ' כו', והיינו כאשר ז\"א ומל' שוין בקומתן, כמארז\"ל לא היא גדולה ממני כו', וזהו תמתי תאומתי.\n<b>ועוי\"ל</b> אחותי ל' איחוי וחיבור, והיינו כמ\"ש ותתצב אחותו כו', וארז\"ל סוטה די\"א א' כל הפסוק ע\"ש שכינה, אחותו דכתי' אמור לחכ' אחותי, מרחוק דכתי' מרחוק ה' נראה לי, והגם דכתי' אמרתי אחכמה כו' מ\"מ ע\"י התורה מרחוק נראה לי, לדיעה<sup data-n=\"4336\">183</sup> חיבור ב' הדיעות וזהו אחותי, ובחי' אמי זהו<sup data-n=\"4337\">184</sup> כשהמל' נעשה משפיע לז\"א כו', וזהו שארז\"ל כל האומר אין לי אלא תורה אפי' תורה אין לו כ\"א צ\"ל תורה ומעשה דהיינו גמ\"ח וגם ארז\"ל אין התורה מתקיימת אלא במי שממית, פי' היינו המס\"נ בק\"ש, וזהו מי יתנך כאח, שבחי' מי נותן להיות כאח בחי' דירה בתחתונים כו', ולכן גם<sup data-n=\"4338\">185</sup> מי שתורתו אומנתו מפסיק לק\"ש.\n<b>והנה</b> לע\"ל רני ושמחי בת דוקא, דהנה לע\"ל תתעלה בחי' מל' כי יהי' בחי' מעשה גדול, וכמו שבירושלמי דשבת פ\"ק מפרשים שרשב\"י לא הפסיק גם לק\"ש, אבל למצות מעשיות כמו סוכה ולולב הפסיק, והיינו ע\"ד כמו שלע\"ל יתעלה בחי' מעשה כו', וע\"ד ג\"ע שעכשיו הוא קיבול שכר, ולאדה\"ר הי' קיום המעשה שלו בג\"ע, ולע\"ל תתעלה המעשה כמו קודם חטא אדה\"ר ויותר כו', וזהו בת היתה לאברהם ובכל שמה, פי' רש\"י בכל שלא הי' חסר כל טוב, והיינו שהטעימן מעין עוה\"ב שיהי' כולו הטוב והמטיב, כי עכשיו לא כמו שמברך על הטובה כו', אבל",[["4330","177","<b>יראה עילאה בחי' חכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370187\" data-slug=\"torah-or\" data-id=\"3901370187\">מא, ג</a>."],["4331","178","<b>משה עבדי</b>: יהושע א, ב. ז. מלאכי ג, כב."],["4332","179","<b>הנה ישכיל עבדי . . וגבה מאד</b>: ישעי' נב, יג. ראה ביאוה\"ז וישב כג, א. ולהצ\"צ ח\"א שם ע' קכג ואילך. אוה\"ת ישעי' כרך א ע' רסה. סה\"מ תרל\"ה ח\"א ע' רסו."],["4333","180","<b>במ\"א</b>: בסה\"מ תרכ\"ז כאן ע' שכט: במ\"א וד\"ל."],["4334","181","<b>ואת רוח הטומאה</b>: זכרי' יג, ב."],["4335","182","<b>משלי י'</b>: לעיל בפנים כאן פיסקא ועוד יש, מציין: משלי ז' ד'."],["4336","183","<b>לדיעה</b>: ראה לעיל הערה 152."],["4337","184","<b>זהו</b>: בסה\"מ תרכ\"ז כאן ע' שלא ליתא."],["4338","185","<b>גם</b>: כ\"ה גם בסה\"מ תרכ\"ז כת\"י ר\"ש סופר ע' שח."]]],[2001910426,"לע\"ל יהי' כולו הטוב והמטיב, וגם יהי' נק' כמו שנכתב כו', ולכן גם באברהם שהטעימו מעין עוה\"ב ז\"ע שהי' לו בת ובכל שמה היינו בחי' עליית מדריגת בת כמו שהיא בכל שלא חסר כל טוב כו'.\n<b>וזהו</b> רני ושמחי בת דוקא שבחי' בת תתעלה גם למעלה מבחי' אמי כי א\"ח עט\"ב, שזהו יותר מבחי' אמי כי פי' בעטרה שעטרה לו אמו שע\"י אמו נמשך העטרה, אבל פי' א\"ח עט\"ב שבחי' בת בחי' מל' תהי' בעצמה העטרה, וזהו כסא דמלכא משיחא מחזיק רך\"א לוגין בחי' א\"א בחי' כתר, ופי' רני ושמחי שענין הרינה היא שמחה שמתוך עצבות, והיינו שעכשיו המל' היא פעם כך ופעם כך כי יש ך\"ח עתים י\"ד לטובה כו', אבל לע\"ל שיהי' כולו הטוב והמטיב יהי' רני ושמחי כו'.",[]],[2001910427,"<h3>שיר המעלות ממעמקים</h3>\n<b>בס\"ד ש\"ש</b>\n<b>שיר</b> המעלות ממעמקים<sup data-n=\"4339\">1</sup> קראתיך<sup data-n=\"4340\">2</sup> כו', הנה מזמור זה אומרים בעשי\"ת<sup data-n=\"4341\">3</sup> וכנודע שיש עשרה עומקים שבכי\"ו קוראי' וממשיכים עומק אחד<sup data-n=\"4342\">4</sup>, ולכאו' צ\"ל מה\"ע העומקים שצריכים בעשי\"ת להמשיך, ומה נשתנה זמן זה דעשי\"ת שהוא הדין והמשפט על כלליות חיות השנה מהדין ומשפט שאדם נידון בכי\"ו<sup data-n=\"4343\">5</sup>, וכמ\"ש לרגעי' תבחנו<sup data-n=\"4344\">6</sup>, שא\"צ לומר ממעמקי' שאינו מוכרח לעורר בחי' עומק הלב כו', וגם צ\"ל למה צריכים לדין ומשפט בשביל המשכת חיות חדש. אך הענין הוא דכתי' כי אמרתי עולם חסד יבנה<sup data-n=\"4345\">7</sup> שנודע שיש בזה ב' פירושים הא' שהעולם נבנה בחסד, הב' שבכדי שיהי' התהוות העולם צריכים לבנות בחי' מדת החסד, ועכ\"פ איך שיהי' נבנה העולם במדת החסד וכמארז\"ל אמת אמר אל יברא<sup data-n=\"4346\">8</sup>, חסד אמר יברא, ובחי' חסד זה זהו בחי' חפץ חסד<sup data-n=\"4347\">9</sup> היינו בחי' החסד שיש בבחי' חפץ הוי' שהוא מה שעלה",[["4339","1","<b>שיר המעלות ממעמקים</b>: למאמר זה ראה סה\"מ תרכ\"ט ע' שמג ואילך ובהנסמן שם ובריש המאמר שם.\nבהכותרת תיבת ש\"ש ניתוסף ע\"פ בוך 810.\nהמאמר נרשם בגוכתי\"ק."],["4340","2","<b>שיר המעלות ממעמקים קראתיך</b>: תהלים קל, א."],["4341","3","<b>מזמור זה אומרים בעשי\"ת</b>: ראה מג\"א הל' ברכות סנ\"ד, ס\"ב. סידור אדה\"ז במקומו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמא ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתסט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540705\" data-slug=\"torat-chaim\" data-id=\"2300540705\">תו\"ח בשלח רכט, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' שיט. וש\"נ. לקמן פ\"ד."],["4342","4","<b>עשרה עומקים . . עומק א'</b>: ראה ס\"י פ\"א, מ\"ה. פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380874\" data-slug=\"likkutei-torah\" data-id=\"4001380874\">לקו\"ת תצא לט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380932\" data-slug=\"likkutei-torah\" data-id=\"4001380932\">נצבים נג, ב</a>."],["4343","5","<b>שאדם נידון בכי\"ו</b>: ר\"ה טז, א. ראה גם אגה\"ק סכ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380536\" data-slug=\"likkutei-torah\" data-id=\"4001380536\">לקו\"ת קרח נה, ג</a> ואילך. סה\"מ תר\"ם ח\"ב ע' תקמג. וש\"נ."],["4344","6","<b>לרגעי' תבחנו</b>: וכ\"ה לקמן רפ\"ב־ רפ\"ד — איוב ז, יח [ושם: תבחננו — וכ\"ה בבוך 810]."],["4345","7","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 106."],["4346","8","<b>אמת אמר אל יברא</b>: ראה ב\"ר פ\"ח, ה."],["4347","9","<b>חפץ חסד</b>: מיכה ז, יח."]]],[2001910428,"ברצונו מצד בחי' טבע הטוב<sup data-n=\"4348\">10</sup> להטיב<sup data-n=\"4349\">11</sup>, אמנם זה הי' רק בתחלת הבריאה שלא הי' שום דבר שיוכל להיות בחי' אתעדל\"ת<sup data-n=\"4350\">12</sup>, אך עכשיו תלוי בבחי' העלאת מ\"ן<sup data-n=\"4351\">13</sup> ממעשה התחתונים, שאם יש העלאת מ\"ן באתעדל\"ת בבחי' תומ\"צ דשנה העברה, היינו כשאכשור דרא<sup data-n=\"4352\">14</sup> אזי נמשך תוס' אור וחיות מרובה בר\"ה על כלליות השנה החדשה, וכן להיפך ח\"ו כשלא אכשור דרא, ואי לזאת מובן שלצורך המשכות חיות הכללי צריך להיות דין ומשפט דוקא, וז\"ע מה שר\"ה נק' יום הדין<sup data-n=\"4353\">15</sup> שהוא הדין ומשפט על כל אדם בפרט, וכמאמר שכל באי עולם<sup data-n=\"4354\">16</sup> עוברי' לפניך כבני מרון, אם ראוי והגון הוא להמשכת גילוי מלכותו ית', וכן על כל העולם בכלל, ומזה יוכל האדם לעורר בעצמו שיכול להיות שכלליות העולם הוא מחצה על מחצה<sup data-n=\"4355\">17</sup>, ואם יהי' הוא זכאי יכריע את כל העולם לכ\"ז<sup data-n=\"4356\">18</sup>, וע\"ז הוא הדין והמשפט בר\"ה על בחי' ההעלאת מ\"ן דשנה העברה כו', וז\"ע מה שג' ספרים נפתחים בר\"ה<sup data-n=\"4357\">19</sup> צדיקים נכתבים לאלתר לחיים כו', שענין ג' ספרים אלו הוא נגד ג' ספרים שבהם נברה\"ע, כמ\"ש בס\"י בל\"ב נתי' פליאות<sup data-n=\"4358\">20</sup> כו' וברא את עולמו בג' ספרים בספר וספר וסיפור, שהם ג' בחי' חב\"ד<sup data-n=\"4359\">21</sup>, ספר הכותב את הספר הוא בחי' חכמה, וספר בחי' בינה, וסיפור הוא בחי' דעת כמ\"ש מפיו דעת<sup data-n=\"4360\">22</sup>, וזהו כמ\"ש ה' בחכמה יסד ארץ כונן שמי' בתבונה<sup data-n=\"4361\">23</sup> בדעתו תהומות נבקעו<sup data-n=\"4362\">24</sup>, שנמצא כלליות בריאת העולם הוא ע\"י ג' ספרים אלו, ולהיות כן בכל ר\"ה שנמשך חיות כללי מחדש על כלליות השנה נמשך ג\"כ ע\"י בחי' ג' ספרים הנ\"ל, ולכן ג' ספרים נפתחים בר\"ה, ושרש ענין בחי' פתיחת הספרים אלו תלוי בהעלאת מ\"ן דמעשה התחתונים וזהו שצדיקים המקיים<sup data-n=\"4363\">25</sup> תומ\"צ כדבעי למהוי נכתבים לאלתר לחיים, ולהפך כו' והבינונים תלוי' ועומדים על התשובה כו'. דהנה ארז\"ל וכל מעשיך בספר נכתבים<sup data-n=\"4364\">26</sup>, וכתי' ויכתב בספר זכרון לפניו<sup data-n=\"4365\">27</sup>, שענין",[["4348","10","<b>שעלה ברצונו מצד בחי' טבע הטוב</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר ובהערה 66."],["4349","11","<b>טבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["4350","12","<b>בתחלת הבריאה שלא הי' . . אתעדל\"ת</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נצבים מז, ב</a>. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["4351","13","<b>עכשיו תלוי בבחי' העלאת מ\"ן</b>: ראה ע\"ח־ לקו\"ת־ וש\"א שם."],["4352","14","<b>כשאכשור דרא</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["4353","15","<b>שר\"ה נק יום הדין</b>: ראה ר\"ה ח, סע\"א. טז, א-ב."],["4354","16","<b>שכל באי עולם</b>: ראה ר\"ה טז, א במשנה."],["4355","17","<b>העולם הוא מחצה על מחצה</b>: ראה רמב\"ם הל' תשובה פ\"ג, ה\"ד."],["4356","18","<b>לכ\"ז</b>: לכף זכות."],["4357","19","<b>שג' ספרים נפתחים בר\"ה</b>: ראה ר\"ה טז, ב. לקוטי הש\"ס להאריז\"ל לר\"ה שם (ח, ב בדפי הספר). הובא באוה\"ת בראשית כרך ג' ע' 1186. ראה גם שם ע' 1180. האזינו [תבוא] ע' א'תתקטז ואילך. תבוא כרך ו ע' ב'שעו ואילך."],["4358","20","<b>כמ\"ש בס\"י בל\"ב נתי' פליאות</b>: פ\"א, מ\"א."],["4359","21","<b>בספר וספר וסיפור . . חב\"ד</b>: ראה לקוטי הש\"ס להאריז\"ל שם. סידור שחרית לשבת קעט, א. סה\"מ תר\"ם ח\"ב ע' תקצא. וש\"נ."],["4360","22","<b>מפיו דעת</b>: משלי ב, ו."],["4361","23","<b>ה' בחכמה . . בתבונה</b>: משלי ג, יט."],["4362","24","<b>בדעתו תהומות נבקעו</b>: משלי שם, כ."],["4363","25","<b>המקיים</b>: בבוך 810: המקיימים."],["4364","26","<b>וכל מעשיך בספר נכתבים</b>: אבות פ\"ב, מ\"א."],["4365","27","<b>ויכתב בספר זכרון לפניו</b>: מלאכי ג, טז [ושם: ספר]."]]],[2001910429,"שכל מעשיך בספר נכתבים היינו בחי' אותיות כמו שלמטה הכותב עניניו בכתב לזכרון כותב בדיו על הקלף פרטי הדברים שיהי' נרשמים באותיות כו'. ועד\"ז יובן למעלה שענין בחי' הכתיבה בספר ז\"ע ד' אותיות ש' הוי'<sup data-n=\"4366\">28</sup>, כי הדיו הוא בחי' יו\"ד ולכן דיו אותיות יו\"ד, והה\"א הוא בחי' ה' אצבעות היד הכותבי' בספר, והוא\"ו הוא בחי' הקולמס ולכן הוא\"ו בראשו יו\"ד<sup data-n=\"4367\">29</sup> הוא בחי' הדיו הנאחז בקולמס, וה' אחרונה הוא בחי' הקלף הנושא האותיות, וא\"כ פי' וכל מעשיך בספר נכתבים היינו שכל מעשה התחתונים נכתבים ונרשמים בספר העליון הוא בחי' ש' הוי' שהפגם מגיע בש' הוי' וכדכתי' ונוקב ש' הוי'<sup data-n=\"4368\">30</sup>, ובסיום הרבה מן המצות נא' אני הוי'<sup data-n=\"4369\">31</sup>, וכתי' ועבדתם את ה' אלקי'<sup data-n=\"4370\">32</sup> כו', ולכן אומרים בק\"ש שעהמ\"ט<sup data-n=\"4371\">33</sup> אם פגמתי באות יו\"ד כו' וכן בכל האותיות, לפי שהפגם מגיע בש' הוי' כו', וזהו דכתיב זה ספר תולדת אדם<sup data-n=\"4372\">34</sup> שבחי' זה הוא בחי' י\"ב<sup data-n=\"4373\">35</sup> צירופי הוי'<sup data-n=\"4374\">36</sup> הוא בחי' ספר העליון והוא נעשה מתולדת אדם היינו בחי' פעולת האדם אם לטב או למוטב, וע\"ז הוא הדין והמשפט בר\"ה כו', על כל המעשים אשר נכתבים בספר שלפע\"ז נמשך ע\"י בחי' הג' ספרים בחי' המשכת החיות על שנה דלהבא כו'.\nב) <b>ואמנם</b> עדיין אינו מובן הלא אדם נידון בכי\"ו, שהרי בכי\"ו נמשך חיות חדש לחדש הישינות כמאמר ובטובו מחדש בכיו\"ת מע\"ב<sup data-n=\"4375\">37</sup>, שהרי בחי' דבר ה' המחי' ומהוה כל פרטי התהוות הנבראים מוכרח להיות תמיד וכמ\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"4376\">38</sup>, שאם הי' נפסק כרגע הי' נעשה אין ואפס מכל הנברא בשי\"ב כמ\"ש בסש\"ב בש' הבעש\"ט ז\"ל וכ\"ה במדרש<sup data-n=\"4377\">39</sup>, ובאמת בכל עת ובכל רגע נמשך חיות חדש<sup data-n=\"4378\">40</sup> וכדכתי' לרגעי' תבחנו, אלא שבכ\"ע ובכל רגע אינו נראה וניכר כ\"כ, רק בכי\"ו שמאפיל ומאיר והאדם נעשה ברי' חדשה<sup data-n=\"4379\">41</sup>, וכ\"ה בכל הנבראים שזהו כמו",[["4366","28","<b>הכתיבה . . ד' אותיות ש' הוי'</b>: ראה גם אוה\"ת חוקת ע' תו ואילך. שם כרך ה ע' א'תרלד. סה\"מ תרכ\"ט כאן ע' שמג."],["4367","29","<b>הוא\"ו בראשו יו\"ד</b>: ראה גם לעיל מאמר ד\"ה כל אשר חפץ ה' עשה הערה ח."],["4368","30","<b>ונוקב ש' הוי'</b>: אמור כד, טז."],["4369","31","<b>אני הוי'</b>: שמיני יא, מד. מה. ועוד."],["4370","32","<b>ועבדתם את ה' אלקי'</b>: משפטים כג, כה."],["4371","33","<b>ולכן אומרים בק\"ש שעהמ\"ט</b>: נוסח האריז\"ל."],["4372","34","<b>זה ספר תולדת אדם</b>: בראשית ה, א. בבוך 810 כאן ובשורה שלאח\"ז: תולדות."],["4373","35","<b>זה . . י\"ב</b>: ב\"ר פכ\"ד, ה. פס\"ג, ו. שמו\"ר פל\"ח, ח. ויק\"ר פ\"ח, ג."],["4374","36","<b>י\"ב צירופי הוי'</b>: ראה גם שערי אורה [לרי\"ג] שער ה (סה, ב). תניא פמ\"א ובמ\"מ הגהות והע\"ק ולקוטי פירושים (לכ\"ק אדמו\"ר זי\"ע) לשם. סה\"מ תרל\"ה ח\"א ע' קסו ד\"ה בענין. שיחת אחש\"פ תשמ\"ז (הנחה בלתי מוגה) סי\"א (תורת מנחם התוועדויות תשמ\"ז ח\"ג ע' 127). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתב."],["4375","37","<b>ובטובו מחדש בכיו\"ת מע\"ב</b>: ברכת יוצר. ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר על יד הערה 35. סה\"מ תר\"ם ח\"א ע' ה. וש\"נ."],["4376","38","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["4377","39","<b>בסש\"ב בש' הבעש\"ט ז\"ל וכ\"ה במדרש</b>: שער היחוה\"א פ\"א. ראה גם לעיל מאמר ד\"ה וירא ישראל את היד הגדולה פ\"ב. וש\"נ."],["4378","40","<b>בכל עת . . חיות חדש</b>: ראה לעיל הערה 37."],["4379","41","<b>בכי\"ו . . והאדם נעשה ברי' חדשה</b>: ראה גם סה\"מ תרל\"א ח\"א ס\"ע לט ואילך. וש\"נ."]]],[2001910430,"ויהי ערב ויהי בקר שהי' בשי\"ב<sup data-n=\"4380\">42</sup>, ומהו ההתחדשות בר\"ה יותר מכמו בכי\"ו עד שר\"ה נק' יום הדין שכל באי עולם עוברין לפניך כבני מרון כו'.\n<b>ויובן</b> בהקדם מארז\"ל למה קדמה שמע לוהא\"ש<sup data-n=\"4381\">43</sup> כדי שיקבלו<sup data-n=\"4382\">*44</sup> עלי' עומ\"ש ואח\"כ יקבל עליו עול מצות, ולכאו' אינו מובן הלא בחי' קבלת עול מצות הוא ג\"כ קבלת עומ\"ש ולמה מחלקים אותם לשני דברים, ויש להקדים לזה מ\"ש והחיות רצוא ושוב, ובפי' והחיות רצו\"ש יש שני פי'<sup data-n=\"4383\">44</sup>, הא' שקאי על חיות הקדש<sup data-n=\"4384\">45</sup> העומדים שעבודתם הוא ברצו\"ש, והב' הוא שהחיות אלקות<sup data-n=\"4385\">46</sup> המחי' ומהוה כל העולמות הוא בבחי' רצו\"ש, וכמ\"ש בס\"י ודברו בהם ברצו\"ש<sup data-n=\"4386\">47</sup>, שבחי' דבר הוי' המהוום הוא בהם ברצו\"ש, ונק' מטי ולא מטי<sup data-n=\"4387\">48</sup>, וזהו דכתי' הלא דברי כאש<sup data-n=\"4388\">49</sup>, פי' שכמו האש מתנענע תמיד בבחי' הסתלקות והתפשטות כן דברי הוא בחי' דבר ה' שלעולם ה' דברך נצב בשמים, וכ\"ה בכל הנבראים הוא בהם כאש דהיינו בבחי' רצו\"ש, אלא לפי שזהו מלמעלמ\"ט לכן נק' בשם מטולמ\"ט שמתחלה הוא ההתפשטות ואח\"כ ההסתלקות<sup data-n=\"4389\">50</sup> וחוזר חלילה כו' כמ\"ש מזה במ\"א. ושרש הענין הוא דהנה המקובלים כינו אותו ית' לקראותו בשם אוא\"ס<sup data-n=\"4390\">51</sup>, וכן הכתוב מכנה אותו לאש כדכתי' כי הוי' אלקיך אש אוכלה הוא<sup data-n=\"4391\">*52</sup> שצ\"ל מה\"ע שכינו אותו ית' בשם אור ואש. אך הענין הוא שאנו רואים שענין בחי' האור כמו אור השמש הנה הוא רק בחי' זיו והארה בלבד מעצם השמש, ואיננו נוגע כלל לעצם בחי' השמש, ולכן לא יפעול שום שינוי בשמש עצמה אם האור מאיר א\"ל, עד\"מ כשיש עננים שמסתירים אור השמש לבלי תאיר אורה לארץ ולדרים עלי' לא יפעול שום שינוי בעצם השמש, וכן כשתאיר אורה לארץ ולדרים עליה ג\"כ לא יהי' מזה שום שינוי בהשמש עצמה,",[["4380","42","<b>ויהי ערב ויהי בקר שהי' בשי\"ב</b>: בראשית א, ה. ח. יג. יט. כג. לא."],["4381","43","<b>למה קדמה שמע לוהא\"ש</b>: ראה ברכות פ\"ב, מ\"ב (יג, א). ראה אוה\"ת תרומה ע' א'שסז ואילך."],["4382","*44","<b>שיקבלו</b>: בבוך 810: שיקבל."],["4383","44","<b>והחיות רצוא ושוב . . שני פי'</b>: יחזקאל א, יד. ראה לקמן פ\"ג. אוה\"ת תרומה ס\"ע א'שנז ואילך. שבועות ס\"ע קלט ואילך — והוא הנחת רנ\"ט<sup data-n=\"e3\">*</sup>. סה\"מ תרכ\"ו ע' קכה ואילך. תרכ\"ז ע' שדמ. וש\"נ. תרכ\"ט ע' רג ואילך."],["4384","45","<b>הא' שקאי על חיות הקדש</b>: ראה יחזקאל שם. חגיגה יג, ב וברש\"י ותוס' שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב."],["4385","46","<b>והב' הוא שהחיות אלקות</b>: ראה גם לעיל מאמר ד\"ה [נקדישך] וביאור הענין ובהערה 64."],["4386","47","<b>וכמ\"ש בס\"י ודברו בהם ברצו\"ש</b>: פ\"א, מ\"ו. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460013\" data-slug=\"or-hatorah-hb\" data-id=\"8316460013\">אוה\"ת יתרו ע' תתכח</a>."],["4387","48","<b>מטי ולא מטי</b>: ראה זהר בראשית טז, ב. נח סה, א. מאמדי אדה\"א שמות ח\"א ע' רפ. וש\"נ. קונטרסים ע' רפו."],["4388","49","<b>הלא דברי כאש</b>: ירמי' כג, כט [בדילוג]."],["4389","50","<b>מטולמ\"ט . . ואח\"כ ההסתלקות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370008\" data-slug=\"torah-or\" data-id=\"3901370008\">תו\"א בראשית ב, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370012\" data-slug=\"torah-or\" data-id=\"3901370012\">ג, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540490\" data-slug=\"torat-chaim\" data-id=\"2300540490\">תו\"ח וארא ח\"א סג, ד</a>. וש\"נ."],["4390","51","<b>המקובלים כינו . . אוא\"ס</b>: ראה הנסמן בסה\"מ תרכ\"ט כאן ע' שמה."],["4391","*52","<b>כי הוי' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["e3","*","ר' נחום טובי' — ראה אודותיו סה\"ש תש\"ה ע' 15. בית רבי ח\"ג פ\"י ע' קכז [ושם: ר' מנחם טובי' מפיראטין חתן ר\"ש פריידעש משקלאוו]. אדמו\"ר הצ\"צ ותנועת ההשכלה קונטרס מח ע' 33 — נדפס גם בספר החקירה להצ\"צ קה\"ת תשס\"ג ע' 456. אוה\"ת ענינים ע' רצג בהערה. מאמרי אדה\"א קונטרסים ע' טו. וראה גם פלח הרמון ויקרא ע' קלט והנרשם לשם בע' תקסה ד\"ה לע\"ע."]]],[2001910431,"והיינו מפני שהאור הוא רק זיו והארה בעלמא, וכן אור וחיות הנפש המחי' את הגוף אינו רק זיו והארה לבד מעצמיות הנפש, שבחי' הארה זו מאיר באברים הכללי' ומשם מתפשט הארתה בכל אבר בפרט, והראי' ממה שמצינו שהסומא מוליד שלם<sup data-n=\"4392\">52</sup>, וכן כל בעל מום שאם<sup data-n=\"4393\">53</sup> היות שהאבר ישנו בגופו ועכ\"ז אינו ממשיך חיות הנפש כמו כל האברים שהם ממשיכים חיות הנפש<sup data-n=\"4394\">54</sup> כמ\"ש במ\"א, ואם הי' הנפש עצמה מחי' הגוף, א\"כ צ\"ל שבבעל מום זה שהאבר אינו ממשיך חיות הנפש להחיותו מוכרח לומר שזהו חסרון בעצמיות נפשו, וא\"כ מאין הוא מוליד שלם, אלא עכצ\"ל שאין החסרון בעצמיות הנפש, והחיות המחי' את הגוף הוא רק הארת הנפש לבד הוא שמחי' הגוף ובו יש חסרון הארת כח אבר זה כו', וענין ההולדה בדומה לו זהו נמשך מעצמיות הנפש<sup data-n=\"4395\">55</sup> כו' כמ\"ש במ\"א, לכן אם היות שבהארת נפשו יש חסרון עכ\"ז מוליד שלם מפני שבעצם נפשו אין שום חסרון כו'. שנמצא מובן שחיות הנפש המחי' את הגוף הוא רק בחי' זיו והארה בלבד ולא מבחי' עצם הנפש, וכן עד\"מ האש שמחמם המתכת או שא\"ד הנה בהמתכת הוא רק הארת האש ולא עצם, ואם היות שהוא חם מאד עד שנכוין בו עכ\"ז זהו רק הארת האש ולא עצם האש. ועפ\"ז יובן מה שדימו אותו ית' לאור ואש, כי כל בחי' המשכות החיות שנמשך מאתו ית' להוות ולהחיות כל העולמות והנבראים שבהם זהו רק בחי' הארה בעלמא שאינו נוגע אל עצמותו כלל, ולכן הוי' אלקיך ה\"ז משל לאש אוכלה שנמשך רק הארה מבחי' האש, והמקובלים פירשו דברי' וקורי' אותו ית' בשם אור שמובן שכל מה שמדברים זהו בבחי' הארה ממנו ית' כו'.\nג) <b>והנה</b> בחי' אור וזיו זה המחי' ומהוה כלליות ההוויות שנתהוו בשי\"ב, אם היות שהוא רק זיו והארה עכ\"ז אינו דומה בחי' הארה זו כמו שהיא כלול בעצמותו וכמארז\"ל בפדר\"א עד שלא נברה\"ע הי' הוא ושמו בלבד<sup data-n=\"4396\">56</sup>, לכמו בחי' הארה זו שירדה להוות התהוות הנבראים כו', שהרי כמו שירדה ה\"ה מקור להתהוות נבראים בע\"ג ותכלית, ולכן בחי' הארה זו היא תמיד בחי' רצו\"ש דהיינו בבחי' מטי ולא מטי, דהיינו שמתפשט להוות ולהחיות ומסתלק למקורה וחוזרת ומתפשטת להוות מפני בחי' רצון הבורא רצה\"ע שעלה ברצונו להטיב כו', שהוא להוות ולהחיות כל העולמות והנבראים ויצורים ונעשים שבהם כו', וה\"ז כמו האש הנאחז בפתילה שעולה תמיד ונאחז שזהו כמו רצו\"ש כי יסוד האש הוא למעלה<sup data-n=\"4397\">57</sup>",[["4392","52","<b>שהסומא מוליד שלם</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תמב. וש\"נ."],["4393","53","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["4394","54","<b>האברים שהם ממשיכים חיות הנפש</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר על יד הערה 45. סה\"מ תרל\"א ח\"א ע' רלח. וש\"נ. תרל\"ח ע' מט. וש\"נ."],["4395","55","<b>ההולדה . . נמשך מעצמיות הנפש</b>: ראה גם אגה\"ק ד\"ה להבין מ\"ש בפע\"ח (תניא קנז, א). ביאוה\"ז בראשית ב, ב (ולהצ\"צ כרך ב' ע' תריג וע' תרטז). נח, ה, ד. בלק צט, א. סה\"מ תרל\"ח ס\"ע כא. וש\"נ. פלח הרמון פסח ס\"ע מא ואילך."],["4396","56","<b>בפדר\"א עד שלא . . ושמו בלבד</b>: ראה שם פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540053\" data-slug=\"torat-chaim\" data-id=\"2300540053\">תו\"ח וארא ח\"א נג, ב</a> הערה 6."],["4397","57","<b>יסוד האש הוא למעלה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ג, ה\"י."]]],[2001910432,"מיסוד המים והעפר, שטבע המים והעפר לירד למטה<sup data-n=\"4398\">58</sup>, משא\"כ האש טבעו לעלות למעלה, והיינו שרוצה לעלות ולהסתלק למעלה לבחי' האש היסודי<sup data-n=\"4399\">59</sup> זולת מה שהפתילה או העצים שהאש נאחז בהם אינו מניח את האש להסתלק ממנו לגמרי לכן דולק ברצו\"ש הסתלקות והתפשטות, ועד\"ז יובן למעלה שהחיות אלקי המחי' ומהוה הנבראים ה\"ה בבחי' מטול\"מ מפני שרוצה תמיד ליכלל במקורו ומוכרח להתפשט בדרך ירידה להוות ולהחיות הנבראים מפני בחי' רצה\"ע כנ\"ל, ומפני כי החיות היא ברצו\"ש לכן גם עבודת הנבראים הוא ג\"כ ברצו\"ש, וזהו דכתי' והחיות רצו\"ש כפי' הא' שקאי על חיות המרכבה שהם ברצו\"ש מפני כי קבלת חיותם הוא ג\"כ ברצו\"ש כו', וזהו בד\"פ בין בשרפים בין באופנים, ובד\"כ<sup data-n=\"4400\">60</sup> השרפים הם בחי' רצוא שהשרפים אומרים קדוש<sup data-n=\"4401\">61</sup> להיות כי הם משיגים איך שהוא ית' קדוש ומובדל מגדר עולמות ולכן עומדים בבחי' רצוא ותשוקה לכלל ולבטל בו ית', ונק' שרפים ע\"ש שכבר נשרפו<sup data-n=\"4402\">62</sup> בעוצם רשפי אש התשוקה כו' כמ\"ש במ\"א, והאופנים אומרים ברוך<sup data-n=\"4403\">63</sup> שהוא בחי' המשכת החיות שיומשך בחי' כבוד הוי' הוא בחי' זיו יקרי'<sup data-n=\"4404\">64</sup> להוות ולהחיות העולמות שזהו בחי' שוב, ועד\"ז יובן העבודה בנש\"י ג\"כ שהוא בבחי' רצו\"ש, שז\"ע קבלת עומ\"ש ועומ\"צ, שפ' ראשונה הוא בחי' רצוא למס\"נ באחד<sup data-n=\"4405\">65</sup> ע\"י התבוננות איך שאני הוי' לא שניתי<sup data-n=\"4406\">66</sup> כמ\"ש במ\"א ולכן ועמך לא חפצתי<sup data-n=\"4407\">67</sup>, אפי' בחי' כי עמך מקו\"ח<sup data-n=\"4408\">68</sup> שהוא רק עמך כו', רק מפני שא\"א להיות כל היום בבחי' רצוא, לזה הו\"ע קבלת עומ\"צ שהוא בחי' שוב להמשיך המשכות אוא\"ס בכלים מכלים שונים כו', וקדמה שמע הוא כמו קדימת הרצוא להשוב כו'.\nד) <b>והנה</b> כ\"ז הוא בכי\"ו שסדר העבודה הוא ברצו\"ש מפני כי החיות הוא ג\"כ ברצו\"ש, ולפי ערך בחי' רצו\"ש שלו לפ\"ע זה נמשך בחי' רצו\"ש המחייהו ומהווהו, וע\"ז הוא שאמרו אדם נידון בכי\"ו וכמ\"ש לרגעים תבחנו, אך הנה בר\"ה ועשי\"ת שצריכים להמשיך חיות כללי על כלליות שנה החדשה, אינו די בבחי' רצו\"ש שהוא בחי' קעומ\"ש וקבעמ\"צ כמו בכל השנה, אלא שצ\"ל בחי' הקבעמ\"ש בבחי' עומקא דליבא. וזהו הטעם מה שבעשי\"ת אומרים השיר ממעמקים",[["4398","58","<b>שטבע המים והעפר לירד למטה</b>: ראה שם פ\"ד, ה\"ב."],["4399","59","<b>שרוצה לעלות . . האש היסודי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא רפי\"ט</a>. מאמרי אדה\"ז תקס\"ט ע' רכו ואילך. המשך מים רבים תרל\"ו פק\"ה."],["4400","60","<b>בד\"פ . . ובד\"כ</b>: כ\"ה בגוכתי\"ק."],["4401","61","<b>שהשרפים אומרים קדוש</b>: ישעי' ו, ב-ג. ראה בסמוך הערה 63."],["4402","62","<b>שרפים ע\"ש שכבר נשרפו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380423\" data-slug=\"likkutei-torah\" data-id=\"4001380423\">לקו\"ת נשא כח, ד</a>. סה\"מ תרל\"ח ע' טז. וש\"נ. תר\"ם ח\"א ע' מ."],["4403","63","<b>והאופנים אומרים ברוך</b>: יחזקאל ג, יב. ראה חולין צא, ב ואילך. ובתוד\"ה ברוך שם צב, רע\"א. ראה גם סה\"מ תרל\"ד ע' רנד."],["4404","64","<b>כבוד הוי' . . זיו יקרי'</b>: תרגום יונתן משפטים כד, יז."],["4405","65","<b>למס\"נ באחד</b>: ואתחנן ו, ד. ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["4406","66","<b>שאני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["4407","67","<b>ועמך לא חפצתי</b>: תהלים עג, כה."],["4408","68","<b>כי עמך מקו\"ח</b>: תהלים לו, י."]]],[2001910433,"קראתיך הוי', שע\"י בחי' העומקא דליבא שמתעורר בזמן ההוא בעבודת האדם עי\"ז קראתיך הוי' מחדש להוות ולהחיות ולהיות ה' מלך גיאות לבש<sup data-n=\"4409\">69</sup> כו' שיתלבש בלבוש מל' להיות מלך על עמו כו' וכמ\"ש מלוך על כל העולם כולו<sup data-n=\"4410\">70</sup> כו', גלה כבוד מל' עלינו<sup data-n=\"4411\">71</sup>. וענין בחי' עומקא דליבא ז\"ע התשובה, כי ענין ובחי' התשובה אינה דוקא על עבירות<sup data-n=\"4412\">72</sup>, כ\"א שענין התשובה הוא להשיב נפשו לשרשה ומקורה כמ\"ש והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"4413\">73</sup> היינו לבחי' נשמה שנתת בי כמו שהיא טהורה היא<sup data-n=\"4414\">74</sup> בבחי' טהיר\"ע<sup data-n=\"4415\">75</sup> כו', והיינו ע\"י שיתבונן איך שהוא רחוק בתכלית מהוי' אחד, עי\"ז יהי' בבחי' רצוא ותשוקה להשיב נפשו למקורה כו'. וזהו דכתי' לבך יהגה אימה אי' סופר ואי' שוקל<sup data-n=\"4416\">76</sup>, פי' ע\"י שיתבונן שבחי' אי' הוא מ\"ש אי' מקום כבודו<sup data-n=\"4417\">77</sup> שאינו מושג, אי' רומז על ג' ראשונות<sup data-n=\"4418\">78</sup> כמ\"ש כלולים בבחי' הכתר, שהאל\"ף הוא בחי' כתר<sup data-n=\"4419\">79</sup> והיו\"ד ה' הוא מ\"ש והחכ' מאין תמצא<sup data-n=\"4420\">80</sup> והבינה כלול<sup data-n=\"4421\">*81</sup> בו ג\"כ כמ\"ש בס\"י הבן בחכ'<sup data-n=\"4422\">81</sup>, ופי' אי' סופר כו' שבחי' אי' בעצמו הוא השוקל והסופר<sup data-n=\"4423\">82</sup> כל מדידות באבי\"ע, וא\"כ עי\"ז לבך יהגה אימה ופחד להשיב נפשו למקורה ושרשה בבחי' תשו\"ת ותשו\"ע, גם אם לא חטא על הנפש כו' וכ\"ש כשיודע בעצמו שפגם באיזה דבר הן בבחי' סור מרע, והן בבחי' ועשה טוב כו' שצריך לשוב ע\"ז מעומקא דליבא, ולצעוק אל ה' מעומקא דליבא, וז\"ע השופר גנוחי גניח וילולי יליל<sup data-n=\"4424\">83</sup>, והתקיעה בקול פשוט<sup data-n=\"4425\">84</sup> מעומקא שלמעלה מהברת האותיות כו', וע\"י התשובה שהיא עזיבת החטא והחרטה<sup data-n=\"4426\">85</sup> על העבר עי\"ז עוקר את הדבר מעיקרו,",[["4409","69","<b>ה' מלך גיאות לבש</b>: תהלים צג, א. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370408\" data-slug=\"torah-or\" data-id=\"3901370408\">תו\"א מג\"א צ, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540372\" data-slug=\"torat-chaim\" data-id=\"2300540372\">תו\"ח וארא ח\"א עה, א</a> ואילך. וש\"נ."],["4410","70","<b>מלוך על כל העולם כולו</b>: תפלת העמידה לר\"ה. ראה סדר תפלות כל השנה — הברכות האמצעיות — ברמב\"ם סוף חלק אהבה. וכ\"ה בכמה סידורי אשכנז־ ספרד־ אר\"י."],["4411","71","<b>גלה כבוד מל' עלינו</b>: מוסף ליו\"ט וימים נוראים."],["4412","72","<b>התשובה אינה דוקא על עבירות</b>: ראה חובת הלבבות שער עבודת אלקים פ\"ג (ד\"ה והחמישי כי מצות). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370205\" data-slug=\"torah-or\" data-id=\"3901370205\">תו\"א ויחי מה, א</a>. לעיל מאמר ד\"ה כתר יתנו לך פ\"ב. סה\"מ תר\"ם ח\"ב ע' תקכט. וש\"נ."],["4413","73","<b>והרוח תשוב . . נתנה</b>: קהלת יב, ז."],["4414","74","<b>נשמה שנתת בי . . טהורה היא</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["4415","75","<b>טהורה היא . . טהיר\"ע</b>: ראה מאמרי אדה\"א דברים ח\"ב ס\"ע תנח ואילך. שע\"ת ל, ב ובהערה 17 . סה\"מ תרל\"ח ע' ערה. וש\"נ."],["4416","76","<b>לבך יהגה אימה אי' סופר ואי' שוקל</b>: ישעי' לג, יח [ושם: אי']."],["4417","77","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["4418","78","<b>אי' רומז על ג' ראשונות</b>: ראה ע\"מ מאמר חקור דין ח\"א רפכ\"ד וביד יהודה שם — הובא באוה\"ת (יהל אור) תהלים מב, ד (ע' קסה). לקו\"ת הוספה לפ' בהעלותך צו, ד. מאו\"א מערכת אי' סכ\"ב — הובא באוה\"ת (יהל אור) תהלים קמו, א (ע' תקסב). לקו\"ת פקודי ה, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370235\" data-slug=\"torah-or\" data-id=\"3901370235\">תו\"א שמות נב, ג</a>."],["4419","79","<b>שהאל\"ף . . כתר</b>: ראה ת\"ז תמ\"ט. מאמרי אדה\"א ויקרא ח\"ב ע' תרסא. וש\"נ."],["4420","80","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["4421","*81","<b>כלול</b>: בבוך 810: כלולה."],["4422","81","<b>כמ\"ש בס\"י הבן בחכ'</b>: פ\"א, מ\"ד."],["4423","82","<b>אי' בעצמו הוא השוקל והסופר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370235\" data-slug=\"torah-or\" data-id=\"3901370235\">תו\"א שמות נב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370238\" data-slug=\"torah-or\" data-id=\"3901370238\">נג, ב</a>."],["4424","83","<b>גנוחי גניח וילולי יליל</b>: ר\"ה לג, ב. לד, א."],["4425","84","<b>והתקיעה בקול פשוט</b>: שו\"ע אדה\"ז הל' ר\"ה סתק\"צ, ס\"א. ראה גם סה\"מ תר\"ם ח\"ב ע' תקמד. וש\"נ."],["4426","85","<b>התשובה . . עזיבת החטא והחרטה</b>: ראה אגה\"ת פ\"א ובליקוט פירושים לשם. אוה\"ת ש\"ש ע' ב'תקה ואילך."]]],[2001910434,"כמו בהתרת נדרים שע\"י החרטה עוקר את הנדר, וענין התשובה היא להשיב נפשו כנ\"ל שעי\"ז מעלה היצה\"ר לשרשו שהוא טוב כי אין רע יורד מלמעלה<sup data-n=\"4427\">86</sup>, והוא רק כח המתאוה והוא בפשעו צייר בו ציור רע כמ\"ש מזה במ\"א בד\"ה זאת חוקת התורה שלא נדפס<sup data-n=\"4428\">87</sup>, ולכן ארז\"ל שט' ופנינה לש\"ש נתכוונו, כי בשרשם הם גבורות קדושות, וע' בלק\"ת<sup data-n=\"4429\">88</sup> בדרושי פרה אדומה. ובזה יובן איך מעביר את הקטיגור שנולד ע\"י העבירה כמארז\"ל העובר עבירה א'<sup data-n=\"4430\">89</sup> קונה לו קטיגר א', אלא שע\"י החרטה עוקרו מעיקרא וע\"י העלאת נפשו לשרשו נעשה טוב גמור ולכן תלוי איך התשו' הוא שיש שזדונות נעשו רק כשגגות לבד, ואם התשו' היא יותר מעולה אזי נעשו לו כזכיות<sup data-n=\"4431\">90</sup>, ולכאו' איך הוא זה, אלא לפי שמעליהו לשרשו ששם הוא גבורות קדושות ובגבורה יש יתרון המעלה כמעלת הזהב על הכסף, והוא בחי' תגבורת החיות<sup data-n=\"4432\">91</sup> לאלקות ולכן נעשו לו כזכיות. ולכן אינו דומה זמן דעשי\"ת להדין שבכי\"ו, שבכי\"ו הוא רק ההמשכה מהכלל לפרט, אבל בר\"ה ויוהכ\"פ שהוא הדין על כלליות השנה צריכים לעורר בעצמו בחי' עומק נקודת הלב ועי\"ז נמשך מלמעלה ג\"כ מבחי' עשרה עומקים שהם נגד עשר בחי' הנפש, להיות ממעמקים קראתיך ה' מחדש גם אם פגם ח\"ו, ואפי' מי שלא פגם צריך ג\"כ לקרות מחדש כי בכל שנה צ\"ל נמשך מבחי' היותר גבוה ולכן צ\"ל ממעמקים קראתיך ה' מחדש, ולכן תיקנו בעשי\"ת לומר מזמור זה כו'.",[["4427","86","<b>אין רע יורד מלמעלה</b>: ראה ב\"ר פנ\"א, ג. ספר ארבע מאות שקל כסף בסופו (רפב, א). של\"ה מאמר החמישי נג, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסו ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540169\" data-slug=\"torat-chaim\" data-id=\"2300540169\">תו\"ח וארא ח\"א נח, ד</a> הערה 29."],["4428","87","<b>בד\"ה זאת חוקת התורה שלא נדפס</b>: סה\"מ תרכ\"ט ע' קא ואילך. וש\"נ. ראה גם סה\"מ תרל\"ח ע' קסג. וש\"נ."],["4429","88","<b>שט' ופנינה לש\"ש . . בלק\"ת</b>: ב\"ב טז, א. ראה לקו\"ת חוקת סב, א. מאמרי אדה\"ז אתהלך לאזניא ע' קנה. אוה\"ת ויצא כרך ה תתמה, א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670327\" data-slug=\"torat-chaim\" data-id=\"2300670327\">תו\"ח נח נא, א</a> ובהערה 6. שער היחוד בסופו."],["4430","89","<b>העובר עבירה א'</b>: ראה אבות פ\"ד, מי\"א."],["4431","90","<b>שזדונות . . כשגגות . . כזכיות</b>: יומא פו, ב."],["4432","91","<b>ובגבורה . . תגבורת החיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. לעיל מאמר ד\"ה ובירך את לחמך ובהערה 88."]]],[2001910435,"<h3>ושאבתם מים בששון</h3>\n<b>בס\"ד חגה\"ס תרמ\"ב</b>\n<b>ושאבתם</b> מים בששון<sup data-n=\"4433\">1</sup> ממעייני הישועה<sup data-n=\"4434\">2</sup> כו' וארז\"ל בירושלמי רפ\"ה דסוכה שהיו שואבים משם רוה\"ק, ולהבין זה למה דווקא ע\"י ניסוך המים<sup data-n=\"4435\">3</sup> היו שואבים רוה\"ק ולא ע\"י היין<sup data-n=\"4436\">4</sup> שבכל השנה, ועוד צ\"ל הטעם למה בחג דוקא ניתוסף מצות ניסוך המים על ניסוך היין, אך באמת מצות ניסוך המים בחג דוקא הוא מחמת שהוא תיכף אחרי יוה\"כ<sup data-n=\"4437\">5</sup>, ושמחת החג נמשך מתוקף העלי' שהי' ביוהכ\"פ, לכן י\"ל מתחלה ענין יוהכ\"פ וממילא יובן מצות שמחת החג ומה שניתוסף בו מצות ניסוך המים כו'. הנה מצינו שיוהכ\"פ נק' שבת שבתון<sup data-n=\"4438\">6</sup>, והיינו כמו שהשבת הוא בחי' עלי' הששה ימים שקדמו איליו שעולים ונכללים ביום השבת שאחריהם בבחי' קודש העליון (כי השבת נק' קודש מלה בגרמה<sup data-n=\"4439\">7</sup> כמ\"ש בזהר, וכדכתי' ושמרתם את השבת כי קדש הוא<sup data-n=\"4440\">8</sup>), כן יוהכ\"פ הוא עליות כל השבתות<sup data-n=\"4441\">9</sup> של כל השנה שקדמו אליו וכולם עולים ונכללים ביוהכ\"פ (שהוא בחי' קדה\"ק כמשי\"ת) ולכן נק' שבת שבתון. ולהבין ענין זה גם להבין מה שלפעמים נא' על יוהכ\"פ שבת שבתון הוא<sup data-n=\"4442\">10</sup> בחי' דכר ולפעמים נא' שבת שבתון היא<sup data-n=\"4443\">11</sup> בחי' נוק'. וילה\"ק מתחלה ענין השבת הנה כתי' זכור את יום השבת לקדשו<sup data-n=\"4444\">12</sup>, ולכאורה אינו מובן מש\"א לקדשו דמשמעו שישראל",[["4433","1","<b>ושאבתם מים בששון</b>: מאמר זה הוא הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ משבת פ' נח קודם התפלה ש' תרי\"א עם תיקונים מכ\"ק אדמו\"ר מהר\"ש.\nהנחת ר' הלל נמצאת גם בבוך 1237 ע' תסו. 1090 ע' שעו. הנרשם ברשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ שנת הנ\"ל ע' פה. ויודפס בע\"ה בסדרת ספריו פלח הרמון. העתק הנחת ר' הלל כפי שהיא נרשמה בבוך זה מתאימה בד\"כ עם ההעתק של בוך 1090 הנ\"ל. בשולי היריעה להלן נרשמו שינויים אחדים מהנחת ר' הלל כפי שהם מופיעים בביכלאך אחרים, ונסמן לקמן באות ה.\nהמאמר נרשם בכת\"י מעתיק עם תיקונים וכו' בגוכתי\"ק.\nהקיצורים (הנמצא לפנינו מתחיל מקיצור ד) נרשמו בגוכתי\"ק בפ\"ע. וסודרו להלן ע\"י המו\"ל בפנים המאמר אחר כל פרק. בפ\"י נרשמו הקיצורים י־ יא־ יב. היינו שבהקיצור פ\"י נחלק לב' פרקים י' וי\"א והקיצור הג' י\"ב הוא הוספה על מה שנמצא בפנים. ואולי קיצורים אלו הם לסידור המאמר באופן אחר, ואולי הי' גם פתיחה אחרת.\nבהכותרת התיבות חגה\"ס תרמ\"ב, ניתוספו ע\"פ בוך 810."],["4434","2","<b>ושאבתם מים בששון ממעייני הישועה</b>: ישעי' יב, ג."],["4435","3","<b>ניסוך המים</b>: סוכה מב, ב. מח, א-ב. רמב\"ם הל' תמידין ומוספין פ\"י, ה\"ו."],["4436","4","<b>ניסוך . . היין</b>: ראה רמב\"ם הל' מעשה הקרבנות פ\"ב. הל' תמידין ומוספין פ\"ו, ה\"ו."],["4437","5","<b>בחג . . תיכף אחרי יוה\"כ</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לט. אוה\"ת יוה\"כ ע' א'תקע. סוכות ע' א'תשכב ואילך. סה\"מ תר\"ם ח\"ב ע' תרכב. וש\"נ. לעיל מאמר ד\"ה ומעתה צ\"ל מפני מה כל הנשמה פ\"ח."],["4438","6","<b>שיוהכ\"פ נק' שבת שבתון</b>: נסמן בסמוך הערות 10-11."],["4439","7","<b>השבת נק' קודש מלה בגרמה</b>: ראה זהר אמור צד, ב."],["4440","8","<b>ושמרתם את השבת כי קדש הוא</b>: תשא לא, יד."],["4441","9","<b>יוהכ\"פ הוא עליות כל השבתות</b>: ראה לקו\"ת יו\"כ ע, ב. לקמן פ\"ט."],["4442","10","<b>שבת שבתון הוא</b>: אמור כג, לב."],["4443","11","<b>שבת שבתון היא</b>: אחרי טז, לא."],["4444","12","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a> ואילך. לעיל מאמר ד\"ה זכור את יום השבת בתחילתו. וש\"נ. ד\"ה במשנה וכו' ר' נהוראי אומר פ\"ג."]]],[2001910436,"ממשיכים תוס' קדושה בשבת ובאמת שבת מקדשא וקיימא<sup data-n=\"4445\">13</sup>, גם להבין מה שא' זכור בקמץ תחת הזיין ולא אמר זכור בשוא<sup data-n=\"4446\">14</sup> (דזכור בשוא אין משמעותו רק ל' ציווי משא\"כ זכור בקמ\"ץ לפעמים הוא לשון ציווי ולפעמים הוא ל' מקור ומשפיע, ולכאו' צ\"ל דהל\"ל בל' דליכא למיטעי בי' כו'). והנה בפ' יתרו כתי' זכור את יום השבת כו', ובמש\"ת בפ' ואתחנן כ' שמור את יום השבת<sup data-n=\"4447\">15</sup>, ואי' במכילתא ע\"ז משל לזאב<sup data-n=\"4448\">16</sup> שהוא טורף מלפניו ומלאחריו כו' כ\"ה ענין השבת זכור הוא מלפניו ושמור הוא מלאחריו, וכבר עמדו המפרשים ע\"ז מהו\"ע המשל שהמשל<sup data-n=\"4449\">17</sup> את השבת לזאב כו'. אך הענין הוא דהנה ארז\"ל במד\"ר<sup data-n=\"4450\">18</sup> ע\"פ ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"4451\">19</sup> מצות שבת מסר לו<sup data-n=\"4452\">20</sup>, ויניחהו<sup data-n=\"4453\">21</sup> כד\"א וינח ביום השביעי<sup data-n=\"4454\">22</sup>, ולעבדה כמד\"א<sup data-n=\"4455\">23</sup> ששת ימים תעבוד<sup data-n=\"4456\">24</sup> כו'<sup data-n=\"4457\">25</sup>, ולשמרה כמד\"א<sup data-n=\"4458\">26</sup> שמור את יום השבת, והנה לכאורה אינו מובן דבשלמא שביתת השבת הוא מצוה אבל ששת ימים תעבוד אינה מצוה כלל<sup data-n=\"4459\">27</sup> ולמה הזכירה במצות שבת שמסר לו כו'. אך כל הנ\"ל יובן בהקדם ענין השבת שהו\"ע מנוחה כמ\"ש כי ששת ימים עשה ה' את השמים כו' וביום השביעי שבת<sup data-n=\"4460\">28</sup> שפירושו הו\"ע מנוחה וכן כתי' וינח ביום השביעי*, ולכאורה אינו מובן איך שייך ענין מנוחה\n\n<i>*)בגוכתי\"ק נרשם: מן שיש עד כמשי\"ת אצ\"ל:</i>\n(שיש שתי שבתות שבת עילאה ושבת תתאה<sup data-n=\"8702\">א</sup> כמארז\"ל אלמלי שמרו ישראל שתי שבתות כהלכתן<sup data-n=\"8703\">ב</sup> כו' והוא מ\"ש אלה תולדות נח נח<sup data-n=\"8704\">ג</sup> כו' ב\"פ נייחא<sup data-n=\"8705\">ד</sup> שהוא שתי שבתות הנ\"ל כמשי\"ת).",[["4445","13","<b>שבת מקדשא וקיימא</b>: ביצה יז, א. ראה גם לקמן פ\"ג. בהערה שלפנ\"ז. סה\"מ תרל\"א ח\"א ע' קנח. וש\"נ."],["4446","14","<b>בשוא</b>: וכ\"ה גם לקמן פ\"ו (ושניהם בכת\"י המעתיק). ראה גם שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460108\" data-slug=\"or-hatorah-hb\" data-id=\"8316460108\">אוה\"ת יתרו ע' תתקכה</a>־ סה\"מ תרכ\"ו ע' א: בשבא. אג\"ק חט\"ז ס\"ע רצו ואילך."],["4447","15","<b>בפ' ואתחנן כ' שמור את יום השבת</b>: ה, יב."],["4448","16","<b>במכילתא ע\"ז משל לזאב</b>: יתרו שם. ראה גם לקמן פ\"ז ואילך. אוה\"ת שם ע' תתקכז. תרכ\"ו שם ע' ג."],["4449","17","<b>שהמשל</b>: בבוך 810: שהמשיל."],["4450","18","<b>ארז\"ל במד\"ר</b>: ב\"ר פט\"ז, ה."],["4451","19","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו. בב\"ר שם הובא רק תיבת ויניחהו."],["4452","20","<b>מצות שבת מסר לו</b>: ראה גם לעיל מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ובהערה 7."],["4453","21","<b>ויניחהו</b>: בב\"ר שם ליתא."],["4454","22","<b>וינח ביום השביעי</b>: יתרו כ, יא."],["4455","23","<b>ולעבדה </b> [ה ובבוך 810: לעבדה]<b> כמד\"א</b>: בב\"ר שם: לעבדה."],["4456","24","<b>ששת ימים תעבוד</b>: יתרו שם, ט. ראה גם סה\"מ תרל\"ב ח\"א ע' ס."],["4457","25","<b>כו'</b>: בב\"ר שם ליתא."],["4458","26","<b>כמד\"א</b>: בב\"ר שם ליתא."],["4459","27","<b>ששת ימים תעבוד אינה מצוה כלל</b>: ראה גם לעיל מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ובהערה 11."],["4460","28","<b>כי ששת ימים עשה . . שבת</b>: תשא לא, יז.\n\n<b>א</b> ) <b>שבת עילאה ושבת תתאה</b>: זהר בהקדמה ה, ב.\n\n<b>ב</b> ) <b>אלמלי . . שתי שבתות כהלכתן</b>: ראה שבת קיח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380258\" data-slug=\"likkutei-torah\" data-id=\"4001380258\">מב, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380263\" data-slug=\"likkutei-torah\" data-id=\"4001380263\">מג, ד</a> ואילך. לעיל מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"ג.\n\n<b>ג</b> ) <b>אלה תולדות נח נח</b>: נח ו, ט.\n\n<b>ד</b> ) <b>ב\"פ נייחא</b>: ראה ב\"ר פ\"ל, ה."]]],[2001910437,"למעלה, דבשלמא למטה באדם העושה מלאכה שבונה בנין או עושה כלי שהמלאכה הוא עמל ויגיעה אצלו מצד שהנפש שלו הוא רוחני' ויורד ומתלבש בדבר גשמי שאינו מערכו כלל לכן העבודה היא יגיעה גדולה גם לגבי הנפש שהיא רוחני, וכ\"ש לגבי גוף הגשמי העובד ועושה כו', לכן אחרי גמר העשי' שמתעלה החיות המלובש במעשה המלאכה לעצמי' הנפש נחשב זה למנוחה אצלו, משא\"כ למעלה שבמאמר ברא הכל<sup data-n=\"4461\">29</sup> ולא שייך בו ענין היגיעה וכדכתי' לא ייעף ולא ייגע<sup data-n=\"4462\">30</sup> כו' וכמארז\"ל לא בעמל ולא ביגיעה ברא<sup data-n=\"4463\">31</sup> הקב\"ה את עולמו כ\"א במאמר כו', וא\"כ לכאו' אינו שייך ענין מנוחה אצלו מן היגיעה כו', אך באמת אין הכוונה בתי' שבת וינפש<sup data-n=\"4464\">32</sup> או וינח ענין המנוחה כפשוטו דוקא רק העלי' מן הירידה הוא קורא בש' שביתה ומנוחה להיות שהוא ע\"ד העלי' מן הירידה באדה\"ת שהוא מנוחה באמת לכן קורא למעלה ג\"כ ענין העלי' מן הירידה ג\"כ בש' שביתה ומנוחה (הגם שלמעלה לא שייך ענין המנוחה כלל, מאחר שלא נתייגע כו').\nב) <b>וביאור</b> ענין העלי' למעלה, הנה כתי' בדבר הוי' שמים נעשו<sup data-n=\"4465\">33</sup> שנמצא ששרשי מקור העולמות הוא מבחי' לבוש הדיבור* שדבורו של הקב\"ה חשיב מעשה<sup data-n=\"4467\">34</sup>, והוא ע\"ד כמו<sup data-n=\"4466\">*34</sup> באדה\"ת שלבושי הדיבור והמעשה נק' לבושי' חיצוני' ע\"ש שהם נמשכים לחוץ מן הנפש בבחי' נפרד, כי ע\"י המעשה בשעה שעושה מתלבש חיות הנפש במעשה הבנין או הכלי ואח\"כ הם נפרדים מאדם העושה נמצא שגם הארת החיות שנתלבשה בהם נבדל ונפרד מן האדם (כידוע שבמעשה שאדם עושה נמשך חיות מעט מזעיר מכח אל הפועל<sup data-n=\"4468\">35</sup>, והראי' מהרה\"מ נ\"ע שהכיר בכלי<sup data-n=\"4469\">36</sup> שמי שעשה אותה הי' סומא בעין א'<sup data-n=\"4470\">37</sup> כו'), וכן הדיבור יורד ג\"כ בבחי' נפרד מן האדם כי הבל הדבור יוצא לחוץ, משא\"כ לבוש המח' באדם מתאחד בעצמי' הנפש ואינו נבדל ממנה לכן אינה מתגלית כלל לזולתו מצד שאינה נמשכת בבחי' נפרד כו', ועד\"ז יובן למעלה שהמשכת התהוות עולמות הנבראים מאין להיות נראים ליש הוא ע\"י דיבור עליון שפועל התגלות השפע לחוץ והיינו שיהי' נראה בבחי' יש ושיסתירו על כח אלקי השופע בהם, והמשכתם הוא למטה עד שמתלבשים בעשי' גשמי', וכח זה נק' בחי' מעשה למעלה כה\"פ בנפעל כו' משא\"כ מח' עליונה הוא",[["4461","29","<b>שבמאמר ברא הכל</b>: אבות רפ\"ה."],["4462","30","<b>לא ייעף ולא ייגע</b>: ישעי' מ, כח. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540787\" data-slug=\"torat-chaim\" data-id=\"2300540787\">תו\"ח בשלח ח\"א ריח, סע\"ד</a> ואילך ובהערה 471. תצוה ח\"ב שכה, ד."],["4463","31","<b>לא בעמל ולא ביגיעה ברא</b>: ראה ב\"ר פ\"ג, ב. פי\"ב, י. סה\"מ תרל\"ב ח\"ב ע' שפז. ע' שפט."],["4464","32","<b>שבת וינפש</b>: תשא לא, יז."],["4465","33","<b>בדבר הוי' שמים נעשו</b>: תהלים לג, ו."],["4467","34","<b>שדבורו . . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח. אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרס\"ח ע' צט."],["4466","*34","<b>הדיבור . . והוא ע\"ד כמו</b>: בכת\"י זה נרשם: הדיבור והו\"ע והוא ע\"ד כמו. כ\"ק אדמו\"ר מהר\"ש מחק התיבות: והו\"ע. ובמקומם הוסיף: שדבורו של הקב\"ה חשיב מעשה. ה: הדיבור והמעשה והוא ע\"ד דוגמא."],["4468","35","<b>מכח אל הפועל</b>: ה: מכח הפועל בנפעל — ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["4469","36","<b>מהרה\"מ נ\"ע שהכיר בכלי</b>: ראה מאמרי אדה\"א נ\"ך ע' קפד: ”כוס של כסף\". וראה בהנסמן שם. לקוטי ביאורים לשער היחוד קסח, ד."],["4470","37","<b>סומא בעין א'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291023\" data-slug=\"likkutei-sichot\" data-id=\"1300291023\">לקו\"ש</a> שבת חזון כרך כט ע' 23. סה\"ש תשמ\"ט ח\"ב ע' 590 בהערה."]]],[2001910438,"בחי' לבוש המתאחד בעצמיות אלקות ואינה נגלית בבחי' יש כו' ולכן המח' הוא למעלה ממקור ההתהוות מאין ליש כו'. והנה אמיתית מקור המהווה מאין ליש הוא בחי' המדות דאצי' (כי ששת ימים<sup data-n=\"4471\">38</sup> כתי' ולא בששת ימים, והיינו שהששת ימים שהם המדות דאצי' בהם עשה את השמים ואת הארץ), וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4472\">39</sup> כו', רק שמעצם המדות לא הי' ההתהוות נראה ליש לכן נתלבשו המדות עליונות<sup data-n=\"4473\">40</sup> במדות<sup data-n=\"4474\">41</sup> המלוכה וכמ\"ש מלכותך מלכ\"ע<sup data-n=\"4475\">42</sup>, וזהו בחי' הדבור עליון דעש\"מ המהוה מציאות התהוות כל הנבראים, אך המח' עליונה הוא בחי' לבוש התגלות חו\"ב עילאין<sup data-n=\"4476\">43</sup> שהם למעלה ממקור ההשתל' מאין ליש ולכן נק' חכים ולא בחכ' ידיעא<sup data-n=\"4477\">44</sup> מבין ולא בבינה ידיעא כו', וכמו באדה\"ת עצם המח' הוא רק כלי אל השכל והשכל הוא התגלות הנפש המגלה לו בעצמו, היינו להשכיל השכלות עמוקות לעצמו ולא לבא בבחי' התגלות לזולתו כי איידי דטריד למיבלע<sup data-n=\"4478\">45</sup> כו'.\nג) <b>ומעתה</b> יובן ענין השבת למעלה שהו\"ע עלי' מן היריד' כנ\"ל, דהנה כל העש\"מ שהם בחי' הדו\"מ הם ירידה לגבי אוא\"ס המתלבש בכלים די\"ס דאצי' וכמ\"ש לאו אורחי' דמלכא לאשתעי במילין דהדיוטא<sup data-n=\"4479\">46</sup> (ובאמת אפי' התלבשות אוא\"ס במדות דאצי' להיות מקור להתהוות מאין ליש הוא ג\"כ ירידה גדולה לגבי אור א\"ס המלובש באו\"א עילאין<sup data-n=\"4480\">47</sup> שלמעלה מבחי' המדות ואפי' מבחי' המוחין השייך למדות הנק' יש\"ס ותבונה<sup data-n=\"4481\">48</sup> כידוע), אך בשבת עולים בחי' לבושי הדבור הנק' מעשה למעלה לבחי' לבוש עצמי' המח' שהוא בחי' לבוש לחו\"ב עילאין כנ\"ל (וכן המדות עולין לבחי' או\"א עילאין והו\"ע עליית הששת ימים ביום השבת שהוא בחי' קדש דח\"ע קדש מלה בגרמי' כו') וממילא עולין כל העולמות ג\"כ לקבל מבחי' עצמיות המח' (ומבחי' עצמיות החו\"ב עילאין כנ\"ל, כי אינו דומה עליות החיות למעלה לגבי עליית החיות למטה באדה\"ת, שלמטה החיות בלבד עולה למקורו והכלי עם החיות מעט המלובש בה נשאר בבחי' נפרד מצד שההתהוות הוא מיש ליש, משא\"כ למעלה שההתהוות הוא מאין ליש לכן אם הי' מסתלק האין המהווהו ליש הי' אין ואפס כמ\"ש בסש\"ב בש' הבעש\"ט ז\"ל ע\"פ לעולם ה' דברך נצב<sup data-n=\"4483\">50</sup>, וכ\"ה במדרש<sup data-n=\"4482\">49</sup>, ולכן ממילא מובן שגם גשם הנבראים מוכרחים לעלות לקבל חיות",[["4471","38","<b>כי ששת ימים</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["4472","39","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["4473","40","<b>המדות עליונות במדת המלוכה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381302\" data-slug=\"likkutei-torah\" data-id=\"4001381302\">לקו\"ת שה\"ש מג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540455\" data-slug=\"torat-chaim\" data-id=\"2300540455\">תו\"ח בא ח\"א ק, ב</a> ובהערה 162."],["4474","41","<b>במדות</b>: בבוך 810: במדת."],["4475","42","<b>מלכותך מלכ\"ע</b>: תהלים קמה, יג."],["4476","43","<b>חו\"ב עילאין</b>: ראה בסמוך הערה 47."],["4477","44","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה יז, ב."],["4478","45","<b>איידי דטריד למיבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["4479","46","<b>לאו אורחי' דמלכא . . דהדיוטא</b>: נסמן לעיל במאמר ד\"ה קדש ישראל לה' פ\"ב הערה 83."],["4480","47","<b>באו\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. פלח הרמון בהר ע' תג. וש\"נ."],["4481","48","<b>יש\"ס </b> [ ישראל סבא]<b> ותבונה</b>: ראה גם שעה\"י קי, ב ובהערה 15. שם קנז, ג ואילך."],["4483","50","<b>לעולם ה' דברך נצב</b>: תהלים קיט, פט."],["4482","49","<b>בסש\"ב בש' הבעש\"ט ז\"ל . . וכ\"ה במדרש</b>: שער היחוה\"א פ\"א. ראה גם לעיל מאמר ד\"ה וירא ישראל את היד הגדולה פ\"ב. וש\"נ."]]],[2001910439,"מהמחשבה כו'). וזהו ממצוא חפציך ודבר דבר<sup data-n=\"4484\">51</sup> דכתי' בשבת ואמרז\"ל דיבור אסור הרהור מותר<sup data-n=\"4485\">52</sup> והיינו מטעם הנ\"ל שלבושי הדבור ומעשה עולין ונכללים בלבושי המח' ביום השבת כנ\"ל וזהו\"ע שבת שנק' בש' שבת בראשית<sup data-n=\"4486\">53</sup>, והיינו מטעם הנ\"ל שלבושי הדבור ומעשה עולין ונכללים בלבושי המח' ביום השבת כנ\"ל וזהו\"ע שבת שנק' בש' שבת בראשית כו' (והיינו מטעם שבו נעשה עליית העולמות והחיות המלובש בהם שהם בחי' לבושי הדיבור ומעשה כו' וגם המדות דאצי' כנ\"ל) שכולם עולים לקבל מבחי' ח\"ע הנק' ראשית<sup data-n=\"4487\">54</sup> כו', וזהו בחי' שבת תתאה שהו\"ע העלי' שנעשה בשבת מלמטה למעלה, ועל בחי' זאת ארז\"ל דשבת מקדשא וקיימא. אך מש\"א לקדשו דמשמע שישראל מוסיפין קדושה בשבת ואיזהו קדושה מוסיפין כו' כיון שהוא קדש מצ\"ע, אך הענין יובן בהקדם מאמר אני ראשון ואני אחרון<sup data-n=\"4488\">55</sup> דבחי' ראשון הוא בחי' אור א\"ס שלמעלה מן החכ' ולכן נק' ראשון, כי ראשית הוא בחי' נוק' והוא בחי' חכ\"ע שהוא בחי' מקבל לגבי למעלה מן החכ' כמ\"ש והחכ' מאין תמצא<sup data-n=\"4490\">57</sup> (הגם שהוא בחי' משפיע לכל מה שלמטה הימנו שהוא כלליות הי\"ס דאצי' ולכן נק' ראשית אליהם כו'), אך בחי' ראשון הוא בחי' דכר<sup data-n=\"4489\">56</sup> והוא בחי' הכתר שלמעלה מן החכ' שהוא בחי' משפיע לגבי ח\"ע ובחי' הכתר נק' קדם<sup data-n=\"4491\">58</sup> שאינו בגדר ראשית ואחרי' (וכמארז\"ל ראשון דמעיקרא משמע<sup data-n=\"4492\">59</sup> כמו הראשון אדם תולד<sup data-n=\"4493\">60</sup> כו'), ולכן א' אני הוא בחי' מל' דא\"ס המתלבש בבחי' ראשון שהוא בחי' הכתר כנ\"ל, הנה בחי' זאת הוא ג\"כ אחרון היינו שנעשה בחי' דכר להשפיע גם במל' הנק' אחרית<sup data-n=\"4494\">61</sup> כי לפניו שוין הח\"ע עם המל' כו' (ומבלעדי אין אלקים באמצעיתא<sup data-n=\"4495\">62</sup> שכל הצמצומי' דהשתל' אינם מסתירים לפניו כלל כו'), וזהו\"ע חותמו של הקב\"ה אמת<sup data-n=\"4496\">63</sup> שהוא בחי' רת\"ס<sup data-n=\"4497\">64</sup>, כי הא' הוא בחי' ראש שהוא בחי' מל' דא\"ס המלובש בח\"ע<sup data-n=\"4498\">*65</sup>, וראש אותיות אשר<sup data-n=\"4499\">65</sup> כמו שאנו אומרים אשר קדשנו במצותיו שהוא בחי' תענוג<sup data-n=\"4500\">66</sup> הפשוט הנמשך",[["4484","51","<b>ממצוא חפציך ודבר דבר</b>: ישעי' נח, יג."],["4485","52","<b>דיבור אסור הרהור מותר</b>: שבת קיג, ריש ע\"ב. ראה אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרכ\"ז ע' קכו ואילך. תרל\"ב ח\"א ע' סב ואילך. וש\"נ."],["4486","53","<b>שבת שנק' בש' שבת בראשית</b>: נדרים עח, א ואילך."],["4487","54","<b>ח\"ע הנק' ראשית</b>: ראה גם לעיל מאמר ד\"ה כי תבואו וכו' ושבתה הארץ ובהערה 48. סה\"מ תר\"ם ח\"א ע' קסב."],["4488","55","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["4490","57","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["4489","56","<b>ראשית . . נוק' . . ראשון . . דכר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370312\" data-slug=\"torah-or\" data-id=\"3901370312\">תו\"א יתרו ע, א</a>. לעיל מאמר ד\"ה אז ישיר משה פ\"ג. סה\"מ תרל\"א ח\"א ע' ו. תר\"ם ח\"א ע' קסב. וש\"נ."],["4491","58","<b>הכתר נק' קדם</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ט מערכת קדם. אור נערב ח\"ז מערכת קדם."],["4492","59","<b>ראשון דמעיקרא משמע</b>: פסחים ה, א."],["4493","60","<b>הראשון אדם תולד</b>: איוב טו, ז."],["4494","61","<b>במל' הנק' אחרית</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"א מערכת אחרית. מגיד משרים וישלח ד\"ה וישלח יעקב. מקץ ד\"ה אור . . כ\"ח לכסליו."],["4495","62","<b>ומבלעדי אין אלקים באמצעיתא</b>: המשך הכתוב אני ראשון — ישעי' מד, ו. ראה ת\"ז ת\"ע קכ, סע\"א. שע\"ת קמו, א ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550308\" data-slug=\"torat-chaim\" data-id=\"2300550308\">תו\"ח תצוה ח\"ב שלא, ג</a>."],["4496","63","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["4497","64","<b>אמת . . רת\"ס</b>: ראה ב\"ר פפ\"א, ב. שעה\"י קלד, א ובהערה 16."],["4498","*65","<b>בח\"ע</b>: ה: בכתר עליון."],["4499","65","<b>וראש אותיות אשר</b>: ראה זהר בראשית טו, סע\"א. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ב. סה\"מ תר\"ם ח\"א ע' קסג. וש\"נ."],["4500","66","<b>אשר קדשנו במצותיו . . תענוג</b>: נוסח ברכת המצות. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370362\" data-slug=\"torah-or\" data-id=\"3901370362\">תו\"א</a> יתרו ע, ריש ע\"ב. שם תצוה פא, א. סה\"מ תר\"ם ח\"א ס\"ע נד. וש\"נ."]]],[2001910440,"מבחי' מל' דא\"ס במצות העליונות (שהם בחי' אורחין דגולגלתא<sup data-n=\"4501\">67</sup> כידוע), והמם הוא בחי' תוך שהוא התלבשותו מבחי' ח\"ע עד המל' (ולא עד בכלל והו\"ע ומבלעדי באמצעיתא כנ\"ל), ותי\"ו הוא בחי' התלבשותו בבחי' המל' שהוא בבחי' אני אחרון המתלבש בבחי' אחרית שהוא המל' כו'.\nד) <b>ומעתה</b> יובן ענין לקדשו הנ\"ל שישראל מוסיפין קדושה בשבת והיינו שממשיכים מבחי' אור א\"ס שלמעלה מן החכמה בחי' תוס' אור בבחי' ח\"ע<sup data-n=\"4502\">*68</sup> כו' (וזהו\"ע דכתי' וקראת לשבת עונג<sup data-n=\"4503\">68</sup> כו'), וזהו שער החצר הפנימי' הפונה קדים יהי' סגור ששת ימי המעשה וביום השבת יפתח<sup data-n=\"4504\">69</sup>, שבשבת נפתח מבחי' קדם שהוא בחי' המל' דא\"ס המלובש בכת\"ע שנק' ראשון ומתגלה בבחי' ח\"ע הנק' יום השבת כו' ובחי' זאת נק' שבת עילאה כו'. אך הנה עדיין צ\"ל איך ממשיכים ישראל, וע\"י מה ממשיכים, תוס' קדושה ביום השבת. והענין הוא שזהו ע\"י ששת ימים תעבוד כו' כי פי' עבודה הוא ל' תיקון<sup data-n=\"4505\">70</sup> והיינו לתקן הששת ימים, וביאור ענין תיקונם הנה ידוע דששת ימים אלו נק' שימ\"ב, והיינו ע\"ש קבלתם מבחי' ח\"ע הנק' ראשית ומאיר בהם בחי' הביטול דח\"ע, אך לאחר חטא עה\"ד נק' ששת ימי החול כי חול הוא מל' חולין והוא מל' אשה זונה וחללה<sup data-n=\"4506\">71</sup>, והיינו מפני שנתפשטו למטה ונתלבשו בנוגה דעשי' כו', כי יש פרסא המבדיל בין קודש לקדש<sup data-n=\"4507\">72</sup> שזהו כל הפרסאות שבמדריגת הקדושה עצמה, אך יש פרסא המבדלת בין קודש לחול שהוא בין בחי' הקדושה לבחי' נוגה לכן כאשר נתלבשו ששת ימים בנוגה נק' ששת ימי החול כו' (כי לאחר חטא עה\"ד נעשה תערובות טו\"ר<sup data-n=\"4508\">73</sup> בעולם ובשנה ובנפש וכולם נתגשמו כו' לכן גם ששת ימים שהם בחי' הזמן נתגשמו ונתערבו טוב ברע לכן נק' ששת ימי החול כו'). והנה התיקון דששת ימים היינו לברר ולהפוך הרע לטוב שעי\"ז יתבררו כל הניצוצות המלובשים בבחי' נוגה דעשי' גשמי' ויתעלו ויוכללו באצי' וזהו נק' חולין שנעשו עטה\"ק<sup data-n=\"4509\">74</sup>, כי הנה באמת יש ג\"כ בחי' אצי' בעשי'<sup data-n=\"4510\">75</sup> ונק' אצי' שבעשי' ולכן אפשר לברר ולהפוך בחי' עשי' הנק' חול באצי' שבו הנק' קודש (וממילא נכלל אח\"כ בעצמי' האצי' כו'). וזהו\"ע ר\"י בן גדגודא<sup data-n=\"4511\">76</sup> שהוא הי' אוכל",[["4501","67","<b>במצות . . אורחין דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). סה\"מ תר\"ם ח\"א ע' נה. וש\"נ."],["4502","*68","<b>אור בבחי' ח\"ע</b>: ה: אורו' בבחי' ח\"ע והיינו המשכת תענוג הפשוט שזהו גילוי אור מל' דא\"ס המלובש בכתר עליון שנק' ראשון וע\"י ישראל הוא נמשך בבחי' חכ\"ע."],["4503","68","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["4504","69","<b>שער החצר . . וביום השבת יפתח</b>: יחזקאל מו, א."],["4505","70","<b>עבודה הוא ל' תיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a>."],["4506","71","<b>אשה זונה וחללה</b>: אמור כא, ז."],["4507","72","<b>פרסא המבדיל בין קודש לקדש</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך יב, סע\"א</a> ואילך."],["4508","73","<b>לאחר חטא עה\"ד . . תערובות טו\"ר</b>: ראה ע\"ח שער הקליפות שמ\"ח, פ\"ג. שע\"ק ח\"א, ש\"א. הערות שמן ששון למאמר פסיעותיו של אאע\"ה [אות מ נדפס גם בס' כתבים חדשים לרח\"ו ע' מ]. מאמרי אדה\"א ויקרא ח\"ב ע' תדש. וש\"נ. הנחות תקע\"ז ע' פג. וש\"נ."],["4509","74","<b>חולין שנעשו עטה\"ק</b>: חגיגה יט, סע\"ב. ראה גם אוה\"ת ברכה כרך ו ע' ב'תקעג."],["4510","75","<b>יש . . אצי' בעשי'</b>: ראה ספר הגלגולים פ\"כ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380317\" data-slug=\"likkutei-torah\" data-id=\"4001380317\">לקו\"ת במדבר ב, ב</a>. סה\"מ תש\"ח ע' 81."],["4511","76","<b>ר\"י בן גדגודא </b> [בבוך 810: גודגדא]<b></b>: ראה חגיגה יח, ב במשנה [ושם: יוחנן . . גודגדא. וכ\"ה באוה\"ת ירמי' ע' שעג. סה\"מ תרכ\"ז ע' רפ. תרכ\"ט ע' קצג. פר\"ת ע' קצד (ושם: במשנה דפ\"ג דחגיגה. וכנצ\"ל: ספ\"ב דחגיגה). תרכ\"ז ע' קנא — ושם: ר' יוחנן]."]]],[2001910441,"חולין שנעשו עטה\"ק כו', כי הנה יש ד' בחי' הא' נק' בש' חול והוא בחי' עשי' שנראה בבחי' יש ונפרד ולכן נק' חול מל' חלל כנ\"ל, והב' נק' מעשר שיש בו בחי' קדושה, כמ\"ש העשירי יהי' קודש<sup data-n=\"4512\">77</sup>, וזהו בחי' יצי' כו', ובחי' הג' נק' בחי' תרומה והוא בבחי' בריאה אשר שם נא' ארוממך אלקי המלך<sup data-n=\"4513\">78</sup> כו' כי המלאכים דבריאה נק' רוממי שדי<sup data-n=\"4514\">79</sup> כו'), אך בחי' הד' נק' קודש שזהו בחי' אצי'<sup data-n=\"4515\">80</sup> שמאיר בו הארת ח\"ע בגילוי עצום הנק' קודש מלה בגרמי', ולכן כ\"א מהתנאים הי' אוכל<sup data-n=\"4516\">81</sup> ומעלה לפי מדריגתו, יש שהי' יכול להעלות הניצוצי' דנוגה דעשי' בבחי' אצי' ממש לכן נק' אוכל חולין שנעשו עטה\"ק, ויש שלא הי' יכול להעלות רק עד עולם הבריאה ונק' אוכל חולין שנעשו על טהרת תרומה כו'. וע\"ד הפשוט יש שהוא אוכל לעבוד את ה' בכח האכילה נמצא שלא נתעלה בשעת מעשה הניצוץ בשעת האכילה ממש, אך אח\"כ בשעת התפילה כשמתפלל באהוי\"ר או לומד לשמה שהתפילה והלימוד הוא בכח האכילה ההוא ממילא נתעלה הניצוץ שבמאכל לבחי' קודש העליון דאצי' וזה אינו נק' אוכל עטה\"ק (רק אפשר נק' אוכל חולין על טהרת תרומה כו'), משא\"כ יש שהוא בתכלית הביטול במחשבתו באוא\"ס בעת האכילה עצמה שאז הוא עליית הניצוץ אלקי שבמאכל בשעת האכילה עצמה לבחי' קודש העליון הנה זהו נק' אוכל חולין על טה\"ק כו'.\n<b>קיצור</b> ד'<sup data-n=\"4517\">82</sup>, אך ע\"י מה ממשיכים תוס' ביוה\"ש זהו ע\"י העבודה בש\"י החול, והענין הוא דכתי' לעשות ות\"י<sup data-n=\"4519\">84</sup> לתקן<sup data-n=\"4518\">83</sup>, ששי\"ב צריכים תיקון, להיות כי נק' בראשית לפי שמקבלים מבחי' חכ' שנק' ראשית, אמנם ע\"י חטא עה\"ד נק' ימי החול, כי יש ב' הבדלות הא' בין קודש לקדש, הב' בין קדש לחול, פי' חול ל' חללה, והיינו לפי שנתפשטו בנוגה, וע\"י חטעה\"ד שנעשה תערובות טו\"ר בעש\"ן, ולכן ששת ימים שהם זמן צריכין תיקון להפך הרע לטוב, וזהו שמצינו בפ\"ב דחגיגה שהתנאים זה הי' אוכל על טה\"ק, וזהו ע\"ט תרומה, והיינו שיש אבי\"ע בכל עולם, א\"כ יש אצי' גם בעשי', ובכלל עשי' חול, יצי' מעשר, בריאה תרומה, אצי' קדש, וכשאוכל עטה\"ק מברר הרע דעשי' שיתהפך להיות טוב בקדש דאצי' דעשי' ואח\"כ עולה לאצי' העליון כו', ויש שלא הי' יכול להעלות כ\"א ע\"ט תרומה דהיינו בריאה לבד, ופי' הענין ע\"פ פשוט כשאוכל כדי שיתחזק שיוכל ללמוד ולהתפלל שבשעת האכילה עדיין אינו מתעלה הניצוץ שבמאכל לבחי' קדש העליון, משא\"כ מי שהוא קשור ודבוק באוא\"ס גם בשעת האכילה הנה הוא מעלה הניצוץ תומ\"י לבחי' קדש העליון כו'.",[["4512","77","<b>העשירי יהי' קודש</b>: בחוקותי כז, לב."],["4513","78","<b>ארוממך אלקי המלך</b>: תהלים קמה, א."],["4514","79","<b>כי </b> [אוצ\"ל: (כי]<b> . . רוממי שדי</b>: ברכת יוצר."],["4515","80","<b>קודש . . אצי'</b>: ראה מ\"ח מס' מקום הקליפות פ\"ב הובא באוה\"ת יתרו ע' תתקל."],["4516","81","<b>כ\"א מהתנאים הי' אוכל</b>: בהקיצור כאן מציין: בפ\"ב דחגיגה."],["4517","82","<b>קיצור ד'</b>: ראה לעיל הערה 1."],["4519","84","<b>ות\"י</b>: תיבה זו איננה ברורה."],["4518","83","<b>לעשות ות\"י לתקן</b>: ראה הנסמן לעיל מאמר ד\"ה במשנה וכו' ר' נהוראי אומר הערה 53."]]],[2001910442,"ה) <b>ועפ\"ז</b> ג\"כ ענין שיחות חולין של ת\"ח צריכים לימוד<sup data-n=\"4520\">85</sup> שנא' ועליהו לא יבול<sup data-n=\"4521\">86</sup> וזהו נא' על ר\"ג כו', הענין הוא ע\"ד שאנו מוצאים בבחי' השערות שנא' שער באשה ערוה<sup data-n=\"4522\">87</sup> ויש שערות שהם בתכלית הקדושה כמו בנזיר דכתי' בי' קדוש יהי' גדל פרע שער ראשו<sup data-n=\"4523\">88</sup> וכן בכהנים<sup data-n=\"4524\">89</sup> כו'. הענין הוא כי שערות הוא בחי' אותיות<sup data-n=\"4525\">90</sup>, והנה צ\"א<sup data-n=\"4526\">91</sup> דע\"מ נק' שער באשה ערוה להיות שנמשכים מבחי' המל' דאצי' הנק' אשה יראת הוי'<sup data-n=\"4527\">92</sup>, והע\"מ מתפשטים למטה מטה עד שנעשה מהם יניקת החיצונים ג\"כ, ולכן בלוים נא' והעבירו תער על כל בשרם<sup data-n=\"4528\">93</sup> כו' בכדי להעביר יניקת החיצונים מהם כו', אך הנזיר הוא מרכבה לבחי' אוא\"ס שלמעלה מבחי' ח\"ע<sup data-n=\"4529\">94</sup> אשר משם לא יוכל להיות המשכת השפע רק ע\"י בחי' שערות ומשם כל קדושה בשערא תלייא<sup data-n=\"4530\">95</sup> כידוע ולכן מוכרח לגדל השער, וכן עד\"ז הכהן הוא מרכבה לבחי' רב חסד דעתיקא<sup data-n=\"4531\">96</sup> כו'. ועד\"ז יובן ג\"כ ענין שיחות חולין של ת\"ח, כי הע\"מ נק' עמל שיחה<sup data-n=\"4532\">97</sup> להיותם בבחי' ירידה והשפלה בבחי' יש נפרד ונק' מילין דהדיוטא כנ\"ל, אך ת\"ח הוא בחי' איתן (ששורש נשמתו הוא באצי' כנז' במאמר ויקח המן<sup data-n=\"4533\">98</sup> כו' ע\"ש) הוא מעלה בחי' שיחה זאת לשרשה בבחי' השערות שלמעלה מן החכ' אשר שם הם",[["4520","85","<b>ועפ\"ז </b> [אוצ\"ל: ועפ\"ז יובן]<b> . . שיחות חולין . . לימוד</b>: ראה סוכה כא, ב. לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי הערה 173."],["4521","86","<b>ועליהו לא יבול</b>: תהלים א, ג."],["4522","87","<b>שער באשה ערוה</b>: ברכות כד, א. ראה לעיל מאמר ד\"ה רני ושמחי ובהערה 79."],["4523","88","<b>קדוש יהי' . . שער ראשו</b>: נשא ו, ה."],["4524","89","<b>וכן בכהנים</b>: ראה גם בסמוך בפנים ובהקיצור. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380531\" data-slug=\"likkutei-torah\" data-id=\"4001380531\">לקו\"ת קרח נד, ב</a>. ביאוה\"ז קרח צד, ב-ג. אמ\"ב צו, ג. תו\"ח ח\"ש קכה, א ובהערות 10-11. הנחות תקע\"ז ע' קנח. דרושי חתונה ח\"ב ע' תקמב (כה\"ג). מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קמח. סה\"מ תרכ\"ז ס\"ע כו (כה\"ג). תרכ\"ט ע' נט. ע' רנו (כה\"ג). תרע\"ח ע' עא ותרצ\"ט ע' 106: ובכהנים (הי') צ\"ל שערות שיכסו ראשן. תרע\"ט ע' תקג. ע' תרלו. פר\"ת ע' קסא: בכהנים כתי' וזקנם<sup data-n=\"e4\">*</sup> לא יגלחו כסום יכסמו ראשיהם<sup data-n=\"e5\">**</sup> שצריכים להיות ראשיהם מכוסה בשערות*<sup data-n=\"e6\">***</sup>.\nראה אוה\"ת שמיני ע' מג הכהן א\"צ כלל לגידול שער הראש . . ומה שהכהן צ\"ל ת\"ד היינו כמו שיש לכל ישראל . . ע\"כ בשערות ראשו אין בו כ\"כ קדושה כ\"א בת\"ד."],["4525","90","<b>שערות הוא בחי' אותיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380631\" data-slug=\"likkutei-torah\" data-id=\"4001380631\">לקו\"ת פינחס עז, ד</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסח. מאמרי אדה\"א ויקרא ח\"ב ע' תקכ."],["4526","91","<b>צ\"א</b>: צירופי אותיות."],["4527","92","<b>המל' . . אשה יראת הוי'</b>: משלי לא, ל. ראה ת\"ז בהקדמה ו, א."],["4528","93","<b>והעבירו תער על כל בשרם</b>: בהעלותך ח, ז."],["4529","94","<b>הנזיר . . מרכבה . . שלמעלה . . ח\"ע</b>: ראה גם בהקיצור כאן. סה\"מ תרל\"ח ס\"ע נז. וש\"נ."],["4530","95","<b>כל קדושה בשערא תלייא</b>: זהר תזריע מח, ב."],["4531","96","<b>הכהן . . רב חסד דעתיקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380531\" data-slug=\"likkutei-torah\" data-id=\"4001380531\">לקו\"ת קרח נד, ב</a> (רב חסד — ראה בהקיצור כאן). יו\"כ עא, ד (כה\"ג). מאמרי אדה\"א ויקרא ח\"ב ע' תקיט. וש\"נ. בראשית ע' כד. וש\"נ."],["4532","97","<b>עמל שיחה</b>: סנהדרין צט, ב. ראה גם מאמרי אדה\"א נ\"ך ס\"ע תק ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670071\" data-slug=\"torat-chaim\" data-id=\"2300670071\">תו\"ח בראשית א, ד</a> ואילך. ח\"ש קלג, סע\"ב."],["4533","98","<b>במאמר ויקח המן</b>: הנחת ר' הלל — מפורים תר\"י. ראה רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ שנת הנ\"ל ע' פג. ויודפס בע\"ה בסדרת ספריו פלח הרמון."],["e4","*","אמור כא, ה ופאת זקנם."],["e5","**","ביחזקאל מד, כ וראשם לא יגלחו ופרע לא ישלחו כסום יכסמו את ראשיהם."],["e6","***","ראה רש\"י בחידושי הר\"ן() ספ\"ב דסנהדרין [הובא גם בשו\"ת הצ\"צ ליו\"ד סצ\"ג, סי\"ז. שם בסופו ד\"ה ועוד ראי']. לקוטי תוס' שאנץ ותוספת הרא\"ש שם. מהר\"י קורקוס לרמב\"ם הל' כלי המקדש פ\"ה, ה\"ו (ובשם רש\"י)."]]],[2001910443,"בתכלית הקדושה וכל קדושה נמשך מהם ולכן צריכים לימוד כי מהם נמשך ביטול דח\"ע כח מ\"ה<sup data-n=\"4534\">99</sup> כו'.\n<b>קיצור</b><sup data-n=\"4535\">100</sup> ה), ועפ\"ז יובן ענין שיחת חולין של ת\"ח צריכים לימוד, דהנה מצינו ששער באשה ערוה, ומצינו שיש קדושה בשערות כמו בנזיר וכהנים, והענין הוא ששערות הם אותיות, ואותיות דע\"מ להיות כי מתפשטים למטה מטה עד שגם סט\"א מקבלת חיותם מהם לכן נק' שער שבאשה יראת ה' הוא בחי' מל' בשם שער באשה ערוה שמתפשט להשפיע חיות גם להם כו', אך הנזיר להיותו מרכבה לבחי' א\"א שלמעלה מהחכ' אשר משם א\"א להיות ההשפעה כ\"א ע\"י שערות לבד לכן קדושה תלוי בשערא דוקא, וכן כהנים מרכבה לרב חסד צ\"ל כסום יכסמו את ראשיהם<sup data-n=\"4536\">101</sup>, משא\"כ בלוים קו השמאל והעבירו תער כו', ולפ\"ז יובן פי' שיחת חולין דהיינו עמל שיחה דעש\"מ, של ת\"ח שמקבלים מבחי' חכ' ונק' איתן כמ\"ש במ\"א, הוא מעלה אותם לשרשם שערות שלמעלה מהחכ' שבהם קדושה תלוי', לכן צריכין לימוד שמשם נמשך חכ' ע\"י שערות כו' דאבא יונק ממזלא<sup data-n=\"4537\">102</sup> כו'.\nוא\"ו) <b>והנה</b> ע\"י התיקון דששת ימים שהו\"ע בירור הניצוצי' מנוגה בכל וא\"ו ימי החול עי\"ז כשמתעלין אח\"כ למעלה בקדושת האצי' בשבת אזי המתברר עולה למעלה<sup data-n=\"4538\">103</sup><sup data-n=\"4539\">104</sup> בבחי' תענוה\"ע הפשוט שלמעלה הרבה מן החכ' שהוא בחי' אני ראשון כנ\"ל וממשיכים אותו בח\"ע הנק' ראשית כנ\"ל ואז נעשה בחי' השבת בחי' דכר ומשפיע כו'. וע\"ז<sup data-n=\"4540\">105</sup> יובן המד\"ר לעבדה כמד\"א ששת ימים תעבוד שזהו מכלל מצות שבת, כי ע\"י תיקון הששת ימים נעשה בחי' השבת כו', וזהו זכור בקמץ מל' דכר ומשפיע היינו שתעשה אותו בבחי' דכר במה שתמשיך בו בחי' אני ראשון שלמעלה מראשית דחכמה בחי' נוק' כו' ועי\"ז נעשה בחי' דכר ומשפיע כו', משא\"כ אם הי' אומר זכור בשוא לא הי' ממשמעותו רק ענין הזכרון שהו\"ע העלי' לבחי' קודש דח\"ע (כידוע דבחי' זכרון הוא בעלי' לחכ'<sup data-n=\"4541\">106</sup> ולכן בפ' קדש שהוא בח\"ע נא' ולזכרון בין עיניך<sup data-n=\"4542\">107</sup> כו'), והוא בחי' שבת תתאה, משא\"כ כשאומר זכור בקמץ כולל ב' הפי' לשון זכירה ול' זכר משפיע וממילא הוא רומז גם על בחי' דשבת עילאה שהוא בחי' המשכת מל' דא\"ס המלובש בכת\"ע וחכ\"ע, וגם הקמץ הוא בכתר<sup data-n=\"4543\">108</sup> כידוע).",[["4534","99","<b>דח\"ע כח מ\"ה</b>: ראה זהר רע\"מ צו כח, א. לד, א."],["4535","100","<b>קיצור</b>: תיבה זו ניתוספה ע\"י המו\"ל — ראה לעיל הערה 1."],["4536","101","<b>כסום יכסמו את ראשיהם</b>: יחזקאל מד, כ. ראה לעיל הערה 89."],["4537","102","<b>דאבא יונק ממזלא</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540755\" data-slug=\"torat-chaim\" data-id=\"2300540755\">תו\"ח שמות ח\"א לו, א</a> הערה 455."],["4538","103","<b>המתברר עולה למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">לקו\"ת בחוקותי מז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540240\" data-slug=\"torat-chaim\" data-id=\"2300540240\">תו\"ח וארא ח\"א ע, ג</a>. וש\"נ."],["4539","104","<b>למעלה</b>: ה ניתוסף: מן המתברר ועולין למעלה."],["4540","105","<b>וע\"ז</b>: ה: (ועם זה. סיום הסוגר הוא בסוף הפרק."],["4541","106","<b>זכרון . . לחכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380303\" data-slug=\"likkutei-torah\" data-id=\"4001380303\">לקו\"ת</a> הוספות ויקרא נב, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540083\" data-slug=\"torat-chaim\" data-id=\"2300540083\">תו\"ח שמות ח\"א כג, ד</a>. וש\"נ. סה\"מ תר\"ם ח\"א ס\"ע נח. וש\"נ."],["4542","107","<b>ולזכרון בין עיניך</b>: בא יג, ט."],["4543","108","<b>הקמץ הוא בכתר</b>: ראה ת\"ז ת\"ע קכט, ב. ע\"ח שער השמות שער מ\"ד, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550226\" data-slug=\"torat-chaim\" data-id=\"2300550226\">תו\"ח ויקהל ח\"ב שפז, ד</a>. וש\"נ."]]]]});
